-- Read-aloud speeches: 25 of them, N5, N4, N3, N2, N1.
--
-- Generated by `pnpm -C nihongo/backend seed:readings` from
-- backend/src/pipeline/data/readings. Do not edit: change the data and generate
-- a new seed.
--
-- Every speech arrives UNPUBLISHED with a pending row in the admin review queue.
-- Approving it there is the only thing that publishes it.
--
-- Idempotent: nothing here overwrites an existing speech, its lines, or a
-- review decision already made.

-- N5 · n5-about-me · About me
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n5-about-me', 'lang-ja', ll.id, 'n5-about-me', 'じこしょうかい', 'About me', false, 0
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-about-me-l0', 'rdg-ja-n5-about-me', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-about-me-l1', 'rdg-ja-n5-about-me', 1, 0, 'わたしの名前は山本です。', 'わたし の なまえ わ やまもと です。', '[{"t":"わたし"},{"t":"の"},{"t":"名前","r":"なまえ"},{"t":"は"},{"t":"山本","r":"やまもと"},{"t":"です"},{"t":"。"}]'::jsonb, 'My name is Yamamoto.'),
  ('rdg-ja-n5-about-me-l2', 'rdg-ja-n5-about-me', 2, 1, 'わたしは二十五さいです。', 'わたし わ にじゅうご さい です。', '[{"t":"わたし"},{"t":"は"},{"t":"二十五","r":"にじゅうご"},{"t":"さい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I am twenty-five years old.'),
  ('rdg-ja-n5-about-me-l3', 'rdg-ja-n5-about-me', 3, 1, '外国から来ました。', 'がいこく から きました。', '[{"t":"外国","r":"がいこく"},{"t":"から"},{"t":"来","r":"き"},{"t":"ました"},{"t":"。"}]'::jsonb, 'I came from abroad.'),
  ('rdg-ja-n5-about-me-l4', 'rdg-ja-n5-about-me', 4, 1, '今、日本に住んでいます。', 'いま、にほん に すんで います。', '[{"t":"今","r":"いま"},{"t":"、"},{"t":"日本","r":"にほん"},{"t":"に"},{"t":"住","r":"す"},{"t":"んで"},{"t":"います"},{"t":"。"}]'::jsonb, 'Now I live in Japan.'),
  ('rdg-ja-n5-about-me-l5', 'rdg-ja-n5-about-me', 5, 2, '会社で働いています。', 'かいしゃ で はたらいて います。', '[{"t":"会社","r":"かいしゃ"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"いて"},{"t":"います"},{"t":"。"}]'::jsonb, 'I work at a company.'),
  ('rdg-ja-n5-about-me-l6', 'rdg-ja-n5-about-me', 6, 2, '毎日、電車で行きます。', 'まいにち、でんしゃ で いきます。', '[{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"電車","r":"でんしゃ"},{"t":"で"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb, 'Every day I go by train.'),
  ('rdg-ja-n5-about-me-l7', 'rdg-ja-n5-about-me', 7, 3, '音楽が好きです。', 'おんがく が すき です。', '[{"t":"音楽","r":"おんがく"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I like music.'),
  ('rdg-ja-n5-about-me-l8', 'rdg-ja-n5-about-me', 8, 3, 'それから、犬も好きです。', 'それから、いぬ も すき です。', '[{"t":"それから"},{"t":"、"},{"t":"犬","r":"いぬ"},{"t":"も"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'And I like dogs too.'),
  ('rdg-ja-n5-about-me-l9', 'rdg-ja-n5-about-me', 9, 3, '家に白い犬がいます。', 'いえ に しろい いぬ が います。', '[{"t":"家","r":"いえ"},{"t":"に"},{"t":"白","r":"しろ"},{"t":"い"},{"t":"犬","r":"いぬ"},{"t":"が"},{"t":"います"},{"t":"。"}]'::jsonb, 'I have a white dog at home.'),
  ('rdg-ja-n5-about-me-l10', 'rdg-ja-n5-about-me', 10, 4, '日本語、まだあまり上手じゃありません。', 'にほんご、まだ あまり じょうず じゃ ありません。', '[{"t":"日本語","r":"にほんご"},{"t":"、"},{"t":"まだ"},{"t":"あまり"},{"t":"上手","r":"じょうず"},{"t":"じゃありません"},{"t":"。"}]'::jsonb, 'My Japanese isn’t very good yet.'),
  ('rdg-ja-n5-about-me-l11', 'rdg-ja-n5-about-me', 11, 4, 'でも、毎日、勉強します。', 'でも、まいにち、べんきょう します。', '[{"t":"でも"},{"t":"、"},{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"勉強","r":"べんきょう"},{"t":"します"},{"t":"。"}]'::jsonb, 'But I study every day.'),
  ('rdg-ja-n5-about-me-l12', 'rdg-ja-n5-about-me', 12, 5, 'みなさんと話したいです。', 'みなさん と はなしたい です。', '[{"t":"みなさん"},{"t":"と"},{"t":"話","r":"はな"},{"t":"したい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I want to talk with all of you.'),
  ('rdg-ja-n5-about-me-l13', 'rdg-ja-n5-about-me', 13, 5, 'どうぞ、よろしく。', 'どうぞ、よろしく。', '[{"t":"どうぞ"},{"t":"、"},{"t":"よろしく"},{"t":"。"}]'::jsonb, 'Nice to meet you all.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-about-me')
ON CONFLICT (reading_id, index) DO NOTHING;

INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, origin, priority, status)
SELECT 'crq-rdg-ja-n5-about-me', 'lang-ja', 'readings', 'rdg-ja-n5-about-me', 'create', '{"code":"n5-about-me","level":"N5"}'::jsonb, 'ai', 1, 'pending'
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-about-me' AND NOT published)
  AND NOT EXISTS (SELECT 1 FROM content_review_queue WHERE target_table = 'readings' AND target_id = 'rdg-ja-n5-about-me')
ON CONFLICT DO NOTHING;

-- N5 · n5-my-day · My day
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n5-my-day', 'lang-ja', ll.id, 'n5-my-day', 'わたしの一日', 'My day', false, 1
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-my-day-l0', 'rdg-ja-n5-my-day', 0, 0, '朝、六時に起きます。', 'あさ、ろくじ に おきます。', '[{"t":"朝","r":"あさ"},{"t":"、"},{"t":"六時","r":"ろくじ"},{"t":"に"},{"t":"起","r":"お"},{"t":"きます"},{"t":"。"}]'::jsonb, 'In the morning, I get up at six.'),
  ('rdg-ja-n5-my-day-l1', 'rdg-ja-n5-my-day', 1, 0, 'はじめに、水を飲みます。', 'はじめに、みず お のみます。', '[{"t":"はじめに"},{"t":"、"},{"t":"水","r":"みず"},{"t":"を"},{"t":"飲","r":"の"},{"t":"みます"},{"t":"。"}]'::jsonb, 'First, I drink water.'),
  ('rdg-ja-n5-my-day-l2', 'rdg-ja-n5-my-day', 2, 0, 'それから、顔を洗います。', 'それから、かお お あらいます。', '[{"t":"それから"},{"t":"、"},{"t":"顔","r":"かお"},{"t":"を"},{"t":"洗","r":"あら"},{"t":"います"},{"t":"。"}]'::jsonb, 'Then I wash my face.'),
  ('rdg-ja-n5-my-day-l3', 'rdg-ja-n5-my-day', 3, 1, '七時に朝ごはんを食べます。', 'しちじ に あさごはん お たべます。', '[{"t":"七時","r":"しちじ"},{"t":"に"},{"t":"朝","r":"あさ"},{"t":"ごはん"},{"t":"を"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'I eat breakfast at seven.'),
  ('rdg-ja-n5-my-day-l4', 'rdg-ja-n5-my-day', 4, 1, 'パンとくだものを食べます。', 'パン と くだもの お たべます。', '[{"t":"パン"},{"t":"と"},{"t":"くだもの"},{"t":"を"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'I eat bread and fruit.'),
  ('rdg-ja-n5-my-day-l5', 'rdg-ja-n5-my-day', 5, 2, '八時に家を出ます。', 'はちじ に いえ お でます。', '[{"t":"八時","r":"はちじ"},{"t":"に"},{"t":"家","r":"いえ"},{"t":"を"},{"t":"出","r":"で"},{"t":"ます"},{"t":"。"}]'::jsonb, 'I leave the house at eight.'),
  ('rdg-ja-n5-my-day-l6', 'rdg-ja-n5-my-day', 6, 2, 'バスで学校へ行きます。', 'バス で がっこう え いきます。', '[{"t":"バス"},{"t":"で"},{"t":"学校","r":"がっこう"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb, 'I go to school by bus.'),
  ('rdg-ja-n5-my-day-l7', 'rdg-ja-n5-my-day', 7, 3, '昼ごはんは友だちと食べます。', 'ひるごはん わ ともだち と たべます。', '[{"t":"昼","r":"ひる"},{"t":"ごはん"},{"t":"は"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb, 'I eat lunch with friends.'),
  ('rdg-ja-n5-my-day-l8', 'rdg-ja-n5-my-day', 8, 3, '午後も勉強します。', 'ごご も べんきょう します。', '[{"t":"午後","r":"ごご"},{"t":"も"},{"t":"勉強","r":"べんきょう"},{"t":"します"},{"t":"。"}]'::jsonb, 'I study in the afternoon too.'),
  ('rdg-ja-n5-my-day-l9', 'rdg-ja-n5-my-day', 9, 4, '五時に家へ帰ります。', 'ごじ に いえ え かえります。', '[{"t":"五時","r":"ごじ"},{"t":"に"},{"t":"家","r":"いえ"},{"t":"へ"},{"t":"帰","r":"かえ"},{"t":"ります"},{"t":"。"}]'::jsonb, 'I go home at five.'),
  ('rdg-ja-n5-my-day-l10', 'rdg-ja-n5-my-day', 10, 4, '夜は、料理を作ります。', 'よる わ、りょうり お つくります。', '[{"t":"夜","r":"よる"},{"t":"は"},{"t":"、"},{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"作","r":"つく"},{"t":"ります"},{"t":"。"}]'::jsonb, 'In the evening I cook dinner.'),
  ('rdg-ja-n5-my-day-l11', 'rdg-ja-n5-my-day', 11, 5, '十一時にねます。', 'じゅういちじ に ねます。', '[{"t":"十一時","r":"じゅういちじ"},{"t":"に"},{"t":"ねます"},{"t":"。"}]'::jsonb, 'I go to bed at eleven.'),
  ('rdg-ja-n5-my-day-l12', 'rdg-ja-n5-my-day', 12, 5, 'おやすみなさい。', 'おやすみなさい。', '[{"t":"おやすみなさい"},{"t":"。"}]'::jsonb, 'Good night.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n5-my-day')
ON CONFLICT (reading_id, index) DO NOTHING;

