SELECT v.* FROM (VALUES
  ('rdg-ja-n5-my-family-l0', 'rdg-ja-n5-my-family', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n5-my-family-l1', 'rdg-ja-n5-my-family', 1, 0, '今日は、家族のことを話します。', 'きょう わ、かぞく の こと お はなします。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"家族","r":"かぞく"},{"t":"の"},{"t":"こと"},{"t":"を"},{"t":"話","r":"はな"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about my family.'),
  ('rdg-ja-n5-my-family-l2', 'rdg-ja-n5-my-family', 2, 1, 'わたしの家族は五人です。', 'わたし の かぞく わ ごにん です。', '[{"t":"わたし"},{"t":"の"},{"t":"家族","r":"かぞく"},{"t":"は"},{"t":"五人","r":"ごにん"},{"t":"です"},{"t":"。"}]'::jsonb, 'There are five people in my family.'),
  ('rdg-ja-n5-my-family-l3', 'rdg-ja-n5-my-family', 3, 1, '父と母と姉と弟とわたしです。', 'ちち と はは と あね と おとうと と わたし です。', '[{"t":"父","r":"ちち"},{"t":"と"},{"t":"母","r":"はは"},{"t":"と"},{"t":"姉","r":"あね"},{"t":"と"},{"t":"弟","r":"おとうと"},{"t":"と"},{"t":"わたし"},{"t":"です"},{"t":"。"}]'::jsonb, 'My father, mother, older sister, younger brother and me.'),
  ('rdg-ja-n5-my-family-l4', 'rdg-ja-n5-my-family', 4, 2, '父は先生です。', 'ちち わ せんせい です。', '[{"t":"父","r":"ちち"},{"t":"は"},{"t":"先生","r":"せんせい"},{"t":"です"},{"t":"。"}]'::jsonb, 'My father is a teacher.'),
  ('rdg-ja-n5-my-family-l5', 'rdg-ja-n5-my-family', 5, 2, '少しこわいですが、やさしいです。', 'すこし こわい です が、やさしい です。', '[{"t":"少","r":"すこ"},{"t":"し"},{"t":"こわい"},{"t":"です"},{"t":"が"},{"t":"、"},{"t":"やさしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'He is a little scary, but kind.'),
  ('rdg-ja-n5-my-family-l6', 'rdg-ja-n5-my-family', 6, 3, '母は料理が上手です。', 'はは わ りょうり が じょうず です。', '[{"t":"母","r":"はは"},{"t":"は"},{"t":"料理","r":"りょうり"},{"t":"が"},{"t":"上手","r":"じょうず"},{"t":"です"},{"t":"。"}]'::jsonb, 'My mother is good at cooking.'),
  ('rdg-ja-n5-my-family-l7', 'rdg-ja-n5-my-family', 7, 3, 'とてもおいしいです。', 'とても おいしい です。', '[{"t":"とても"},{"t":"おいしい"},{"t":"です"},{"t":"。"}]'::jsonb, 'It’s really delicious.'),
  ('rdg-ja-n5-my-family-l8', 'rdg-ja-n5-my-family', 8, 4, '姉は大学生です。', 'あね わ だいがくせい です。', '[{"t":"姉","r":"あね"},{"t":"は"},{"t":"大学生","r":"だいがくせい"},{"t":"です"},{"t":"。"}]'::jsonb, 'My older sister is a university student.'),
  ('rdg-ja-n5-my-family-l9', 'rdg-ja-n5-my-family', 9, 4, '毎日、とても忙しいです。', 'まいにち、とても いそがしい です。', '[{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"とても"},{"t":"忙","r":"いそが"},{"t":"しい"},{"t":"です"},{"t":"。"}]'::jsonb, 'She is very busy every day.'),
  ('rdg-ja-n5-my-family-l10', 'rdg-ja-n5-my-family', 10, 5, '弟は十さいです。', 'おとうと わ じゅっさい です。', '[{"t":"弟","r":"おとうと"},{"t":"は"},{"t":"十","r":"じゅっ"},{"t":"さい"},{"t":"です"},{"t":"。"}]'::jsonb, 'My younger brother is ten years old.'),
  ('rdg-ja-n5-my-family-l11', 'rdg-ja-n5-my-family', 11, 5, '走るのが好きです。', 'はしる の が すき です。', '[{"t":"走","r":"はし"},{"t":"る"},{"t":"の"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'He likes running.'),
  ('rdg-ja-n5-my-family-l12', 'rdg-ja-n5-my-family', 12, 6, 'みんな、わたしの大切な家族です。', 'みんな、わたし の たいせつな かぞく です。', '[{"t":"みんな"},{"t":"、"},{"t":"わたし"},{"t":"の"},{"t":"大切","r":"たいせつ"},{"t":"な"},{"t":"家族","r":"かぞく"},{"t":"です"},{"t":"。"}]'::jsonb, 'They are all my precious family.'),
  ('rdg-ja-n5-my-family-l13', 'rdg-ja-n5-my-family', 13, 6, 'ありがとうございました。', 'ありがとう ございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
