INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n5-my-room-l0', 'rdg-ja-n5-my-room', 0, 0, 'これはわたしの部屋です。', 'これ わ わたし の へや です。', '[{"t":"これは"},{"t":"わたし"},{"t":"の"},{"t":"部屋","r":"へや"},{"t":"です"},{"t":"。"}]'::jsonb, 'This is my room.'),
  ('rdg-ja-n5-my-room-l1', 'rdg-ja-n5-my-room', 1, 0, '小さいですが、新しいです。', 'ちいさい です が、あたらしい です。', '[{"t":"小","r":"ちい"},{"t":"さい"},{"t":"です"},{"t":"が"},{"t":"、"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"です"},{"t":"。"}]'::jsonb, 'It is small, but new.'),
  ('rdg-ja-n5-my-room-l2', 'rdg-ja-n5-my-room', 2, 1, 'ドアの右にベッドがあります。', 'ドア の みぎ に ベッド が あります。', '[{"t":"ドア"},{"t":"の"},{"t":"右","r":"みぎ"},{"t":"に"},{"t":"ベッド"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a bed to the right of the door.'),
  ('rdg-ja-n5-my-room-l3', 'rdg-ja-n5-my-room', 3, 1, 'ベッドの上に本があります。', 'ベッド の うえ に ほん が あります。', '[{"t":"ベッド"},{"t":"の"},{"t":"上","r":"うえ"},{"t":"に"},{"t":"本","r":"ほん"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a book on the bed.'),
  ('rdg-ja-n5-my-room-l4', 'rdg-ja-n5-my-room', 4, 2, '窓の下につくえがあります。', 'まど の した に つくえ が あります。', '[{"t":"窓","r":"まど"},{"t":"の"},{"t":"下","r":"した"},{"t":"に"},{"t":"つくえ"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a desk under the window.'),
  ('rdg-ja-n5-my-room-l5', 'rdg-ja-n5-my-room', 5, 2, 'つくえの上にパソコンがあります。', 'つくえ の うえ に パソコン が あります。', '[{"t":"つくえ"},{"t":"の"},{"t":"上","r":"うえ"},{"t":"に"},{"t":"パソコン"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a computer on the desk.'),
  ('rdg-ja-n5-my-room-l6', 'rdg-ja-n5-my-room', 6, 2, '毎日、つくえで勉強します。', 'まいにち、つくえ で べんきょう します。', '[{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"つくえ"},{"t":"で"},{"t":"勉強","r":"べんきょう"},{"t":"します"},{"t":"。"}]'::jsonb, 'I study at the desk every day.'),
  ('rdg-ja-n5-my-room-l7', 'rdg-ja-n5-my-room', 7, 3, 'つくえの前にテレビがあります。', 'つくえ の まえ に テレビ が あります。', '[{"t":"つくえ"},{"t":"の"},{"t":"前","r":"まえ"},{"t":"に"},{"t":"テレビ"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a TV in front of the desk.'),
  ('rdg-ja-n5-my-room-l8', 'rdg-ja-n5-my-room', 8, 3, 'テレビの後ろに大きい箱があります。', 'テレビ の うしろ に おおきい はこ が あります。', '[{"t":"テレビ"},{"t":"の"},{"t":"後","r":"うし"},{"t":"ろ"},{"t":"に"},{"t":"大","r":"おお"},{"t":"きい"},{"t":"箱","r":"はこ"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There is a big box behind the TV.'),
