  ('rdg-ja-n5-my-weekend-l3', 'rdg-ja-n5-my-weekend', 3, 1, 'そして、部屋をそうじしました。', 'そして、へや お そうじ しました。', '[{"t":"そして"},{"t":"、"},{"t":"部屋","r":"へや"},{"t":"を"},{"t":"そうじ"},{"t":"しました"},{"t":"。"}]'::jsonb, 'Then I cleaned my room.'),
  ('rdg-ja-n5-my-weekend-l4', 'rdg-ja-n5-my-weekend', 4, 2, '午後は友だちに会いました。', 'ごご わ ともだち に あいました。', '[{"t":"午後","r":"ごご"},{"t":"は"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"に"},{"t":"会","r":"あ"},{"t":"いました"},{"t":"。"}]'::jsonb, 'In the afternoon I met a friend.'),
  ('rdg-ja-n5-my-weekend-l5', 'rdg-ja-n5-my-weekend', 5, 2, '二人で買い物に行きました。', 'ふたり で かいもの に いきました。', '[{"t":"二人","r":"ふたり"},{"t":"で"},{"t":"買","r":"か"},{"t":"い"},{"t":"物","r":"もの"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'The two of us went shopping.'),
  ('rdg-ja-n5-my-weekend-l6', 'rdg-ja-n5-my-weekend', 6, 2, '新しい本を買いました。', 'あたらしい ほん お かいました。', '[{"t":"新","r":"あたら"},{"t":"しい"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"買","r":"か"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I bought a new book.'),
  ('rdg-ja-n5-my-weekend-l7', 'rdg-ja-n5-my-weekend', 7, 3, '夜は友だちと映画を見ました。', 'よる わ ともだち と えいが お みました。', '[{"t":"夜","r":"よる"},{"t":"は"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"映画","r":"えいが"},{"t":"を"},{"t":"見","r":"み"},{"t":"ました"},{"t":"。"}]'::jsonb, 'At night I watched a movie with a friend.'),
  ('rdg-ja-n5-my-weekend-l8', 'rdg-ja-n5-my-weekend', 8, 3, 'とても面白かったです。', 'とても おもしろかった です。', '[{"t":"とても"},{"t":"面白","r":"おもしろ"},{"t":"かった"},{"t":"です"},{"t":"。"}]'::jsonb, 'It was really fun.'),
  ('rdg-ja-n5-my-weekend-l9', 'rdg-ja-n5-my-weekend', 9, 4, '日曜日は家にいました。', 'にちようび わ いえ に いました。', '[{"t":"日曜日","r":"にちようび"},{"t":"は"},{"t":"家","r":"いえ"},{"t":"に"},{"t":"いました"},{"t":"。"}]'::jsonb, 'On Sunday I stayed home.'),
  ('rdg-ja-n5-my-weekend-l10', 'rdg-ja-n5-my-weekend', 10, 4, '本を読んで、お茶を飲みました。', 'ほん お よんで、おちゃ お のみました。', '[{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"んで"},{"t":"、"},{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"を"},{"t":"飲","r":"の"},{"t":"みました"},{"t":"。"}]'::jsonb, 'I read a book and drank tea.'),
