INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-my-dream-l0', 'rdg-ja-n4-my-dream', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-my-dream-l1', 'rdg-ja-n4-my-dream', 1, 0, '私の夢は、日本で働くことです。', 'わたし の ゆめ わ、にほん で はたらく こと です。', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"夢","r":"ゆめ"},{"t":"は"},{"t":"、"},{"t":"日本","r":"にほん"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"く"},{"t":"こと"},{"t":"です"},{"t":"。"}]'::jsonb, 'My dream is to work in Japan.'),
  ('rdg-ja-n4-my-dream-l2', 'rdg-ja-n4-my-dream', 2, 0, '今日は、夢について話します。', 'きょう わ、ゆめ に ついて はなします。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"夢","r":"ゆめ"},{"t":"について"},{"t":"話","r":"はな"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about my dream.'),
  ('rdg-ja-n4-my-dream-l3', 'rdg-ja-n4-my-dream', 3, 1, '子どものとき、テレビで日本の町を見ました。', 'こども の とき、テレビ で にほん の まち お みました。', '[{"t":"子","r":"こ"},{"t":"ども"},{"t":"の"},{"t":"とき"},{"t":"、"},{"t":"テレビ"},{"t":"で"},{"t":"日本","r":"にほん"},{"t":"の"},{"t":"町","r":"まち"},{"t":"を"},{"t":"見","r":"み"},{"t":"ました"},{"t":"。"}]'::jsonb, 'When I was a child, I saw a Japanese town on television.'),
  ('rdg-ja-n4-my-dream-l4', 'rdg-ja-n4-my-dream', 4, 1, '大きなビルと、たくさんの人。', 'おおきな ビル と、たくさん の ひと。', '[{"t":"大","r":"おお"},{"t":"きな"},{"t":"ビル"},{"t":"と"},{"t":"、"},{"t":"たくさん"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"。"}]'::jsonb, 'Big buildings and so many people.'),
  ('rdg-ja-n4-my-dream-l5', 'rdg-ja-n4-my-dream', 5, 1, 'とてもにぎやかな町だと思いました。', 'とても にぎやかな まち だ と おもいました。', '[{"t":"とても"},{"t":"にぎやかな"},{"t":"町","r":"まち"},{"t":"だ"},{"t":"と"},{"t":"思","r":"おも"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I thought it was a very lively town.'),
  ('rdg-ja-n4-my-dream-l6', 'rdg-ja-n4-my-dream', 6, 2, 'あの時から、毎日、日本のことを勉強しています。', 'あの とき から、まいにち、にほん の こと お べんきょう して います。', '[{"t":"あの"},{"t":"時","r":"とき"},{"t":"から"},{"t":"、"},{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"日本","r":"にほん"},{"t":"の"},{"t":"こと"},{"t":"を"},{"t":"勉強","r":"べんきょう"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'Since then, I have studied about Japan every day.'),
  ('rdg-ja-n4-my-dream-l7', 'rdg-ja-n4-my-dream', 7, 2, '朝は、新しいことばをノートに書きます。', 'あさ わ、あたらしい ことば お ノート に かきます。', '[{"t":"朝","r":"あさ"},{"t":"は"},{"t":"、"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"ことば"},{"t":"を"},{"t":"ノート"},{"t":"に"},{"t":"書","r":"か"},{"t":"きます"},{"t":"。"}]'::jsonb, 'In the morning, I write new words in my notebook.'),
  ('rdg-ja-n4-my-dream-l8', 'rdg-ja-n4-my-dream', 8, 2, '夜は、友だちと話します。', 'よる わ、ともだち と はなします。', '[{"t":"夜","r":"よる"},{"t":"は"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"話","r":"はな"},{"t":"します"},{"t":"。"}]'::jsonb, 'At night, I talk with a friend.'),
  ('rdg-ja-n4-my-dream-l9', 'rdg-ja-n4-my-dream', 9, 2, 'まだ上手ではありませんが、楽しいです。', 'まだ じょうず で わ ありません が、たのしい です。', '[{"t":"まだ"},{"t":"上手","r":"じょうず"},{"t":"では"},{"t":"ありません"},{"t":"が"},{"t":"、"},{"t":"楽","r":"たの"},{"t":"しい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I''m not good yet, but it is fun.'),
  ('rdg-ja-n4-my-dream-l10', 'rdg-ja-n4-my-dream', 10, 3, '日本に行ったら、会社で働きたいです。', 'にほん に いったら、かいしゃ で はたらきたい です。', '[{"t":"日本","r":"にほん"},{"t":"に"},{"t":"行","r":"い"},{"t":"ったら"},{"t":"、"},{"t":"会社","r":"かいしゃ"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"きたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'If I go to Japan, I want to work at a company.'),
  ('rdg-ja-n4-my-dream-l11', 'rdg-ja-n4-my-dream', 11, 3, '店で、お客さんと話す仕事もしてみたいです。', 'みせ で、おきゃくさん と はなす しごと も して みたい です。', '[{"t":"店","r":"みせ"},{"t":"で"},{"t":"、"},{"t":"お"},{"t":"客","r":"きゃく"},{"t":"さん"},{"t":"と"},{"t":"話","r":"はな"},{"t":"す"},{"t":"仕事","r":"しごと"},{"t":"も"},{"t":"して"},{"t":"みたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I would also like to try a job talking with customers in a shop.'),
  ('rdg-ja-n4-my-dream-l12', 'rdg-ja-n4-my-dream', 12, 3, 'そして、日本の友だちをたくさん作りたいです。', 'そして、にほん の ともだち お たくさん つくりたい です。', '[{"t":"そして"},{"t":"、"},{"t":"日本","r":"にほん"},{"t":"の"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"を"},{"t":"たくさん"},{"t":"作","r":"つく"},{"t":"りたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'And I want to make lots of Japanese friends.'),
  ('rdg-ja-n4-my-dream-l13', 'rdg-ja-n4-my-dream', 13, 4, '夢はまだ遠いですが、毎日、勉強します。', 'ゆめ わ まだ とおい です が、まいにち、べんきょう します。', '[{"t":"夢","r":"ゆめ"},{"t":"は"},{"t":"まだ"},{"t":"遠","r":"とお"},{"t":"い"},{"t":"です"},{"t":"が"},{"t":"、"},{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"勉強","r":"べんきょう"},{"t":"します"},{"t":"。"}]'::jsonb, 'My dream is still far away, but I study every day.'),
  ('rdg-ja-n4-my-dream-l14', 'rdg-ja-n4-my-dream', 14, 4, '少しずつ、前に進みます。', 'すこし ずつ、まえ に すすみます。', '[{"t":"少","r":"すこ"},{"t":"し"},{"t":"ずつ"},{"t":"、"},{"t":"前","r":"まえ"},{"t":"に"},{"t":"進","r":"すす"},{"t":"みます"},{"t":"。"}]'::jsonb, 'I will move forward one step at a time.'),
  ('rdg-ja-n4-my-dream-l15', 'rdg-ja-n4-my-dream', 15, 4, '私の話は、これで終わります。', 'わたし の はなし わ、これ で おわります。', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"は"},{"t":"、"},{"t":"これ"},{"t":"で"},{"t":"終","r":"お"},{"t":"わります"},{"t":"。"}]'::jsonb, 'That is the end of my talk.'),
