INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-my-hometown-l0', 'rdg-ja-n4-my-hometown', 0, 0, 'はじめまして。', 'はじめまして。', '[{"t":"はじめまして"},{"t":"。"}]'::jsonb, 'Nice to meet you.'),
  ('rdg-ja-n4-my-hometown-l1', 'rdg-ja-n4-my-hometown', 1, 0, '私のふるさとについて話します。', 'わたし の ふるさと に ついて はなします。', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"ふるさと"},{"t":"について"},{"t":"話","r":"はな"},{"t":"します"},{"t":"。"}]'::jsonb, 'I will tell you about my hometown.'),
  ('rdg-ja-n4-my-hometown-l2', 'rdg-ja-n4-my-hometown', 2, 0, '小さい町ですが、大好きな所です。', 'ちいさい まち です が、だいすきな ところ です。', '[{"t":"小","r":"ちい"},{"t":"さい"},{"t":"町","r":"まち"},{"t":"です"},{"t":"が"},{"t":"、"},{"t":"大好","r":"だいす"},{"t":"き"},{"t":"な"},{"t":"所","r":"ところ"},{"t":"です"},{"t":"。"}]'::jsonb, 'It''s a small town, but a place I love.'),
  ('rdg-ja-n4-my-hometown-l3', 'rdg-ja-n4-my-hometown', 3, 1, '町の近くに、大きな山があります。', 'まち の ちかく に、おおきな やま が あります。', '[{"t":"町","r":"まち"},{"t":"の"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"に"},{"t":"、"},{"t":"大","r":"おお"},{"t":"きな"},{"t":"山","r":"やま"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'Near the town there is a big mountain.'),
  ('rdg-ja-n4-my-hometown-l4', 'rdg-ja-n4-my-hometown', 4, 1, '夏には、よく家族と山へ行きました。', 'なつ に わ、よく かぞく と やま え いきました。', '[{"t":"夏","r":"なつ"},{"t":"に"},{"t":"は"},{"t":"、"},{"t":"よく"},{"t":"家族","r":"かぞく"},{"t":"と"},{"t":"山","r":"やま"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'In summer, I often went there with my family.'),
  ('rdg-ja-n4-my-hometown-l5', 'rdg-ja-n4-my-hometown', 5, 1, '山の上は、風が気持ちよかったです。', 'やま の うえ わ、かぜ が きもち よかった です。', '[{"t":"山","r":"やま"},{"t":"の"},{"t":"上","r":"うえ"},{"t":"は"},{"t":"、"},{"t":"風","r":"かぜ"},{"t":"が"},{"t":"気持","r":"きも"},{"t":"ち"},{"t":"よかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'At the top, the wind felt good.'),
  ('rdg-ja-n4-my-hometown-l6', 'rdg-ja-n4-my-hometown', 6, 2, '町には、古いお寺もあります。', 'まち に わ、ふるい おてら も あります。', '[{"t":"町","r":"まち"},{"t":"に"},{"t":"は"},{"t":"、"},{"t":"古","r":"ふる"},{"t":"い"},{"t":"お"},{"t":"寺","r":"てら"},{"t":"も"},{"t":"あります"},{"t":"。"}]'::jsonb, 'The town also has an old temple.'),
  ('rdg-ja-n4-my-hometown-l7', 'rdg-ja-n4-my-hometown', 7, 2, '毎年、秋に大きなお祭りがあります。', 'まいとし、あき に おおきな おまつり が あります。', '[{"t":"毎年","r":"まいとし"},{"t":"、"},{"t":"秋","r":"あき"},{"t":"に"},{"t":"大","r":"おお"},{"t":"きな"},{"t":"お"},{"t":"祭","r":"まつ"},{"t":"り"},{"t":"が"},{"t":"あります"},{"t":"。"}]'::jsonb, 'Every year in autumn there is a big festival.'),
  ('rdg-ja-n4-my-hometown-l8', 'rdg-ja-n4-my-hometown', 8, 2, 'みんなで歌って、踊ります。', 'みんな で うたって、おどります。', '[{"t":"みんな"},{"t":"で"},{"t":"歌","r":"うた"},{"t":"って"},{"t":"、"},{"t":"踊","r":"おど"},{"t":"ります"},{"t":"。"}]'::jsonb, 'Everyone sings and dances together.'),
  ('rdg-ja-n4-my-hometown-l9', 'rdg-ja-n4-my-hometown', 9, 2, '私も子どものときから、毎年、行っています。', 'わたし も こども の とき から、まいとし、いって います。', '[{"t":"私","r":"わたし"},{"t":"も"},{"t":"子","r":"こ"},{"t":"ども"},{"t":"の"},{"t":"とき"},{"t":"から"},{"t":"、"},{"t":"毎年","r":"まいとし"},{"t":"、"},{"t":"行","r":"い"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'I have gone every year since I was a child.'),
  ('rdg-ja-n4-my-hometown-l10', 'rdg-ja-n4-my-hometown', 10, 3, '町の人は、とても親切です。', 'まち の ひと わ、とても しんせつ です。', '[{"t":"町","r":"まち"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"親切","r":"しんせつ"},{"t":"です"},{"t":"。"}]'::jsonb, 'The people in town are very kind.'),
  ('rdg-ja-n4-my-hometown-l11', 'rdg-ja-n4-my-hometown', 11, 3, '道で会うと、いつも声をかけてくれます。', 'みち で あう と、いつも こえ お かけて くれます。', '[{"t":"道","r":"みち"},{"t":"で"},{"t":"会","r":"あ"},{"t":"う"},{"t":"と"},{"t":"、"},{"t":"いつも"},{"t":"声","r":"こえ"},{"t":"を"},{"t":"かけて"},{"t":"くれます"},{"t":"。"}]'::jsonb, 'When we meet on the street, they always say hello.'),
  ('rdg-ja-n4-my-hometown-l12', 'rdg-ja-n4-my-hometown', 12, 3, '店の人も、私の名前を知っています。', 'みせ の ひと も、わたし の なまえ お しって います。', '[{"t":"店","r":"みせ"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"も"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"名前","r":"なまえ"},{"t":"を"},{"t":"知","r":"し"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'The shop owners know my name too.'),
  ('rdg-ja-n4-my-hometown-l13', 'rdg-ja-n4-my-hometown', 13, 4, '今は大きな町に住んでいます。', 'いま わ おおきな まち に すんで います。', '[{"t":"今","r":"いま"},{"t":"は"},{"t":"大","r":"おお"},{"t":"きな"},{"t":"町","r":"まち"},{"t":"に"},{"t":"住","r":"す"},{"t":"んで"},{"t":"います"},{"t":"。"}]'::jsonb, 'Now I live in a big city.'),
  ('rdg-ja-n4-my-hometown-l14', 'rdg-ja-n4-my-hometown', 14, 4, 'でも、ときどきふるさとを思い出します。', 'でも、ときどき ふるさと お おもいだします。', '[{"t":"でも"},{"t":"、"},{"t":"ときどき"},{"t":"ふるさと"},{"t":"を"},{"t":"思","r":"おも"},{"t":"い"},{"t":"出","r":"だ"},{"t":"します"},{"t":"。"}]'::jsonb, 'But sometimes I remember my hometown.'),
  ('rdg-ja-n4-my-hometown-l15', 'rdg-ja-n4-my-hometown', 15, 4, '来年の春、ひさしぶりに帰る予定です。', 'らいねん の はる、ひさしぶり に かえる よてい です。', '[{"t":"来年","r":"らいねん"},{"t":"の"},{"t":"春","r":"はる"},{"t":"、"},{"t":"ひさしぶり"},{"t":"に"},{"t":"帰","r":"かえ"},{"t":"る"},{"t":"予定","r":"よてい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Next spring, I plan to go back for the first time in a while.'),
  ('rdg-ja-n4-my-hometown-l16', 'rdg-ja-n4-my-hometown', 16, 4, '今から楽しみです。', 'いま から たのしみ です。', '[{"t":"今","r":"いま"},{"t":"から"},{"t":"楽","r":"たの"},{"t":"しみ"},{"t":"です"},{"t":"。"}]'::jsonb, 'I''m already looking forward to it.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n4-my-hometown')
ON CONFLICT (reading_id, index) DO NOTHING;

