INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-favourite-season-l0', 'rdg-ja-n4-favourite-season', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-favourite-season-l1', 'rdg-ja-n4-favourite-season', 1, 0, '四つの季節の中で、私は秋が、一番、好きです。', 'よっつ の きせつ の なか で、わたし わ あき が、いちばん、すき です。', '[{"t":"四","r":"よっ"},{"t":"つ"},{"t":"の"},{"t":"季節","r":"きせつ"},{"t":"の"},{"t":"中","r":"なか"},{"t":"で"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"秋","r":"あき"},{"t":"が"},{"t":"、"},{"t":"一番","r":"いちばん"},{"t":"、"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'Of the four seasons, I like autumn the best.'),
  ('rdg-ja-n4-favourite-season-l2', 'rdg-ja-n4-favourite-season', 2, 0, '理由は、三つあります。', 'りゆう わ、みっつ あります。', '[{"t":"理由","r":"りゆう"},{"t":"は"},{"t":"、"},{"t":"三","r":"みっ"},{"t":"つ"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There are three reasons.'),
  ('rdg-ja-n4-favourite-season-l3', 'rdg-ja-n4-favourite-season', 3, 1, '一つ目は、朝の風が気持ちよいことです。', 'ひとつめ わ、あさ の かぜ が きもち よい こと です。', '[{"t":"一","r":"ひと"},{"t":"つ"},{"t":"目","r":"め"},{"t":"は"},{"t":"、"},{"t":"朝","r":"あさ"},{"t":"の"},{"t":"風","r":"かぜ"},{"t":"が"},{"t":"気持","r":"きも"},{"t":"ち"},{"t":"よい"},{"t":"こと"},{"t":"です"},{"t":"。"}]'::jsonb, 'The first is that the morning breeze feels pleasant.'),
  ('rdg-ja-n4-favourite-season-l4', 'rdg-ja-n4-favourite-season', 4, 1, '夏ほど暑くないし、冬ほど寒くもありません。', 'なつ ほど あつくない し、ふゆ ほど さむく も ありません。', '[{"t":"夏","r":"なつ"},{"t":"ほど"},{"t":"暑","r":"あつ"},{"t":"くないし"},{"t":"、"},{"t":"冬","r":"ふゆ"},{"t":"ほど"},{"t":"寒","r":"さむ"},{"t":"くもありません"},{"t":"。"}]'::jsonb, 'It''s not as hot as summer, and not as cold as winter.'),
  ('rdg-ja-n4-favourite-season-l5', 'rdg-ja-n4-favourite-season', 5, 1, '朝の散歩が、特に楽しいです。', 'あさ の さんぽ が、とくに たのしい です。', '[{"t":"朝","r":"あさ"},{"t":"の"},{"t":"散歩","r":"さんぽ"},{"t":"が"},{"t":"、"},{"t":"特","r":"とく"},{"t":"に"},{"t":"楽","r":"たの"},{"t":"しい"},{"t":"です"},{"t":"。"}]'::jsonb, 'Morning walks are especially fun.'),
  ('rdg-ja-n4-favourite-season-l6', 'rdg-ja-n4-favourite-season', 6, 2, '二つ目は、山の色です。', 'ふたつめ わ、やま の いろ です。', '[{"t":"二","r":"ふた"},{"t":"つ"},{"t":"目","r":"め"},{"t":"は"},{"t":"、"},{"t":"山","r":"やま"},{"t":"の"},{"t":"色","r":"いろ"},{"t":"です"},{"t":"。"}]'::jsonb, 'The second is the colour of the mountains.'),
  ('rdg-ja-n4-favourite-season-l7', 'rdg-ja-n4-favourite-season', 7, 2, '赤や黄色の葉が、たくさん見られます。', 'あか や きいろ の は が、たくさん みられます。', '[{"t":"赤","r":"あか"},{"t":"や"},{"t":"黄色","r":"きいろ"},{"t":"の"},{"t":"葉","r":"は"},{"t":"が"},{"t":"、"},{"t":"たくさん"},{"t":"見","r":"み"},{"t":"られます"},{"t":"。"}]'::jsonb, 'You can see lots of red and yellow leaves.'),
  ('rdg-ja-n4-favourite-season-l8', 'rdg-ja-n4-favourite-season', 8, 2, '去年は、友だちと山へ見に行きました。', 'きょねん わ、ともだち と やま え み に いきました。', '[{"t":"去年","r":"きょねん"},{"t":"は"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"山","r":"やま"},{"t":"へ"},{"t":"見","r":"み"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'Last year I went to see them in the mountains with friends.'),
  ('rdg-ja-n4-favourite-season-l9', 'rdg-ja-n4-favourite-season', 9, 2, '写真をたくさんとりました。', 'しゃしん お たくさん とりました。', '[{"t":"写真","r":"しゃしん"},{"t":"を"},{"t":"たくさん"},{"t":"とりました"},{"t":"。"}]'::jsonb, 'I took a lot of photos.'),
  ('rdg-ja-n4-favourite-season-l10', 'rdg-ja-n4-favourite-season', 10, 3, '三つ目は、おいしい物が多いことです。', 'みっつめ わ、おいしい もの が おおい こと です。', '[{"t":"三","r":"みっ"},{"t":"つ"},{"t":"目","r":"め"},{"t":"は"},{"t":"、"},{"t":"おいしい"},{"t":"物","r":"もの"},{"t":"が"},{"t":"多","r":"おお"},{"t":"い"},{"t":"こと"},{"t":"です"},{"t":"。"}]'::jsonb, 'The third is that there is so much good food.'),
  ('rdg-ja-n4-favourite-season-l11', 'rdg-ja-n4-favourite-season', 11, 3, 'お米も、野菜も、秋が一番おいしいと思います。', 'おこめ も、やさい も、あき が いちばん おいしい と おもいます。', '[{"t":"お"},{"t":"米","r":"こめ"},{"t":"も"},{"t":"、"},{"t":"野菜","r":"やさい"},{"t":"も"},{"t":"、"},{"t":"秋","r":"あき"},{"t":"が"},{"t":"一番","r":"いちばん"},{"t":"おいしい"},{"t":"と"},{"t":"思","r":"おも"},{"t":"います"},{"t":"。"}]'::jsonb, 'I think rice and vegetables both taste best in autumn.'),
  ('rdg-ja-n4-favourite-season-l12', 'rdg-ja-n4-favourite-season', 12, 3, '秋になると、母が料理をたくさん作ってくれます。', 'あき に なる と、はは が りょうり お たくさん つくって くれます。', '[{"t":"秋","r":"あき"},{"t":"に"},{"t":"なる"},{"t":"と"},{"t":"、"},{"t":"母","r":"はは"},{"t":"が"},{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"たくさん"},{"t":"作","r":"つく"},{"t":"って"},{"t":"くれます"},{"t":"。"}]'::jsonb, 'When autumn comes, my mother cooks lots of dishes for me.'),
  ('rdg-ja-n4-favourite-season-l13', 'rdg-ja-n4-favourite-season', 13, 4, '秋は、静かで、やさしい季節です。', 'あき わ、しずか で、やさしい きせつ です。', '[{"t":"秋","r":"あき"},{"t":"は"},{"t":"、"},{"t":"静","r":"しず"},{"t":"か"},{"t":"で"},{"t":"、"},{"t":"やさしい"},{"t":"季節","r":"きせつ"},{"t":"です"},{"t":"。"}]'::jsonb, 'Autumn is a quiet, gentle season.'),
  ('rdg-ja-n4-favourite-season-l14', 'rdg-ja-n4-favourite-season', 14, 4, 'みなさんの好きな季節は、いつですか。', 'みなさん の すきな きせつ わ、いつ です か。', '[{"t":"みなさん"},{"t":"の"},{"t":"好","r":"す"},{"t":"き"},{"t":"な"},{"t":"季節","r":"きせつ"},{"t":"は"},{"t":"、"},{"t":"いつ"},{"t":"です"},{"t":"か"},{"t":"。"}]'::jsonb, 'What is your favourite season?'),
  ('rdg-ja-n4-favourite-season-l15', 'rdg-ja-n4-favourite-season', 15, 4, 'よかったら、教えてください。', 'よかったら、おしえて ください。', '[{"t":"よかったら"},{"t":"、"},{"t":"教","r":"おし"},{"t":"えて"},{"t":"ください"},{"t":"。"}]'::jsonb, 'Please tell me, if you like.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n4-favourite-season')
