INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-happy-day-off-l0', 'rdg-ja-n4-happy-day-off', 0, 0, 'みなさん、休みの日は何をしていますか。', 'みなさん、やすみ の ひ わ なに お して います か。', '[{"t":"みなさん"},{"t":"、"},{"t":"休","r":"やす"},{"t":"み"},{"t":"の"},{"t":"日","r":"ひ"},{"t":"は"},{"t":"何","r":"なに"},{"t":"を"},{"t":"して"},{"t":"います"},{"t":"か"},{"t":"。"}]'::jsonb, 'Everyone, what do you do on your days off?'),
  ('rdg-ja-n4-happy-day-off-l1', 'rdg-ja-n4-happy-day-off', 1, 0, '先週の日曜日は、とても楽しい一日でした。', 'せんしゅう の にちようび わ、とても たのしい いちにち でした。', '[{"t":"先週","r":"せんしゅう"},{"t":"の"},{"t":"日曜日","r":"にちようび"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"楽","r":"たの"},{"t":"しい"},{"t":"一日","r":"いちにち"},{"t":"でした"},{"t":"。"}]'::jsonb, 'Last Sunday was a very enjoyable day.'),
  ('rdg-ja-n4-happy-day-off-l2', 'rdg-ja-n4-happy-day-off', 2, 0, 'あの日のことを話します。', 'あの ひ の こと お はなします。', '[{"t":"あの"},{"t":"日","r":"ひ"},{"t":"の"},{"t":"こと"},{"t":"を"},{"t":"話","r":"はな"},{"t":"します"},{"t":"。"}]'::jsonb, 'Let me tell you about that day.'),
  ('rdg-ja-n4-happy-day-off-l3', 'rdg-ja-n4-happy-day-off', 3, 1, 'いつもは早く起きますが、', 'いつも わ はやく おきます が、', '[{"t":"いつも"},{"t":"は"},{"t":"早","r":"はや"},{"t":"く"},{"t":"起","r":"お"},{"t":"きます"},{"t":"が"},{"t":"、"}]'::jsonb, 'I usually get up early, but'),
  ('rdg-ja-n4-happy-day-off-l4', 'rdg-ja-n4-happy-day-off', 4, 1, '日曜日は九時まで寝ました。', 'にちようび わ くじ まで ねました。', '[{"t":"日曜日","r":"にちようび"},{"t":"は"},{"t":"九時","r":"くじ"},{"t":"まで"},{"t":"寝","r":"ね"},{"t":"ました"},{"t":"。"}]'::jsonb, 'on Sunday I slept until nine.'),
  ('rdg-ja-n4-happy-day-off-l5', 'rdg-ja-n4-happy-day-off', 5, 1, '朝ご飯を食べて、お茶を飲みました。', 'あさごはん お たべて、おちゃ お のみました。', '[{"t":"朝","r":"あさ"},{"t":"ご"},{"t":"飯","r":"はん"},{"t":"を"},{"t":"食","r":"た"},{"t":"べて"},{"t":"、"},{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"を"},{"t":"飲","r":"の"},{"t":"みました"},{"t":"。"}]'::jsonb, 'I ate breakfast and drank tea.'),
  ('rdg-ja-n4-happy-day-off-l6', 'rdg-ja-n4-happy-day-off', 6, 1, 'それから、天気がよかったので、外へ出ました。', 'それから、てんき が よかった ので、そと え でました。', '[{"t":"それから"},{"t":"、"},{"t":"天気","r":"てんき"},{"t":"が"},{"t":"よかった"},{"t":"ので"},{"t":"、"},{"t":"外","r":"そと"},{"t":"へ"},{"t":"出","r":"で"},{"t":"ました"},{"t":"。"}]'::jsonb, 'Then, because the weather was nice, I went outside.'),
  ('rdg-ja-n4-happy-day-off-l7', 'rdg-ja-n4-happy-day-off', 7, 2, '電車に乗って、海へ行きました。', 'でんしゃ に のって、うみ え いきました。', '[{"t":"電車","r":"でんしゃ"},{"t":"に"},{"t":"乗","r":"の"},{"t":"って"},{"t":"、"},{"t":"海","r":"うみ"},{"t":"へ"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'I took a train to the sea.'),
  ('rdg-ja-n4-happy-day-off-l8', 'rdg-ja-n4-happy-day-off', 8, 2, '海のそばで、友だちと昼ご飯を食べました。', 'うみ の そば で、ともだち と ひるごはん お たべました。', '[{"t":"海","r":"うみ"},{"t":"の"},{"t":"そば"},{"t":"で"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"昼","r":"ひる"},{"t":"ご"},{"t":"飯","r":"はん"},{"t":"を"},{"t":"食","r":"た"},{"t":"べました"},{"t":"。"}]'::jsonb, 'By the sea, I ate lunch with a friend.'),
  ('rdg-ja-n4-happy-day-off-l9', 'rdg-ja-n4-happy-day-off', 9, 2, '自分で作ったお弁当は、とてもおいしくできました。', 'じぶん で つくった おべんとう わ、とても おいしく できました。', '[{"t":"自分","r":"じぶん"},{"t":"で"},{"t":"作","r":"つく"},{"t":"った"},{"t":"お"},{"t":"弁当","r":"べんとう"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"おいしく"},{"t":"できました"},{"t":"。"}]'::jsonb, 'The packed lunch I made myself turned out really good.'),
  ('rdg-ja-n4-happy-day-off-l10', 'rdg-ja-n4-happy-day-off', 10, 2, '風が強かったので、帽子がとんでしまいました。', 'かぜ が つよかった ので、ぼうし が とんで しまいました。', '[{"t":"風","r":"かぜ"},{"t":"が"},{"t":"強","r":"つよ"},{"t":"かった"},{"t":"ので"},{"t":"、"},{"t":"帽子","r":"ぼうし"},{"t":"が"},{"t":"とんで"},{"t":"しまいました"},{"t":"。"}]'::jsonb, 'The wind was strong, so my hat blew away.'),
  ('rdg-ja-n4-happy-day-off-l11', 'rdg-ja-n4-happy-day-off', 11, 3, '午後は、本屋で新しい本を買いました。', 'ごご わ、ほんや で あたらしい ほん お かいました。', '[{"t":"午後","r":"ごご"},{"t":"は"},{"t":"、"},{"t":"本屋","r":"ほんや"},{"t":"で"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"買","r":"か"},{"t":"いました"},{"t":"。"}]'::jsonb, 'In the afternoon, I bought a new book at a bookshop.'),
  ('rdg-ja-n4-happy-day-off-l12', 'rdg-ja-n4-happy-day-off', 12, 3, '帰り道で、おいしいケーキも食べました。', 'かえりみち で、おいしい ケーキ も たべました。', '[{"t":"帰","r":"かえ"},{"t":"り"},{"t":"道","r":"みち"},{"t":"で"},{"t":"、"},{"t":"おいしい"},{"t":"ケーキ"},{"t":"も"},{"t":"食","r":"た"},{"t":"べました"},{"t":"。"}]'::jsonb, 'On the way home, I also ate some delicious cake.'),
  ('rdg-ja-n4-happy-day-off-l13', 'rdg-ja-n4-happy-day-off', 13, 3, '家に帰ってから、お風呂に入りました。', 'うち に かえって から、おふろ に はいりました。', '[{"t":"家","r":"うち"},{"t":"に"},{"t":"帰","r":"かえ"},{"t":"って"},{"t":"から"},{"t":"、"},{"t":"お"},{"t":"風呂","r":"ふろ"},{"t":"に"},{"t":"入","r":"はい"},{"t":"りました"},{"t":"。"}]'::jsonb, 'After getting home, I took a bath.'),
  ('rdg-ja-n4-happy-day-off-l14', 'rdg-ja-n4-happy-day-off', 14, 4, '特別なことは何もしませんでした。', 'とくべつな こと わ なにも しませんでした。', '[{"t":"特別","r":"とくべつ"},{"t":"な"},{"t":"こと"},{"t":"は"},{"t":"何","r":"なに"},{"t":"も"},{"t":"しませんでした"},{"t":"。"}]'::jsonb, 'I didn''t do anything special.'),
  ('rdg-ja-n4-happy-day-off-l15', 'rdg-ja-n4-happy-day-off', 15, 4, 'でも、心も体も休めました。', 'でも、こころ も からだ も やすめました。', '[{"t":"でも"},{"t":"、"},{"t":"心","r":"こころ"},{"t":"も"},{"t":"体","r":"からだ"},{"t":"も"},{"t":"休","r":"やす"},{"t":"めました"},{"t":"。"}]'::jsonb, 'But my mind and body both got a rest.'),
  ('rdg-ja-n4-happy-day-off-l16', 'rdg-ja-n4-happy-day-off', 16, 4, '聞いてくれて、ありがとうございました。', 'きいて くれて、ありがとうございました。', '[{"t":"聞","r":"き"},{"t":"いて"},{"t":"くれて"},{"t":"、"},{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you for listening.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
