-- N4 · n4-learning-to-cook · Learning to cook
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n4-learning-to-cook', 'lang-ja', ll.id, 'n4-learning-to-cook', '料理を習う', 'Learning to cook', false, 9
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n4-learning-to-cook-l0', 'rdg-ja-n4-learning-to-cook', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n4-learning-to-cook-l1', 'rdg-ja-n4-learning-to-cook', 1, 0, '三か月前から、料理を習っています。', 'さんかげつ まえ から、りょうり お ならって います。', '[{"t":"三","r":"さん"},{"t":"か"},{"t":"月","r":"げつまえ"},{"t":"前"},{"t":"から"},{"t":"、"},{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"習","r":"なら"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'I have been learning to cook for three months.'),
  ('rdg-ja-n4-learning-to-cook-l2', 'rdg-ja-n4-learning-to-cook', 2, 0, 'それまでは、料理をしたことがありませんでした。', 'それまで わ、りょうり お した こと が ありませんでした。', '[{"t":"それまで"},{"t":"は"},{"t":"、"},{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"した"},{"t":"こと"},{"t":"が"},{"t":"ありませんでした"},{"t":"。"}]'::jsonb, 'Until then, I had never cooked.'),
  ('rdg-ja-n4-learning-to-cook-l3', 'rdg-ja-n4-learning-to-cook', 3, 1, 'いつも店で買った物を食べていました。', 'いつも みせ で かった もの お たべて いました。', '[{"t":"いつも"},{"t":"店","r":"みせ"},{"t":"で"},{"t":"買","r":"か"},{"t":"った"},{"t":"物","r":"もの"},{"t":"を"},{"t":"食","r":"た"},{"t":"べて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I always ate things I bought at shops.'),
  ('rdg-ja-n4-learning-to-cook-l4', 'rdg-ja-n4-learning-to-cook', 4, 1, 'でも、お金もかかるし、体にもよくありません。', 'でも、おかね も かかる し、からだ に も よく ありません。', '[{"t":"でも"},{"t":"、"},{"t":"お"},{"t":"金","r":"かね"},{"t":"も"},{"t":"かかる"},{"t":"し"},{"t":"、"},{"t":"体","r":"からだ"},{"t":"にも"},{"t":"よく"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'But it costs money, and it isn''t good for my body.'),
  ('rdg-ja-n4-learning-to-cook-l5', 'rdg-ja-n4-learning-to-cook', 5, 1, 'それで、自分で作ろうと決めました。', 'それで、じぶん で つくろう と きめました。', '[{"t":"それで"},{"t":"、"},{"t":"自分","r":"じぶん"},{"t":"で"},{"t":"作","r":"つく"},{"t":"ろう"},{"t":"と"},{"t":"決","r":"き"},{"t":"めました"},{"t":"。"}]'::jsonb, 'So I decided to make my own food.'),
  ('rdg-ja-n4-learning-to-cook-l6', 'rdg-ja-n4-learning-to-cook', 6, 2, '最初に作ったのは、肉と野菜のスープです。', 'さいしょ に つくった の わ、にく と やさい の スープ です。', '[{"t":"最初","r":"さいしょ"},{"t":"に"},{"t":"作","r":"つく"},{"t":"った"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"肉","r":"にく"},{"t":"と"},{"t":"野菜","r":"やさい"},{"t":"の"},{"t":"スープ"},{"t":"です"},{"t":"。"}]'::jsonb, 'The first thing I made was a meat and vegetable soup.'),
  ('rdg-ja-n4-learning-to-cook-l7', 'rdg-ja-n4-learning-to-cook', 7, 2, '火が強くて、野菜が黒くなってしまいました。', 'ひ が つよくて、やさい が くろく なって しまいました。', '[{"t":"火","r":"ひ"},{"t":"が"},{"t":"強","r":"つよ"},{"t":"くて"},{"t":"、"},{"t":"野菜","r":"やさい"},{"t":"が"},{"t":"黒","r":"くろ"},{"t":"く"},{"t":"なって"},{"t":"しまいました"},{"t":"。"}]'::jsonb, 'The heat was too high, and the vegetables turned black.'),
  ('rdg-ja-n4-learning-to-cook-l8', 'rdg-ja-n4-learning-to-cook', 8, 2, '味もよくなくて、半分しか食べられませんでした。', 'あじ も よくなくて、はんぶん しか たべられませんでした。', '[{"t":"味","r":"あじ"},{"t":"も"},{"t":"よくなくて"},{"t":"、"},{"t":"半分","r":"はんぶん"},{"t":"しか"},{"t":"食","r":"た"},{"t":"べられませんでした"},{"t":"。"}]'::jsonb, 'It tasted bad too, and I could only eat half.'),
  ('rdg-ja-n4-learning-to-cook-l9', 'rdg-ja-n4-learning-to-cook', 9, 3, '少し悲しかったです。', 'すこし かなしかった です。', '[{"t":"少","r":"すこ"},{"t":"し"},{"t":"悲","r":"かな"},{"t":"しかったです"},{"t":"。"}]'::jsonb, 'I was a little sad.'),
  ('rdg-ja-n4-learning-to-cook-l10', 'rdg-ja-n4-learning-to-cook', 10, 3, 'でも、あとで友だちと笑いました。', 'でも、あとで ともだち と わらいました。', '[{"t":"でも"},{"t":"、"},{"t":"あとで"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"と"},{"t":"笑","r":"わら"},{"t":"いました"},{"t":"。"}]'::jsonb, 'But later I laughed about it with a friend.'),
  ('rdg-ja-n4-learning-to-cook-l11', 'rdg-ja-n4-learning-to-cook', 11, 4, '今は、週に三日、料理教室に通っています。', 'いま わ、しゅう に みっか、りょうり きょうしつ に かよって います。', '[{"t":"今","r":"いま"},{"t":"は"},{"t":"、"},{"t":"週","r":"しゅう"},{"t":"に"},{"t":"三日","r":"みっか"},{"t":"、"},{"t":"料理教室","r":"りょうりきょうしつ"},{"t":"に"},{"t":"通","r":"かよ"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'Now I go to a cooking class three days a week.'),
  ('rdg-ja-n4-learning-to-cook-l12', 'rdg-ja-n4-learning-to-cook', 12, 4, '先生は、包丁の使い方を教えてくれました。', 'せんせい わ、ほうちょう の つかいかた お おしえて くれました。', '[{"t":"先生","r":"せんせい"},{"t":"は"},{"t":"、"},{"t":"包丁","r":"ほうちょう"},{"t":"の"},{"t":"使","r":"つか"},{"t":"い"},{"t":"方","r":"かた"},{"t":"を"},{"t":"教","r":"おし"},{"t":"えて"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'My teacher showed me how to use a knife.'),
  ('rdg-ja-n4-learning-to-cook-l13', 'rdg-ja-n4-learning-to-cook', 13, 4, '少しずつ、上手になっています。', 'すこし ずつ、じょうず に なって います。', '[{"t":"少","r":"すこ"},{"t":"し"},{"t":"ずつ"},{"t":"、"},{"t":"上手","r":"じょうず"},{"t":"に"},{"t":"なって"},{"t":"います"},{"t":"。"}]'::jsonb, 'I am getting better little by little.'),
  ('rdg-ja-n4-learning-to-cook-l14', 'rdg-ja-n4-learning-to-cook', 14, 5, '先週は、友だちを家に呼んで、肉を焼きました。', 'せんしゅう わ、ともだち お うち に よんで、にく お やきました。', '[{"t":"先週","r":"せんしゅう"},{"t":"は"},{"t":"、"},{"t":"友","r":"とも"},{"t":"だち"},{"t":"を"},{"t":"家","r":"うち"},{"t":"に"},{"t":"呼","r":"よ"},{"t":"んで"},{"t":"、"},{"t":"肉","r":"にく"},{"t":"を"},{"t":"焼","r":"や"},{"t":"きました"},{"t":"。"}]'::jsonb, 'Last week I invited friends over and grilled meat.'),
  ('rdg-ja-n4-learning-to-cook-l15', 'rdg-ja-n4-learning-to-cook', 15, 5, '友だちに「おいしい」と言われて、とても嬉しかったです。', 'ともだち に 「おいしい」 と いわれて、とても うれしかった です。', '[{"t":"友","r":"とも"},{"t":"だち"},{"t":"に"},{"t":"「"},{"t":"おいしい"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"われて"},{"t":"、"},{"t":"とても"},{"t":"嬉","r":"うれ"},{"t":"しかったです"},{"t":"。"}]'::jsonb, 'My friends said it was delicious, and I felt really happy.'),
  ('rdg-ja-n4-learning-to-cook-l16', 'rdg-ja-n4-learning-to-cook', 16, 5, 'これからも、毎日、料理をします。', 'これから も、まいにち、りょうり お します。', '[{"t":"これから"},{"t":"も"},{"t":"、"},{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'I''m going to keep cooking every day.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n4-learning-to-cook')
ON CONFLICT (reading_id, index) DO NOTHING;

