-- N3 · n3-trip-gone-wrong · A Trip That Went Wrong
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n3-trip-gone-wrong', 'lang-ja', ll.id, 'n3-trip-gone-wrong', 'うまくいかなかった旅行', 'A Trip That Went Wrong', false, 10
