INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n3-trip-gone-wrong-l0', 'rdg-ja-n3-trip-gone-wrong', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n3-trip-gone-wrong-l1', 'rdg-ja-n3-trip-gone-wrong', 1, 0, '去年の夏、友達と旅行に行きました。', 'きょねん の なつ、ともだち と りょこう に いきました。', '[{"t":"去年","r":"きょねん"},{"t":"の"},{"t":"夏","r":"なつ"},{"t":"、"},{"t":"友達","r":"ともだち"},{"t":"と"},{"t":"旅行","r":"りょこう"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"。"}]'::jsonb, 'Last summer, I went on a trip with a friend.'),
  ('rdg-ja-n3-trip-gone-wrong-l2', 'rdg-ja-n3-trip-gone-wrong', 2, 0, 'でも、思った通りにはいきませんでした。', 'でも、おもった とおり に わ いきませんでした。', '[{"t":"でも"},{"t":"、"},{"t":"思","r":"おも"},{"t":"った"},{"t":"通","r":"とお"},{"t":"り"},{"t":"に"},{"t":"は"},{"t":"いきませんでした"},{"t":"。"}]'::jsonb, 'But it did not go the way I had thought.'),
  ('rdg-ja-n3-trip-gone-wrong-l3', 'rdg-ja-n3-trip-gone-wrong', 3, 1, '朝、駅に着いてから分かりました。', 'あさ、えき に ついて から わかりました。', '[{"t":"朝","r":"あさ"},{"t":"、"},{"t":"駅","r":"えき"},{"t":"に"},{"t":"着","r":"つ"},{"t":"いて"},{"t":"から"},{"t":"分","r":"わ"},{"t":"かりました"},{"t":"。"}]'::jsonb, 'In the morning, after reaching the station, I realized.'),
  ('rdg-ja-n3-trip-gone-wrong-l4', 'rdg-ja-n3-trip-gone-wrong', 4, 1, '切符を家に忘れていたのです。', 'きっぷ お いえ に わすれて いた の です。', '[{"t":"切符","r":"きっぷ"},{"t":"を"},{"t":"家","r":"いえ"},{"t":"に"},{"t":"忘","r":"わす"},{"t":"れて"},{"t":"いた"},{"t":"のです"},{"t":"。"}]'::jsonb, 'I had left my ticket at home.'),
  ('rdg-ja-n3-trip-gone-wrong-l5', 'rdg-ja-n3-trip-gone-wrong', 5, 1, '急いで取りに帰りました。', 'いそいで とり に かえりました。', '[{"t":"急","r":"いそ"},{"t":"いで"},{"t":"取","r":"と"},{"t":"りに"},{"t":"帰","r":"かえ"},{"t":"りました"},{"t":"。"}]'::jsonb, 'I hurried back to get it.'),
  ('rdg-ja-n3-trip-gone-wrong-l6', 'rdg-ja-n3-trip-gone-wrong', 6, 2, 'それで、予定の電車に乗れませんでした。', 'それで、よてい の でんしゃ に のれませんでした。', '[{"t":"それで"},{"t":"、"},{"t":"予定","r":"よてい"},{"t":"の"},{"t":"電車","r":"でんしゃ"},{"t":"に"},{"t":"乗","r":"の"},{"t":"れませんでした"},{"t":"。"}]'::jsonb, 'So I missed the train we had planned on.'),
  ('rdg-ja-n3-trip-gone-wrong-l7', 'rdg-ja-n3-trip-gone-wrong', 7, 2, '友達は一時間も待ってくれました。', 'ともだち わ いちじかん も まって くれました。', '[{"t":"友達","r":"ともだち"},{"t":"は"},{"t":"一時間","r":"いちじかん"},{"t":"も"},{"t":"待","r":"ま"},{"t":"って"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'My friend waited a whole hour for me.'),
  ('rdg-ja-n3-trip-gone-wrong-l8', 'rdg-ja-n3-trip-gone-wrong', 8, 2, '私は何度も謝りました。', 'わたし わ なんど も あやまりました。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"何度","r":"なんど"},{"t":"も"},{"t":"謝","r":"あやま"},{"t":"りました"},{"t":"。"}]'::jsonb, 'I apologized again and again.'),
  ('rdg-ja-n3-trip-gone-wrong-l9', 'rdg-ja-n3-trip-gone-wrong', 9, 3, 'やっと着いた町は、雨でした。', 'やっと ついた まち わ、あめ でした。', '[{"t":"やっと"},{"t":"着","r":"つ"},{"t":"いた"},{"t":"町","r":"まち"},{"t":"は"},{"t":"、"},{"t":"雨","r":"あめ"},{"t":"でした"},{"t":"。"}]'::jsonb, 'The town we finally reached was rainy.'),
  ('rdg-ja-n3-trip-gone-wrong-l10', 'rdg-ja-n3-trip-gone-wrong', 10, 3, '傘を持っていなかったので、', 'かさ お もって いなかった ので、', '[{"t":"傘","r":"かさ"},{"t":"を"},{"t":"持","r":"も"},{"t":"って"},{"t":"いなかった"},{"t":"ので"},{"t":"、"}]'::jsonb, 'Since I had no umbrella,'),
  ('rdg-ja-n3-trip-gone-wrong-l11', 'rdg-ja-n3-trip-gone-wrong', 11, 3, '二人ともぬれてしまいました。', 'ふたり とも ぬれて しまいました。', '[{"t":"二人","r":"ふたり"},{"t":"とも"},{"t":"ぬれて"},{"t":"しまいました"},{"t":"。"}]'::jsonb, 'both of us got soaked.'),
  ('rdg-ja-n3-trip-gone-wrong-l12', 'rdg-ja-n3-trip-gone-wrong', 12, 4, 'しかも、ホテルの予約が取れていませんでした。', 'しかも、ホテル の よやく が とれて いませんでした。', '[{"t":"しかも"},{"t":"、"},{"t":"ホテル"},{"t":"の"},{"t":"予約","r":"よやく"},{"t":"が"},{"t":"取","r":"と"},{"t":"れて"},{"t":"いませんでした"},{"t":"。"}]'::jsonb, 'On top of that, our hotel booking had not gone through.'),
  ('rdg-ja-n3-trip-gone-wrong-l13', 'rdg-ja-n3-trip-gone-wrong', 13, 4, '泊まる部屋がありませんでした。', 'とまる へや が ありませんでした。', '[{"t":"泊","r":"と"},{"t":"まる"},{"t":"部屋","r":"へや"},{"t":"が"},{"t":"ありませんでした"},{"t":"。"}]'::jsonb, 'There was no room for us to stay in.'),
  ('rdg-ja-n3-trip-gone-wrong-l14', 'rdg-ja-n3-trip-gone-wrong', 14, 4, '近くの小さな宿に泊まりました。', 'ちかく の ちいさな やど に とまりました。', '[{"t":"近","r":"ちか"},{"t":"く"},{"t":"の"},{"t":"小","r":"ちい"},{"t":"さな"},{"t":"宿","r":"やど"},{"t":"に"},{"t":"泊","r":"と"},{"t":"まりました"},{"t":"。"}]'::jsonb, 'We stayed at a small inn nearby.'),
  ('rdg-ja-n3-trip-gone-wrong-l15', 'rdg-ja-n3-trip-gone-wrong', 15, 5, '宿で食べた晩ご飯は、', 'やど で たべた ばんごはん わ、', '[{"t":"宿","r":"やど"},{"t":"で"},{"t":"食","r":"た"},{"t":"べた"},{"t":"晩","r":"ばん"},{"t":"ご"},{"t":"飯","r":"はん"},{"t":"は"},{"t":"、"}]'::jsonb, 'The dinner we ate at the inn,'),
  ('rdg-ja-n3-trip-gone-wrong-l16', 'rdg-ja-n3-trip-gone-wrong', 16, 5, '今まで食べた中で一番おいしいと思いました。', 'いま まで たべた なか で いちばん おいしい と おもいました。', '[{"t":"今","r":"いま"},{"t":"まで"},{"t":"食","r":"た"},{"t":"べた"},{"t":"中","r":"なか"},{"t":"で"},{"t":"一番","r":"いちばん"},{"t":"おいしい"},{"t":"と"},{"t":"思","r":"おも"},{"t":"いました"},{"t":"。"}]'::jsonb, 'was the best I had ever eaten, I thought.'),
  ('rdg-ja-n3-trip-gone-wrong-l17', 'rdg-ja-n3-trip-gone-wrong', 17, 5, '宿の人もとても親切でした。', 'やど の ひと も とても しんせつ でした。', '[{"t":"宿","r":"やど"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"も"},{"t":"とても"},{"t":"親切","r":"しんせつ"},{"t":"でした"},{"t":"。"}]'::jsonb, 'The people at the inn were very kind too.'),
  ('rdg-ja-n3-trip-gone-wrong-l18', 'rdg-ja-n3-trip-gone-wrong', 18, 6, '帰りの電車で、二人で笑いました。', 'かえり の でんしゃ で、ふたり で わらいました。', '[{"t":"帰","r":"かえ"},{"t":"り"},{"t":"の"},{"t":"電車","r":"でんしゃ"},{"t":"で"},{"t":"、"},{"t":"二人","r":"ふたり"},{"t":"で"},{"t":"笑","r":"わら"},{"t":"いました"},{"t":"。"}]'::jsonb, 'On the train home, we laughed together.'),
  ('rdg-ja-n3-trip-gone-wrong-l19', 'rdg-ja-n3-trip-gone-wrong', 19, 6, '失敗ばかりの旅行でしたが、', 'しっぱい ばかり の りょこう でした が、', '[{"t":"失敗","r":"しっぱい"},{"t":"ばかり"},{"t":"の"},{"t":"旅行","r":"りょこう"},{"t":"でした"},{"t":"が"},{"t":"、"}]'::jsonb, 'It was a trip full of mistakes, but'),
  ('rdg-ja-n3-trip-gone-wrong-l20', 'rdg-ja-n3-trip-gone-wrong', 20, 6, '一番の思い出になりました。', 'いちばん の おもいで に なりました。', '[{"t":"一番","r":"いちばん"},{"t":"の"},{"t":"思","r":"おも"},{"t":"い"},{"t":"出","r":"で"},{"t":"に"},{"t":"なりました"},{"t":"。"}]'::jsonb, 'it became my favorite memory.'),
  ('rdg-ja-n3-trip-gone-wrong-l21', 'rdg-ja-n3-trip-gone-wrong', 21, 7, '今は、出かける前に何度も確認します。', 'いま わ、でかける まえ に なんど も かくにん します。', '[{"t":"今","r":"いま"},{"t":"は"},{"t":"、"},{"t":"出","r":"で"},{"t":"かける"},{"t":"前","r":"まえ"},{"t":"に"},{"t":"何度","r":"なんど"},{"t":"も"},{"t":"確認","r":"かくにん"},{"t":"します"},{"t":"。"}]'::jsonb, 'Now I check many times before I leave.'),
  ('rdg-ja-n3-trip-gone-wrong-l22', 'rdg-ja-n3-trip-gone-wrong', 22, 7, '最後まで聞いていただいて、ありがとうございました。', 'さいご まで きいて いただいて、ありがとう ございました。', '[{"t":"最後","r":"さいご"},{"t":"まで"},{"t":"聞","r":"き"},{"t":"いて"},{"t":"いただいて"},{"t":"、"},{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you for listening to the end.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
