INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n3-part-time-job-l0', 'rdg-ja-n3-part-time-job', 0, 0, 'はじめまして。', 'はじめまして。', '[{"t":"はじめまして"},{"t":"。"}]'::jsonb, 'Nice to meet you.'),
  ('rdg-ja-n3-part-time-job-l1', 'rdg-ja-n3-part-time-job', 1, 0, '今日は、私のアルバイトの話をします。', 'きょう わ、わたし の アルバイト の はなし お します。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"アルバイト"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"します"},{"t":"。"}]'::jsonb, 'Today I will talk about my part-time job.'),
  ('rdg-ja-n3-part-time-job-l2', 'rdg-ja-n3-part-time-job', 2, 1, '私は駅前の小さな本屋で働いています。', 'わたし わ えきまえ の ちいさな ほんや で はたらいて います。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"駅前","r":"えきまえ"},{"t":"の"},{"t":"小","r":"ちい"},{"t":"さな"},{"t":"本屋","r":"ほんや"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"いて"},{"t":"います"},{"t":"。"}]'::jsonb, 'I work at a small bookstore in front of the station.'),
  ('rdg-ja-n3-part-time-job-l3', 'rdg-ja-n3-part-time-job', 3, 1, '週に三日、夕方から夜まで働きます。', 'しゅう に みっか、ゆうがた から よる まで はたらきます。', '[{"t":"週","r":"しゅう"},{"t":"に"},{"t":"三日","r":"みっか"},{"t":"、"},{"t":"夕方","r":"ゆうがた"},{"t":"から"},{"t":"夜","r":"よる"},{"t":"まで"},{"t":"働","r":"はたら"},{"t":"きます"},{"t":"。"}]'::jsonb, 'I work three days a week, from evening until night.'),
  ('rdg-ja-n3-part-time-job-l4', 'rdg-ja-n3-part-time-job', 4, 2, '仕事は、本を並べることと、', 'しごと わ、ほん お ならべる こと と、', '[{"t":"仕事","r":"しごと"},{"t":"は"},{"t":"、"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"並","r":"なら"},{"t":"べる"},{"t":"こと"},{"t":"と"},{"t":"、"}]'::jsonb, 'My work is arranging books,'),
  ('rdg-ja-n3-part-time-job-l5', 'rdg-ja-n3-part-time-job', 5, 2, 'お客さんの質問に答えることです。', 'おきゃくさん の しつもん に こたえる こと です。', '[{"t":"お"},{"t":"客","r":"きゃく"},{"t":"さん"},{"t":"の"},{"t":"質問","r":"しつもん"},{"t":"に"},{"t":"答","r":"こた"},{"t":"える"},{"t":"こと"},{"t":"です"},{"t":"。"}]'::jsonb, 'and answering customers'' questions.'),
  ('rdg-ja-n3-part-time-job-l6', 'rdg-ja-n3-part-time-job', 6, 2, 'レジに立つこともあります。', 'レジ に たつ こと も あります。', '[{"t":"レジ"},{"t":"に"},{"t":"立","r":"た"},{"t":"つ"},{"t":"こと"},{"t":"も"},{"t":"あります"},{"t":"。"}]'::jsonb, 'Sometimes I also work the register.'),
  ('rdg-ja-n3-part-time-job-l7', 'rdg-ja-n3-part-time-job', 7, 3, '始めたばかりの頃は、失敗が多くて、', 'はじめた ばかり の ころ わ、しっぱい が おおくて、', '[{"t":"始","r":"はじ"},{"t":"めた"},{"t":"ばかり"},{"t":"の"},{"t":"頃","r":"ころ"},{"t":"は"},{"t":"、"},{"t":"失敗","r":"しっぱい"},{"t":"が"},{"t":"多","r":"おお"},{"t":"くて"},{"t":"、"}]'::jsonb, 'When I had just started, I made many mistakes,'),
  ('rdg-ja-n3-part-time-job-l8', 'rdg-ja-n3-part-time-job', 8, 3, '毎日、店の人に注意されました。', 'まいにち、みせ の ひと に ちゅうい されました。', '[{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"店","r":"みせ"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"に"},{"t":"注意","r":"ちゅうい"},{"t":"されました"},{"t":"。"}]'::jsonb, 'and I was told off by the staff every day.'),
  ('rdg-ja-n3-part-time-job-l9', 'rdg-ja-n3-part-time-job', 9, 3, '正直、やめたいと思ったこともあります。', 'しょうじき、やめたい と おもった こと も あります。', '[{"t":"正直","r":"しょうじき"},{"t":"、"},{"t":"やめたい"},{"t":"と"},{"t":"思","r":"おも"},{"t":"った"},{"t":"こと"},{"t":"も"},{"t":"あります"},{"t":"。"}]'::jsonb, 'Honestly, there were times I wanted to quit.'),
  ('rdg-ja-n3-part-time-job-l10', 'rdg-ja-n3-part-time-job', 10, 4, 'でも、ある日、お客さんに', 'でも、ある ひ、おきゃくさん に', '[{"t":"でも"},{"t":"、"},{"t":"ある"},{"t":"日","r":"ひ"},{"t":"、"},{"t":"お"},{"t":"客","r":"きゃく"},{"t":"さん"},{"t":"に"}]'::jsonb, 'But one day, a customer told me,'),
  ('rdg-ja-n3-part-time-job-l11', 'rdg-ja-n3-part-time-job', 11, 4, '「教えてくれた本、とてもよかったよ」と言われました。', '「おしえて くれた ほん、とても よかったよ」 と いわれました。', '[{"t":"「"},{"t":"教","r":"おし"},{"t":"えて"},{"t":"くれた"},{"t":"本","r":"ほん"},{"t":"、"},{"t":"とても"},{"t":"よかったよ"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"われました"},{"t":"。"}]'::jsonb, '"The book you told me about was really good."'),
  ('rdg-ja-n3-part-time-job-l12', 'rdg-ja-n3-part-time-job', 12, 4, 'あの言葉が力になって、続けることにしました。', 'あの ことば が ちから に なって、つづける こと に しました。', '[{"t":"あの"},{"t":"言葉","r":"ことば"},{"t":"が"},{"t":"力","r":"ちから"},{"t":"に"},{"t":"なって"},{"t":"、"},{"t":"続","r":"つづ"},{"t":"ける"},{"t":"こと"},{"t":"に"},{"t":"しました"},{"t":"。"}]'::jsonb, 'Those words gave me strength, so I decided to keep going.'),
  ('rdg-ja-n3-part-time-job-l13', 'rdg-ja-n3-part-time-job', 13, 5, 'アルバイトで学んだことは、', 'アルバイト で まなんだ こと わ、', '[{"t":"アルバイト"},{"t":"で"},{"t":"学","r":"まな"},{"t":"んだ"},{"t":"こと"},{"t":"は"},{"t":"、"}]'::jsonb, 'What I learned from the job is'),
  ('rdg-ja-n3-part-time-job-l14', 'rdg-ja-n3-part-time-job', 14, 5, '人に説明する力です。', 'ひと に せつめい する ちから です。', '[{"t":"人","r":"ひと"},{"t":"に"},{"t":"説明","r":"せつめい"},{"t":"する"},{"t":"力","r":"ちから"},{"t":"です"},{"t":"。"}]'::jsonb, 'the ability to explain things to people.'),
  ('rdg-ja-n3-part-time-job-l15', 'rdg-ja-n3-part-time-job', 15, 5, '大学の勉強にも役に立っています。', 'だいがく の べんきょう に も やく に たって います。', '[{"t":"大学","r":"だいがく"},{"t":"の"},{"t":"勉強","r":"べんきょう"},{"t":"にも"},{"t":"役","r":"やく"},{"t":"に"},{"t":"立","r":"た"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'It is useful for my university studies too.'),
  ('rdg-ja-n3-part-time-job-l16', 'rdg-ja-n3-part-time-job', 16, 6, '給料は安いですが、', 'きゅうりょう わ やすい です が、', '[{"t":"給料","r":"きゅうりょう"},{"t":"は"},{"t":"安","r":"やす"},{"t":"い"},{"t":"です"},{"t":"が"},{"t":"、"}]'::jsonb, 'The pay is low, but'),
  ('rdg-ja-n3-part-time-job-l17', 'rdg-ja-n3-part-time-job', 17, 6, '店で働くのが好きです。', 'みせ で はたらく の が すき です。', '[{"t":"店","r":"みせ"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"く"},{"t":"の"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":"。"}]'::jsonb, 'I enjoy working at the shop.'),
  ('rdg-ja-n3-part-time-job-l18', 'rdg-ja-n3-part-time-job', 18, 6, 'これからも、頑張るつもりです。', 'これから も、がんばる つもり です。', '[{"t":"これから"},{"t":"も"},{"t":"、"},{"t":"頑張","r":"がんば"},{"t":"る"},{"t":"つもりです"},{"t":"。"}]'::jsonb, 'I intend to keep doing my best from now on.'),
  ('rdg-ja-n3-part-time-job-l19', 'rdg-ja-n3-part-time-job', 19, 7, 'これで私の話を終わります。', 'これ で わたし の はなし お おわります。', '[{"t":"これ"},{"t":"で"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"終","r":"お"},{"t":"わります"},{"t":"。"}]'::jsonb, 'That is the end of my talk.'),
  ('rdg-ja-n3-part-time-job-l20', 'rdg-ja-n3-part-time-job', 20, 7, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n3-part-time-job')
