INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n3-chance-meeting-l0', 'rdg-ja-n3-chance-meeting', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n3-chance-meeting-l1', 'rdg-ja-n3-chance-meeting', 1, 0, '先月、不思議なことがありました。', 'せんげつ、ふしぎな こと が ありました。', '[{"t":"先月","r":"せんげつ"},{"t":"、"},{"t":"不思議","r":"ふしぎ"},{"t":"な"},{"t":"こと"},{"t":"が"},{"t":"ありました"},{"t":"。"}]'::jsonb, 'Last month, something strange happened.'),
  ('rdg-ja-n3-chance-meeting-l2', 'rdg-ja-n3-chance-meeting', 2, 1, '休みの日に、知らない町を歩いていました。', 'やすみ の ひ に、しらない まち お あるいて いました。', '[{"t":"休","r":"やす"},{"t":"み"},{"t":"の"},{"t":"日","r":"ひ"},{"t":"に"},{"t":"、"},{"t":"知","r":"し"},{"t":"らない"},{"t":"町","r":"まち"},{"t":"を"},{"t":"歩","r":"ある"},{"t":"いて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'On a day off, I was walking in a town I did not know.'),
  ('rdg-ja-n3-chance-meeting-l3', 'rdg-ja-n3-chance-meeting', 3, 1, '道に迷って、困っていたときです。', 'みち に まよって、こまって いた とき です。', '[{"t":"道","r":"みち"},{"t":"に"},{"t":"迷","r":"まよ"},{"t":"って"},{"t":"、"},{"t":"困","r":"こま"},{"t":"って"},{"t":"いた"},{"t":"とき"},{"t":"です"},{"t":"。"}]'::jsonb, 'It was while I was lost and did not know what to do.'),
  ('rdg-ja-n3-chance-meeting-l4', 'rdg-ja-n3-chance-meeting', 4, 1, '後ろから、私の名前を呼ぶ声がしました。', 'うしろ から、わたし の なまえ お よぶ こえ が しました。', '[{"t":"後","r":"うし"},{"t":"ろ"},{"t":"から"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"名前","r":"なまえ"},{"t":"を"},{"t":"呼","r":"よ"},{"t":"ぶ"},{"t":"声","r":"こえ"},{"t":"が"},{"t":"しました"},{"t":"。"}]'::jsonb, 'From behind, I heard a voice calling my name.'),
  ('rdg-ja-n3-chance-meeting-l5', 'rdg-ja-n3-chance-meeting', 5, 2, '見ると、立っていたのは', 'みる と、たって いた の わ', '[{"t":"見","r":"み"},{"t":"る"},{"t":"と"},{"t":"、"},{"t":"立","r":"た"},{"t":"って"},{"t":"いた"},{"t":"の"},{"t":"は"}]'::jsonb, 'When I looked, the person standing there was'),
  ('rdg-ja-n3-chance-meeting-l6', 'rdg-ja-n3-chance-meeting', 6, 2, '学生のときの友達でした。', 'がくせい の とき の ともだち でした。', '[{"t":"学生","r":"がくせい"},{"t":"の"},{"t":"とき"},{"t":"の"},{"t":"友達","r":"ともだち"},{"t":"でした"},{"t":"。"}]'::jsonb, 'a friend from my student days.'),
  ('rdg-ja-n3-chance-meeting-l7', 'rdg-ja-n3-chance-meeting', 7, 2, '十年ぶりに会ったのです。', 'じゅうねん ぶり に あった の です。', '[{"t":"十年","r":"じゅうねん"},{"t":"ぶり"},{"t":"に"},{"t":"会","r":"あ"},{"t":"った"},{"t":"のです"},{"t":"。"}]'::jsonb, 'It was the first time we had seen each other in ten years.'),
  ('rdg-ja-n3-chance-meeting-l8', 'rdg-ja-n3-chance-meeting', 8, 3, 'お互い、少しの間、言葉が出ませんでした。', 'おたがい、すこし の あいだ、ことば が でませんでした。', '[{"t":"お"},{"t":"互","r":"たが"},{"t":"い"},{"t":"、"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"の"},{"t":"間","r":"あいだ"},{"t":"、"},{"t":"言葉","r":"ことば"},{"t":"が"},{"t":"出","r":"で"},{"t":"ませんでした"},{"t":"。"}]'::jsonb, 'For a little while, neither of us could say a word.'),
  ('rdg-ja-n3-chance-meeting-l9', 'rdg-ja-n3-chance-meeting', 9, 3, 'それから、同時に笑い出しました。', 'それから、どうじ に わらいだしました。', '[{"t":"それから"},{"t":"、"},{"t":"同時","r":"どうじ"},{"t":"に"},{"t":"笑","r":"わら"},{"t":"い"},{"t":"出","r":"だ"},{"t":"しました"},{"t":"。"}]'::jsonb, 'Then we both burst out laughing at the same time.'),
  ('rdg-ja-n3-chance-meeting-l10', 'rdg-ja-n3-chance-meeting', 10, 4, '彼女は仕事で、近くの町に引っ越したそうです。', 'かのじょ わ しごと で、ちかく の まち に ひっこした そう です。', '[{"t":"彼女","r":"かのじょ"},{"t":"は"},{"t":"仕事","r":"しごと"},{"t":"で"},{"t":"、"},{"t":"近","r":"ちか"},{"t":"く"},{"t":"の"},{"t":"町","r":"まち"},{"t":"に"},{"t":"引","r":"ひ"},{"t":"っ"},{"t":"越","r":"こ"},{"t":"した"},{"t":"そう"},{"t":"です"},{"t":"。"}]'::jsonb, 'She told me she had moved to a nearby town for work.'),
  ('rdg-ja-n3-chance-meeting-l11', 'rdg-ja-n3-chance-meeting', 11, 4, '近くのおいしい店に連れて行ってくれました。', 'ちかく の おいしい みせ に つれて いって くれました。', '[{"t":"近","r":"ちか"},{"t":"く"},{"t":"の"},{"t":"おいしい"},{"t":"店","r":"みせ"},{"t":"に"},{"t":"連","r":"つ"},{"t":"れて"},{"t":"行","r":"い"},{"t":"って"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'She took me to a tasty restaurant nearby.'),
  ('rdg-ja-n3-chance-meeting-l12', 'rdg-ja-n3-chance-meeting', 12, 5, '二人で何時間も話しました。', 'ふたり で なんじかん も はなしました。', '[{"t":"二人","r":"ふたり"},{"t":"で"},{"t":"何時間","r":"なんじかん"},{"t":"も"},{"t":"話","r":"はな"},{"t":"しました"},{"t":"。"}]'::jsonb, 'The two of us talked for hours.'),
  ('rdg-ja-n3-chance-meeting-l13', 'rdg-ja-n3-chance-meeting', 13, 5, '昔の先生のこと、学校のこと、', 'むかし の せんせい の こと、がっこう の こと、', '[{"t":"昔","r":"むかし"},{"t":"の"},{"t":"先生","r":"せんせい"},{"t":"の"},{"t":"こと"},{"t":"、"},{"t":"学校","r":"がっこう"},{"t":"の"},{"t":"こと"},{"t":"、"}]'::jsonb, 'About our old teachers, our school,'),
  ('rdg-ja-n3-chance-meeting-l14', 'rdg-ja-n3-chance-meeting', 14, 5, 'そして、これからの夢のことを。', 'そして、これから の ゆめ の こと お。', '[{"t":"そして"},{"t":"、"},{"t":"これから"},{"t":"の"},{"t":"夢","r":"ゆめ"},{"t":"の"},{"t":"こと"},{"t":"を"},{"t":"。"}]'::jsonb, 'and then our dreams for the future.'),
  ('rdg-ja-n3-chance-meeting-l15', 'rdg-ja-n3-chance-meeting', 15, 6, 'もし道に迷わなかったら、', 'もし みち に まよわなかったら、', '[{"t":"もし"},{"t":"道","r":"みち"},{"t":"に"},{"t":"迷","r":"まよ"},{"t":"わなかった"},{"t":"ら"},{"t":"、"}]'::jsonb, 'If I had not gotten lost,'),
  ('rdg-ja-n3-chance-meeting-l16', 'rdg-ja-n3-chance-meeting', 16, 6, '会えなかったかもしれません。', 'あえなかった かも しれません。', '[{"t":"会","r":"あ"},{"t":"えなかった"},{"t":"かも"},{"t":"しれません"},{"t":"。"}]'::jsonb, 'we might never have met.'),
  ('rdg-ja-n3-chance-meeting-l17', 'rdg-ja-n3-chance-meeting', 17, 6, '迷子になって、本当によかったです。', 'まいご に なって、ほんとう に よかった です。', '[{"t":"迷子","r":"まいご"},{"t":"に"},{"t":"なって"},{"t":"、"},{"t":"本当","r":"ほんとう"},{"t":"に"},{"t":"よかった"},{"t":"です"},{"t":"。"}]'::jsonb, 'I am truly glad I got lost.'),
  ('rdg-ja-n3-chance-meeting-l18', 'rdg-ja-n3-chance-meeting', 18, 7, '今も、時々電話で話しています。', 'いま も、ときどき でんわ で はなして います。', '[{"t":"今","r":"いま"},{"t":"も"},{"t":"、"},{"t":"時々電話","r":"ときどき"},{"t":"で"},{"t":"話","r":"んわではな"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'Even now, we talk on the phone from time to time.'),
  ('rdg-ja-n3-chance-meeting-l19', 'rdg-ja-n3-chance-meeting', 19, 7, 'みなさんにも、そんな出会いがありますように。', 'みなさん に も、そんな であい が あります よう に。', '[{"t":"みなさん"},{"t":"にも"},{"t":"、"},{"t":"そんな"},{"t":"出会","r":"であ"},{"t":"い"},{"t":"が"},{"t":"あります"},{"t":"よう"},{"t":"に"},{"t":"。"}]'::jsonb, 'I hope you have a meeting like that too.'),
  ('rdg-ja-n3-chance-meeting-l20', 'rdg-ja-n3-chance-meeting', 20, 7, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n3-chance-meeting')
ON CONFLICT (reading_id, index) DO NOTHING;

