-- N3 · n3-living-alone · Living Alone for the First Time
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n3-living-alone', 'lang-ja', ll.id, 'n3-living-alone', '初めての一人暮らし', 'Living Alone for the First Time', false, 13
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N3'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n3-living-alone-l0', 'rdg-ja-n3-living-alone', 0, 0, 'みなさん、こんばんは。', 'みなさん、こんばんわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんばんは"},{"t":"。"}]'::jsonb, 'Good evening, everyone.'),
  ('rdg-ja-n3-living-alone-l1', 'rdg-ja-n3-living-alone', 1, 0, '私は半年前から、一人で生活しています。', 'わたし わ はんとし まえ から、ひとり で せいかつ して います。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"半","r":"はんとしまえ"},{"t":"年"},{"t":"前"},{"t":"から"},{"t":"、"},{"t":"一人","r":"ひとり"},{"t":"で"},{"t":"生活","r":"せいかつ"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'I have been living on my own for half a year.'),
  ('rdg-ja-n3-living-alone-l2', 'rdg-ja-n3-living-alone', 2, 1, '家を出る日、母は少し泣いていました。', 'いえ お でる ひ、はは わ すこし ないて いました。', '[{"t":"家","r":"いえ"},{"t":"を"},{"t":"出","r":"で"},{"t":"る"},{"t":"日","r":"ひ"},{"t":"、"},{"t":"母","r":"はは"},{"t":"は"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"泣","r":"な"},{"t":"いて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'On the day I left home, my mother was crying a little.'),
  ('rdg-ja-n3-living-alone-l3', 'rdg-ja-n3-living-alone', 3, 1, '私は「大丈夫だよ」と言いましたが、', 'わたし わ 「だいじょうぶだよ」 と いいました が、', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"「"},{"t":"大丈夫","r":"だいじょうぶ"},{"t":"だよ"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"いました"},{"t":"が"},{"t":"、"}]'::jsonb, 'I said, "I will be fine," but'),
  ('rdg-ja-n3-living-alone-l4', 'rdg-ja-n3-living-alone', 4, 1, '本当は、とても不安でした。', 'ほんとう わ、とても ふあん でした。', '[{"t":"本当","r":"ほんとう"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"不安","r":"ふあん"},{"t":"でした"},{"t":"。"}]'::jsonb, 'the truth is, I was very anxious.'),
  ('rdg-ja-n3-living-alone-l5', 'rdg-ja-n3-living-alone', 5, 2, '最初の週は、分からないことばかりでした。', 'さいしょ の しゅう わ、わからない こと ばかり でした。', '[{"t":"最初","r":"さいしょ"},{"t":"の"},{"t":"週","r":"しゅう"},{"t":"は"},{"t":"、"},{"t":"分","r":"わ"},{"t":"からない"},{"t":"こと"},{"t":"ばかり"},{"t":"でした"},{"t":"。"}]'::jsonb, 'The first week, it was nothing but things I did not understand.'),
  ('rdg-ja-n3-living-alone-l6', 'rdg-ja-n3-living-alone', 6, 2, '洗濯機の使い方が分からなくて、', 'せんたくき の つかいかた が わからなくて、', '[{"t":"洗濯機","r":"せんたくき"},{"t":"の"},{"t":"使","r":"つか"},{"t":"い"},{"t":"方","r":"かた"},{"t":"が"},{"t":"分","r":"わ"},{"t":"からなくて"},{"t":"、"}]'::jsonb, 'I did not know how to use the washing machine,'),
  ('rdg-ja-n3-living-alone-l7', 'rdg-ja-n3-living-alone', 7, 2, '服を全部、洗い直しました。', 'ふく お ぜんぶ、あらいなおしました。', '[{"t":"服","r":"ふく"},{"t":"を"},{"t":"全部","r":"ぜんぶ"},{"t":"、"},{"t":"洗","r":"あら"},{"t":"い"},{"t":"直","r":"なお"},{"t":"しました"},{"t":"。"}]'::jsonb, 'and I had to wash all my clothes again.'),
  ('rdg-ja-n3-living-alone-l8', 'rdg-ja-n3-living-alone', 8, 3, '料理も苦手で、毎日パンばかり食べていました。', 'りょうり も にがて で、まいにち パン ばかり たべて いました。', '[{"t":"料理","r":"りょうり"},{"t":"も"},{"t":"苦手","r":"にがて"},{"t":"で"},{"t":"、"},{"t":"毎日","r":"まいにち"},{"t":"パン"},{"t":"ばかり"},{"t":"食","r":"た"},{"t":"べて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I was bad at cooking too, so I lived on bread every day.'),
  ('rdg-ja-n3-living-alone-l9', 'rdg-ja-n3-living-alone', 9, 3, '母に電話して、作り方を聞きました。', 'はは に でんわ して、つくりかた お ききました。', '[{"t":"母","r":"はは"},{"t":"に"},{"t":"電話","r":"でんわ"},{"t":"して"},{"t":"、"},{"t":"作","r":"つく"},{"t":"り"},{"t":"方","r":"かた"},{"t":"を"},{"t":"聞","r":"き"},{"t":"きました"},{"t":"。"}]'::jsonb, 'I called my mother and asked how to make things.'),
  ('rdg-ja-n3-living-alone-l10', 'rdg-ja-n3-living-alone', 10, 4, '夜、部屋が静かで、', 'よる、へや が しずか で、', '[{"t":"夜","r":"よる"},{"t":"、"},{"t":"部屋","r":"へや"},{"t":"が"},{"t":"静","r":"しず"},{"t":"か"},{"t":"で"},{"t":"、"}]'::jsonb, 'At night, the room is so quiet,'),
  ('rdg-ja-n3-living-alone-l11', 'rdg-ja-n3-living-alone', 11, 4, 'さびしくなることもあります。', 'さびしく なる こと も あります。', '[{"t":"さびしく"},{"t":"なる"},{"t":"こと"},{"t":"も"},{"t":"あります"},{"t":"。"}]'::jsonb, 'and sometimes I get lonely.'),
  ('rdg-ja-n3-living-alone-l12', 'rdg-ja-n3-living-alone', 12, 4, 'そんなときは、好きな音楽をかけます。', 'そんな とき わ、すきな おんがく お かけます。', '[{"t":"そんな"},{"t":"とき"},{"t":"は"},{"t":"、"},{"t":"好","r":"す"},{"t":"き"},{"t":"な"},{"t":"音楽","r":"おんがく"},{"t":"を"},{"t":"かけます"},{"t":"。"}]'::jsonb, 'At those times, I play music I like.'),
  ('rdg-ja-n3-living-alone-l13', 'rdg-ja-n3-living-alone', 13, 5, 'でも、少しずつ慣れてきました。', 'でも、すこし ずつ なれて きました。', '[{"t":"でも"},{"t":"、"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"ずつ"},{"t":"慣","r":"な"},{"t":"れて"},{"t":"きました"},{"t":"。"}]'::jsonb, 'But little by little, I have gotten used to it.'),
  ('rdg-ja-n3-living-alone-l14', 'rdg-ja-n3-living-alone', 14, 5, '自分で決めて、自分で動く。', 'じぶん で きめて、じぶん で うごく。', '[{"t":"自分","r":"じぶん"},{"t":"で"},{"t":"決","r":"き"},{"t":"めて"},{"t":"、"},{"t":"自分","r":"じぶん"},{"t":"で"},{"t":"動","r":"うご"},{"t":"く"},{"t":"。"}]'::jsonb, 'Decide for myself, and move for myself.'),
  ('rdg-ja-n3-living-alone-l15', 'rdg-ja-n3-living-alone', 15, 5, 'それが、こんなに楽しいとは思いませんでした。', 'それ が、こんなに たのしい と わ おもいませんでした。', '[{"t":"それ"},{"t":"が"},{"t":"、"},{"t":"こんなに"},{"t":"楽","r":"たの"},{"t":"しい"},{"t":"とは"},{"t":"思","r":"おも"},{"t":"いませんでした"},{"t":"。"}]'::jsonb, 'I never thought that would be so enjoyable.'),
  ('rdg-ja-n3-living-alone-l16', 'rdg-ja-n3-living-alone', 16, 6, '今では、母のしてくれたことがよく分かります。', 'いま で わ、はは の して くれた こと が よく わかります。', '[{"t":"今","r":"いま"},{"t":"では"},{"t":"、"},{"t":"母","r":"はは"},{"t":"の"},{"t":"して"},{"t":"くれた"},{"t":"こと"},{"t":"が"},{"t":"よく"},{"t":"分","r":"わ"},{"t":"かります"},{"t":"。"}]'::jsonb, 'Now I understand well what my mother did for me.'),
  ('rdg-ja-n3-living-alone-l17', 'rdg-ja-n3-living-alone', 17, 6, '来月、久しぶりに実家へ帰ります。', 'らいげつ、ひさしぶり に じっか え かえります。', '[{"t":"来月","r":"らいげつ"},{"t":"、"},{"t":"久","r":"ひさ"},{"t":"しぶり"},{"t":"に"},{"t":"実家","r":"じっか"},{"t":"へ"},{"t":"帰","r":"かえ"},{"t":"ります"},{"t":"。"}]'::jsonb, 'Next month, I will go back to my parents'' home after a long time.'),
  ('rdg-ja-n3-living-alone-l18', 'rdg-ja-n3-living-alone', 18, 6, '母に、おいしい料理を作ってみたいです。', 'はは に、おいしい りょうり お つくって みたい です。', '[{"t":"母","r":"はは"},{"t":"に"},{"t":"、"},{"t":"おいしい"},{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"作","r":"つく"},{"t":"って"},{"t":"みたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I want to try cooking my mother a tasty meal.'),
  ('rdg-ja-n3-living-alone-l19', 'rdg-ja-n3-living-alone', 19, 7, '以上です。', 'いじょう です。', '[{"t":"以上","r":"いじょう"},{"t":"です"},{"t":"。"}]'::jsonb, 'That is all.'),
  ('rdg-ja-n3-living-alone-l20', 'rdg-ja-n3-living-alone', 20, 7, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n3-living-alone')
ON CONFLICT (reading_id, index) DO NOTHING;

