SELECT 'crq-rdg-ja-n3-living-alone', 'lang-ja', 'readings', 'rdg-ja-n3-living-alone', 'create', '{"code":"n3-living-alone","level":"N3"}'::jsonb, 'ai', 3, 'pending'
