-- N3 · n3-why-i-keep-a-diary · Why I Keep a Diary
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n3-why-i-keep-a-diary', 'lang-ja', ll.id, 'n3-why-i-keep-a-diary', '日記をつける理由', 'Why I Keep a Diary', false, 14
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N3'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n3-why-i-keep-a-diary-l0', 'rdg-ja-n3-why-i-keep-a-diary', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l1', 'rdg-ja-n3-why-i-keep-a-diary', 1, 0, '私は五年間、毎晩日記を書いています。', 'わたし わ ごねんかん、まいばん にっき お かいて います。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"五年間","r":"ごねんかん"},{"t":"、"},{"t":"毎晩","r":"まいばんにっき"},{"t":"日記"},{"t":"を"},{"t":"書","r":"か"},{"t":"いて"},{"t":"います"},{"t":"。"}]'::jsonb, 'I have written in a diary every night for five years.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l2', 'rdg-ja-n3-why-i-keep-a-diary', 2, 1, 'きっかけは、中学のときの先生の言葉でした。', 'きっかけ わ、ちゅうがく の とき の せんせい の ことば でした。', '[{"t":"きっかけ"},{"t":"は"},{"t":"、"},{"t":"中学","r":"ちゅうがく"},{"t":"の"},{"t":"とき"},{"t":"の"},{"t":"先生","r":"せんせい"},{"t":"の"},{"t":"言葉","r":"ことば"},{"t":"でした"},{"t":"。"}]'::jsonb, 'It all began with something my middle-school teacher said.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l3', 'rdg-ja-n3-why-i-keep-a-diary', 3, 1, '「書けば、心が軽くなるよ」と言われたのです。', '「かけば、こころ が かるく なるよ」 と いわれた の です。', '[{"t":"「"},{"t":"書","r":"か"},{"t":"けば"},{"t":"、"},{"t":"心","r":"こころ"},{"t":"が"},{"t":"軽","r":"かる"},{"t":"くなるよ"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"われたのです"},{"t":"。"}]'::jsonb, 'I was told, "If you write, your heart will feel lighter."'),
  ('rdg-ja-n3-why-i-keep-a-diary-l4', 'rdg-ja-n3-why-i-keep-a-diary', 4, 1, '最初は、信じていませんでした。', 'さいしょ わ、しんじて いませんでした。', '[{"t":"最初","r":"さいしょ"},{"t":"は"},{"t":"、"},{"t":"信","r":"しん"},{"t":"じて"},{"t":"いませんでした"},{"t":"。"}]'::jsonb, 'At first, I did not believe it.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l5', 'rdg-ja-n3-why-i-keep-a-diary', 5, 2, 'でも、続けてみると、本当に先生の言うとおりでした。', 'でも、つづけて みる と、ほんとう に せんせい の いう とおり でした。', '[{"t":"でも"},{"t":"、"},{"t":"続","r":"つづ"},{"t":"けて"},{"t":"みる"},{"t":"と"},{"t":"、"},{"t":"本当","r":"ほんとう"},{"t":"に"},{"t":"先生","r":"せんせい"},{"t":"の"},{"t":"言","r":"い"},{"t":"う"},{"t":"とおり"},{"t":"でした"},{"t":"。"}]'::jsonb, 'But once I kept at it, my teacher was exactly right.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l6', 'rdg-ja-n3-why-i-keep-a-diary', 6, 2, 'いやなことがあった日も、', 'いやな こと が あった ひ も、', '[{"t":"いやな"},{"t":"こと"},{"t":"が"},{"t":"あった"},{"t":"日","r":"ひ"},{"t":"も"},{"t":"、"}]'::jsonb, 'Even on days when something bad happened,'),
  ('rdg-ja-n3-why-i-keep-a-diary-l7', 'rdg-ja-n3-why-i-keep-a-diary', 7, 2, '書いているうちに、落ち着いてきます。', 'かいて いる うち に、おちついて きます。', '[{"t":"書","r":"か"},{"t":"いて"},{"t":"いる"},{"t":"うち"},{"t":"に"},{"t":"、"},{"t":"落","r":"お"},{"t":"ち"},{"t":"着","r":"つ"},{"t":"いて"},{"t":"きます"},{"t":"。"}]'::jsonb, 'while I write, I calm down.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l8', 'rdg-ja-n3-why-i-keep-a-diary', 8, 3, '日記は、自分と話す時間でもあります。', 'にっき わ、じぶん と はなす じかん でも あります。', '[{"t":"日記","r":"にっき"},{"t":"は"},{"t":"、"},{"t":"自分","r":"じぶん"},{"t":"と"},{"t":"話","r":"はな"},{"t":"す"},{"t":"時間","r":"じかん"},{"t":"でも"},{"t":"あります"},{"t":"。"}]'::jsonb, 'A diary is also time to talk with myself.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l9', 'rdg-ja-n3-why-i-keep-a-diary', 9, 3, '一日の気持ちを、正直に書きます。', 'いちにち の きもち お、しょうじき に かきます。', '[{"t":"一日","r":"いちにち"},{"t":"の"},{"t":"気持","r":"きも"},{"t":"ち"},{"t":"を"},{"t":"、"},{"t":"正直","r":"しょうじき"},{"t":"に"},{"t":"書","r":"か"},{"t":"きます"},{"t":"。"}]'::jsonb, 'I write the day''s feelings honestly.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l10', 'rdg-ja-n3-why-i-keep-a-diary', 10, 3, '人には言えないことも書けます。', 'ひと に わ いえない こと も かけます。', '[{"t":"人","r":"ひと"},{"t":"に"},{"t":"は"},{"t":"言","r":"い"},{"t":"えない"},{"t":"こと"},{"t":"も"},{"t":"書","r":"か"},{"t":"けます"},{"t":"。"}]'::jsonb, 'I can even write things I cannot tell others.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l11', 'rdg-ja-n3-why-i-keep-a-diary', 11, 4, 'もう一つの理由は、読み返す楽しみです。', 'もう ひとつ の りゆう わ、よみかえす たのしみ です。', '[{"t":"もう"},{"t":"一","r":"ひと"},{"t":"つ"},{"t":"の"},{"t":"理由","r":"りゆう"},{"t":"は"},{"t":"、"},{"t":"読","r":"よ"},{"t":"み"},{"t":"返","r":"かえ"},{"t":"す"},{"t":"楽","r":"たの"},{"t":"しみ"},{"t":"です"},{"t":"。"}]'::jsonb, 'Another reason is the pleasure of reading it again.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l12', 'rdg-ja-n3-why-i-keep-a-diary', 12, 4, '去年の今日、何をしていたか分かります。', 'きょねん の きょう、なに お して いた か わかります。', '[{"t":"去年","r":"きょねん"},{"t":"の"},{"t":"今日","r":"きょう"},{"t":"、"},{"t":"何","r":"なに"},{"t":"を"},{"t":"して"},{"t":"いた"},{"t":"か"},{"t":"分","r":"わ"},{"t":"かります"},{"t":"。"}]'::jsonb, 'I can tell what I was doing on this day last year.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l13', 'rdg-ja-n3-why-i-keep-a-diary', 13, 4, '自分の小さな変化に気づくこともあります。', 'じぶん の ちいさな へんか に きづく こと も あります。', '[{"t":"自分","r":"じぶん"},{"t":"の"},{"t":"小","r":"ちい"},{"t":"さな"},{"t":"変化","r":"へんか"},{"t":"に"},{"t":"気","r":"き"},{"t":"づく"},{"t":"こと"},{"t":"も"},{"t":"あります"},{"t":"。"}]'::jsonb, 'Sometimes I notice small changes in myself.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l14', 'rdg-ja-n3-why-i-keep-a-diary', 14, 5, '忙しくて、書けない日もあります。', 'いそがしくて、かけない ひ も あります。', '[{"t":"忙","r":"いそが"},{"t":"しくて"},{"t":"、"},{"t":"書","r":"か"},{"t":"けない"},{"t":"日","r":"ひ"},{"t":"も"},{"t":"あります"},{"t":"。"}]'::jsonb, 'There are days when I am too busy to write.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l15', 'rdg-ja-n3-why-i-keep-a-diary', 15, 5, 'そんな日は、短くてもいいのです。', 'そんな ひ わ、みじかくても いい の です。', '[{"t":"そんな"},{"t":"日","r":"ひ"},{"t":"は"},{"t":"、"},{"t":"短","r":"みじか"},{"t":"くてもいいのです"},{"t":"。"}]'::jsonb, 'On those days, even a short entry is fine.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l16', 'rdg-ja-n3-why-i-keep-a-diary', 16, 6, '大切なのは、続けることです。', 'たいせつな の わ、つづける こと です。', '[{"t":"大切","r":"たいせつ"},{"t":"な"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"続","r":"つづ"},{"t":"ける"},{"t":"こと"},{"t":"です"},{"t":"。"}]'::jsonb, 'What matters is to keep going.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l17', 'rdg-ja-n3-why-i-keep-a-diary', 17, 6, '日記のおかげで、自分のことがよく分かるようになりました。', 'にっき の おかげ で、じぶん の こと が よく わかる よう に なりました。', '[{"t":"日記","r":"にっき"},{"t":"の"},{"t":"おかげで"},{"t":"、"},{"t":"自分","r":"じぶん"},{"t":"の"},{"t":"こと"},{"t":"が"},{"t":"よく"},{"t":"分","r":"わ"},{"t":"かる"},{"t":"よう"},{"t":"に"},{"t":"なりました"},{"t":"。"}]'::jsonb, 'Thanks to my diary, I have come to understand myself better.'),
  ('rdg-ja-n3-why-i-keep-a-diary-l18', 'rdg-ja-n3-why-i-keep-a-diary', 18, 7, 'みなさんも、今夜から始めてみませんか。', 'みなさん も、こんや から はじめて みませんか。', '[{"t":"みなさん"},{"t":"も"},{"t":"、"},{"t":"今夜","r":"こんや"},{"t":"から"},{"t":"始","r":"はじ"},{"t":"めて"},{"t":"みませんか"},{"t":"。"}]'::jsonb, 'Why not try starting tonight, everyone?'),
  ('rdg-ja-n3-why-i-keep-a-diary-l19', 'rdg-ja-n3-why-i-keep-a-diary', 19, 7, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n3-why-i-keep-a-diary')
