-- N2 · n2-work-and-life · Balancing work and the rest of life
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n2-work-and-life', 'lang-ja', ll.id, 'n2-work-and-life', '仕事と生活のバランス', 'Balancing work and the rest of life', false, 15
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N2'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n2-work-and-life-l0', 'rdg-ja-n2-work-and-life', 0, 0, 'みなさんは、毎日何時まで働いていますか。', 'みなさん わ、まいにち なんじ まで はたらいて います か。', '[{"t":"みなさん"},{"t":"は"},{"t":"、"},{"t":"毎日","r":"まいにちなんじ"},{"t":"何"},{"t":"時"},{"t":"まで"},{"t":"働","r":"はたら"},{"t":"いて"},{"t":"います"},{"t":"か"},{"t":"。"}]'::jsonb, 'Everyone, until what time do you work each day?'),
  ('rdg-ja-n2-work-and-life-l1', 'rdg-ja-n2-work-and-life', 1, 0, '数年前の私は、', 'すうねん まえ の わたし わ、', '[{"t":"数年前","r":"すうねんまえ"},{"t":"の"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"}]'::jsonb, 'A few years ago, I'),
  ('rdg-ja-n2-work-and-life-l2', 'rdg-ja-n2-work-and-life', 2, 0, '毎日、夜の十時ごろまで働いていました。', 'まいにち、よる の じゅうじ ごろ まで はたらいて いました。', '[{"t":"毎日","r":"まいにち"},{"t":"、"},{"t":"夜","r":"よる"},{"t":"の"},{"t":"十時","r":"じゅうじ"},{"t":"ごろ"},{"t":"まで"},{"t":"働","r":"はたら"},{"t":"いて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'worked until around ten at night every day.'),
  ('rdg-ja-n2-work-and-life-l3', 'rdg-ja-n2-work-and-life', 3, 0, '家に帰っても、ただ寝るだけでした。', 'いえ に かえって も、ただ ねる だけ でした。', '[{"t":"家","r":"いえ"},{"t":"に"},{"t":"帰","r":"かえ"},{"t":"って"},{"t":"も"},{"t":"、"},{"t":"ただ"},{"t":"寝","r":"ね"},{"t":"る"},{"t":"だけ"},{"t":"でした"},{"t":"。"}]'::jsonb, 'When I got home, all I did was go to sleep.'),
  ('rdg-ja-n2-work-and-life-l4', 'rdg-ja-n2-work-and-life', 4, 1, '忙しいのは、良いことだと', 'いそがしい の わ、よい こと だ と', '[{"t":"忙","r":"いそが"},{"t":"しい"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"良","r":"よ"},{"t":"い"},{"t":"こと"},{"t":"だ"},{"t":"と"}]'::jsonb, 'I believed that being busy'),
  ('rdg-ja-n2-work-and-life-l5', 'rdg-ja-n2-work-and-life', 5, 1, '思っていたのです。', 'おもって いた の です。', '[{"t":"思","r":"おも"},{"t":"って"},{"t":"いた"},{"t":"のです"},{"t":"。"}]'::jsonb, 'was a good thing.'),
  ('rdg-ja-n2-work-and-life-l6', 'rdg-ja-n2-work-and-life', 6, 1, 'でも、体は正直でした。', 'でも、からだ わ しょうじき でした。', '[{"t":"でも"},{"t":"、"},{"t":"体","r":"からだ"},{"t":"は"},{"t":"正直","r":"しょうじき"},{"t":"でした"},{"t":"。"}]'::jsonb, 'But my body was honest.'),
  ('rdg-ja-n2-work-and-life-l7', 'rdg-ja-n2-work-and-life', 7, 2, 'ある朝、起きられなくなりました。', 'ある あさ、おきられなく なりました。', '[{"t":"ある"},{"t":"朝","r":"あさ"},{"t":"、"},{"t":"起","r":"お"},{"t":"きられなくなりました"},{"t":"。"}]'::jsonb, 'One morning, I could not get up.'),
  ('rdg-ja-n2-work-and-life-l8', 'rdg-ja-n2-work-and-life', 8, 2, '医者は、休むように言いました。', 'いしゃ わ、やすむ よう に いいました。', '[{"t":"医者","r":"いしゃ"},{"t":"は"},{"t":"、"},{"t":"休","r":"やす"},{"t":"む"},{"t":"よう"},{"t":"に"},{"t":"言","r":"い"},{"t":"いました"},{"t":"。"}]'::jsonb, 'The doctor told me to rest.'),
  ('rdg-ja-n2-work-and-life-l9', 'rdg-ja-n2-work-and-life', 9, 2, 'あの時、初めて気が付きました。', 'あの とき、はじめて き が つきました。', '[{"t":"あの"},{"t":"時","r":"とき"},{"t":"、"},{"t":"初","r":"はじ"},{"t":"めて"},{"t":"気","r":"き"},{"t":"が"},{"t":"付","r":"つ"},{"t":"きました"},{"t":"。"}]'::jsonb, 'That was when I first realized'),
  ('rdg-ja-n2-work-and-life-l10', 'rdg-ja-n2-work-and-life', 10, 2, '私は無理ばかりしていたのです。', 'わたし わ むり ばかり して いた の です。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"無理","r":"むり"},{"t":"ばかり"},{"t":"して"},{"t":"いた"},{"t":"のです"},{"t":"。"}]'::jsonb, 'that I had been pushing myself too hard.'),
  ('rdg-ja-n2-work-and-life-l11', 'rdg-ja-n2-work-and-life', 11, 3, 'それから、いくつかのことを', 'それから、いくつか の こと お', '[{"t":"それから"},{"t":"、"},{"t":"いくつか"},{"t":"の"},{"t":"こと"},{"t":"を"}]'::jsonb, 'After that, I decided to change'),
  ('rdg-ja-n2-work-and-life-l12', 'rdg-ja-n2-work-and-life', 12, 3, '変えることにしました。', 'かえる こと に しました。', '[{"t":"変","r":"か"},{"t":"える"},{"t":"こと"},{"t":"に"},{"t":"しました"},{"t":"。"}]'::jsonb, 'a few things.'),
  ('rdg-ja-n2-work-and-life-l13', 'rdg-ja-n2-work-and-life', 13, 3, 'はじめに、夜の八時以降は', 'はじめ に、よる の はちじ いこう わ', '[{"t":"はじめ"},{"t":"に"},{"t":"、"},{"t":"夜","r":"よる"},{"t":"の"},{"t":"八時","r":"はちじいこう"},{"t":"以降"},{"t":"は"}]'::jsonb, 'First, after eight at night,'),
  ('rdg-ja-n2-work-and-life-l14', 'rdg-ja-n2-work-and-life', 14, 3, '仕事の連絡を見ません。', 'しごと の れんらく お みません。', '[{"t":"仕事","r":"しごと"},{"t":"の"},{"t":"連絡","r":"れんらく"},{"t":"を"},{"t":"見","r":"み"},{"t":"ません"},{"t":"。"}]'::jsonb, 'I do not look at work messages.'),
  ('rdg-ja-n2-work-and-life-l15', 'rdg-ja-n2-work-and-life', 15, 4, '次に、週に二回は早く帰って', 'つぎ に、しゅう に にかい わ はやく かえって', '[{"t":"次","r":"つぎ"},{"t":"に"},{"t":"、"},{"t":"週","r":"しゅう"},{"t":"に"},{"t":"二回","r":"にかい"},{"t":"は"},{"t":"早","r":"はや"},{"t":"く"},{"t":"帰","r":"かえ"},{"t":"って"}]'::jsonb, 'Next, twice a week I go home early'),
  ('rdg-ja-n2-work-and-life-l16', 'rdg-ja-n2-work-and-life', 16, 4, '自分で料理を作ります。', 'じぶん で りょうり お つくります。', '[{"t":"自分","r":"じぶん"},{"t":"で"},{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"作","r":"つく"},{"t":"ります"},{"t":"。"}]'::jsonb, 'and cook for myself.'),
  ('rdg-ja-n2-work-and-life-l17', 'rdg-ja-n2-work-and-life', 17, 4, '小さなことですが、', 'ちいさな こと です が、', '[{"t":"小","r":"ちい"},{"t":"さな"},{"t":"こと"},{"t":"です"},{"t":"が"},{"t":"、"}]'::jsonb, 'It is a small thing,'),
  ('rdg-ja-n2-work-and-life-l18', 'rdg-ja-n2-work-and-life', 18, 4, '心が軽くなりました。', 'こころ が かるく なりました。', '[{"t":"心","r":"こころ"},{"t":"が"},{"t":"軽","r":"かる"},{"t":"くなりました"},{"t":"。"}]'::jsonb, 'but my heart felt lighter.'),
  ('rdg-ja-n2-work-and-life-l19', 'rdg-ja-n2-work-and-life', 19, 5, '休みの日には、散歩に行ったり、', 'やすみ の ひ に わ、さんぽ に いったり、', '[{"t":"休","r":"やす"},{"t":"み"},{"t":"の"},{"t":"日","r":"ひ"},{"t":"に"},{"t":"は"},{"t":"、"},{"t":"散歩","r":"さんぽ"},{"t":"に"},{"t":"行","r":"い"},{"t":"った"},{"t":"り"},{"t":"、"}]'::jsonb, 'On days off, I go for walks,'),
  ('rdg-ja-n2-work-and-life-l20', 'rdg-ja-n2-work-and-life', 20, 5, '友達と会ったりしています。', 'ともだち と あったり して います。', '[{"t":"友達","r":"ともだち"},{"t":"と"},{"t":"会","r":"あ"},{"t":"った"},{"t":"り"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'or meet up with friends.'),
  ('rdg-ja-n2-work-and-life-l21', 'rdg-ja-n2-work-and-life', 21, 5, '仕事の成果は、', 'しごと の せいか わ、', '[{"t":"仕事","r":"しごと"},{"t":"の"},{"t":"成果","r":"せいか"},{"t":"は"},{"t":"、"}]'::jsonb, 'The results of my work'),
  ('rdg-ja-n2-work-and-life-l22', 'rdg-ja-n2-work-and-life', 22, 5, '意外にも下がりませんでした。', 'いがい に も さがりませんでした。', '[{"t":"意外","r":"いがい"},{"t":"にも"},{"t":"下","r":"さ"},{"t":"がりませんでした"},{"t":"。"}]'::jsonb, 'surprisingly did not drop.'),
  ('rdg-ja-n2-work-and-life-l23', 'rdg-ja-n2-work-and-life', 23, 6, '仕事は人生の一部であって、', 'しごと わ じんせい の いちぶ であって、', '[{"t":"仕事","r":"しごと"},{"t":"は"},{"t":"人生","r":"じんせい"},{"t":"の"},{"t":"一部","r":"いちぶ"},{"t":"であって"},{"t":"、"}]'::jsonb, 'Work is one part of life,'),
  ('rdg-ja-n2-work-and-life-l24', 'rdg-ja-n2-work-and-life', 24, 6, 'すべてではありません。', 'すべて で わ ありません。', '[{"t":"すべて"},{"t":"では"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'not the whole of it.'),
  ('rdg-ja-n2-work-and-life-l25', 'rdg-ja-n2-work-and-life', 25, 6, '今後も、仕事と生活の両方を', 'こんご も、しごと と せいかつ の りょうほう お', '[{"t":"今後","r":"こんご"},{"t":"も"},{"t":"、"},{"t":"仕事","r":"しごと"},{"t":"と"},{"t":"生活","r":"せいかつ"},{"t":"の"},{"t":"両方","r":"りょうほう"},{"t":"を"}]'::jsonb, 'From now on, too, I want to value'),
  ('rdg-ja-n2-work-and-life-l26', 'rdg-ja-n2-work-and-life', 26, 6, '大切にしたいです。', 'たいせつ に したい です。', '[{"t":"大切","r":"たいせつ"},{"t":"に"},{"t":"したい"},{"t":"です"},{"t":"。"}]'::jsonb, 'both my work and my life.'),
  ('rdg-ja-n2-work-and-life-l27', 'rdg-ja-n2-work-and-life', 27, 7, '今日は、ありがとうございました。', 'きょう わ、ありがとうございました。', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you for listening.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n2-work-and-life')
ON CONFLICT (reading_id, index) DO NOTHING;

