INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n2-social-media-and-me-l0', 'rdg-ja-n2-social-media-and-me', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n2-social-media-and-me-l1', 'rdg-ja-n2-social-media-and-me', 1, 0, '私は、画面との付き合い方について', 'わたし わ、がめん と の つきあいかた に ついて', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"画面","r":"がめん"},{"t":"と"},{"t":"の"},{"t":"付","r":"つ"},{"t":"き"},{"t":"合","r":"あ"},{"t":"い"},{"t":"方","r":"かた"},{"t":"について"}]'::jsonb, 'I would like to speak about'),
  ('rdg-ja-n2-social-media-and-me-l2', 'rdg-ja-n2-social-media-and-me', 2, 0, 'お話ししたいと思います。', 'おはなし したい と おもいます。', '[{"t":"お"},{"t":"話","r":"はな"},{"t":"し"},{"t":"したい"},{"t":"と"},{"t":"思","r":"おも"},{"t":"います"},{"t":"。"}]'::jsonb, 'how I relate to screens.'),
  ('rdg-ja-n2-social-media-and-me-l3', 'rdg-ja-n2-social-media-and-me', 3, 1, '高校生の頃、', 'こうこうせい の ころ、', '[{"t":"高校生","r":"こうこうせい"},{"t":"の"},{"t":"頃","r":"ころ"},{"t":"、"}]'::jsonb, 'When I was in high school,'),
  ('rdg-ja-n2-social-media-and-me-l4', 'rdg-ja-n2-social-media-and-me', 4, 1, '私は一日に何十回も', 'わたし わ いちにち に なんじゅっかい も', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"一日","r":"いちにち"},{"t":"に"},{"t":"何十回","r":"なんじゅっかい"},{"t":"も"}]'::jsonb, 'I checked my phone'),
  ('rdg-ja-n2-social-media-and-me-l5', 'rdg-ja-n2-social-media-and-me', 5, 1, '携帯を見ていました。', 'けいたい お みて いました。', '[{"t":"携帯","r":"けいたい"},{"t":"を"},{"t":"見","r":"み"},{"t":"て"},{"t":"いました"},{"t":"。"}]'::jsonb, 'dozens of times a day.'),
  ('rdg-ja-n2-social-media-and-me-l6', 'rdg-ja-n2-social-media-and-me', 6, 2, '友達の投稿を見てはコメントを書き、', 'ともだち の とうこう お みて わ コメント お かき、', '[{"t":"友達","r":"ともだち"},{"t":"の"},{"t":"投稿","r":"とうこう"},{"t":"を"},{"t":"見","r":"み"},{"t":"て"},{"t":"は"},{"t":"コメント"},{"t":"を"},{"t":"書","r":"か"},{"t":"き"},{"t":"、"}]'::jsonb, 'I read my friends'' posts and left comments,'),
  ('rdg-ja-n2-social-media-and-me-l7', 'rdg-ja-n2-social-media-and-me', 7, 2, '自分の写真にも', 'じぶん の しゃしん に も', '[{"t":"自分","r":"じぶん"},{"t":"の"},{"t":"写真","r":"しゃしん"},{"t":"にも"}]'::jsonb, 'and on my own photos,'),
  ('rdg-ja-n2-social-media-and-me-l8', 'rdg-ja-n2-social-media-and-me', 8, 2, '反応が来るのを、ずっと待っていました。', 'はんのう が くる の お、ずっと まって いました。', '[{"t":"反応","r":"はんのう"},{"t":"が"},{"t":"来","r":"く"},{"t":"る"},{"t":"の"},{"t":"を"},{"t":"、"},{"t":"ずっと"},{"t":"待","r":"ま"},{"t":"って"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I kept waiting for reactions.'),
  ('rdg-ja-n2-social-media-and-me-l9', 'rdg-ja-n2-social-media-and-me', 9, 3, 'ところが、だんだん', 'ところが、だんだん', '[{"t":"ところが"},{"t":"、"},{"t":"だんだん"}]'::jsonb, 'But little by little,'),
  ('rdg-ja-n2-social-media-and-me-l10', 'rdg-ja-n2-social-media-and-me', 10, 3, '疲れを感じるようになりました。', 'つかれ お かんじる よう に なりました。', '[{"t":"疲","r":"つか"},{"t":"れ"},{"t":"を"},{"t":"感","r":"かん"},{"t":"じる"},{"t":"よう"},{"t":"に"},{"t":"なりました"},{"t":"。"}]'::jsonb, 'I began to feel worn out.'),
  ('rdg-ja-n2-social-media-and-me-l11', 'rdg-ja-n2-social-media-and-me', 11, 3, '他の人の楽しそうな生活と', 'ほか の ひと の たのしそう な せいかつ と', '[{"t":"他","r":"ほか"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"の"},{"t":"楽","r":"たの"},{"t":"しそう"},{"t":"な"},{"t":"生活","r":"せいかつ"},{"t":"と"}]'::jsonb, 'That was because I kept comparing myself'),
  ('rdg-ja-n2-social-media-and-me-l12', 'rdg-ja-n2-social-media-and-me', 12, 3, '自分を比べてばかりいたからです。', 'じぶん お くらべて ばかり いた から です。', '[{"t":"自分","r":"じぶん"},{"t":"を"},{"t":"比","r":"くら"},{"t":"べて"},{"t":"ばかり"},{"t":"いた"},{"t":"から"},{"t":"です"},{"t":"。"}]'::jsonb, 'with other people''s happy-looking lives.'),
  ('rdg-ja-n2-social-media-and-me-l13', 'rdg-ja-n2-social-media-and-me', 13, 4, '画面の中の世界は、', 'がめん の なか の せかい わ、', '[{"t":"画面","r":"がめん"},{"t":"の"},{"t":"中","r":"なか"},{"t":"の"},{"t":"世界","r":"せかい"},{"t":"は"},{"t":"、"}]'::jsonb, 'The world inside the screen'),
  ('rdg-ja-n2-social-media-and-me-l14', 'rdg-ja-n2-social-media-and-me', 14, 4, '良い部分だけを切り取ったものです。', 'よい ぶぶん だけ お きりとった もの です。', '[{"t":"良","r":"よ"},{"t":"い"},{"t":"部分","r":"ぶぶん"},{"t":"だけ"},{"t":"を"},{"t":"切","r":"き"},{"t":"り"},{"t":"取","r":"と"},{"t":"った"},{"t":"もの"},{"t":"です"},{"t":"。"}]'::jsonb, 'is only the best parts, cut out.'),
  ('rdg-ja-n2-social-media-and-me-l15', 'rdg-ja-n2-social-media-and-me', 15, 4, 'それを忘れてはいけません。', 'それ お わすれて わ いけません。', '[{"t":"それ"},{"t":"を"},{"t":"忘","r":"わす"},{"t":"れて"},{"t":"はいけません"},{"t":"。"}]'::jsonb, 'We must not forget that.'),
  ('rdg-ja-n2-social-media-and-me-l16', 'rdg-ja-n2-social-media-and-me', 16, 5, '今は、自分だけの', 'いま わ、じぶん だけ の', '[{"t":"今","r":"いま"},{"t":"は"},{"t":"、"},{"t":"自分","r":"じぶん"},{"t":"だけ"},{"t":"の"}]'::jsonb, 'Now I have made'),
  ('rdg-ja-n2-social-media-and-me-l17', 'rdg-ja-n2-social-media-and-me', 17, 5, 'ルールを作っています。', 'ルール お つくって います。', '[{"t":"ルール"},{"t":"を"},{"t":"作","r":"つく"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'rules of my own.'),
  ('rdg-ja-n2-social-media-and-me-l18', 'rdg-ja-n2-social-media-and-me', 18, 5, '寝る前の一時間は、', 'ねる まえ の いちじかん わ、', '[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"まえ"},{"t":"の"},{"t":"一時間","r":"いちじかん"},{"t":"は"},{"t":"、"}]'::jsonb, 'For the hour before bed,'),
  ('rdg-ja-n2-social-media-and-me-l19', 'rdg-ja-n2-social-media-and-me', 19, 5, '携帯を別の部屋に置きます。', 'けいたい お べつ の へや に おきます。', '[{"t":"携帯","r":"けいたい"},{"t":"を"},{"t":"別","r":"べつ"},{"t":"の"},{"t":"部屋","r":"へや"},{"t":"に"},{"t":"置","r":"お"},{"t":"きます"},{"t":"。"}]'::jsonb, 'I leave my phone in another room.'),
  ('rdg-ja-n2-social-media-and-me-l20', 'rdg-ja-n2-social-media-and-me', 20, 6, '確かに、携帯には', 'たしか に、けいたい に わ', '[{"t":"確","r":"たし"},{"t":"か"},{"t":"に"},{"t":"、"},{"t":"携帯","r":"けいたい"},{"t":"に"},{"t":"は"}]'::jsonb, 'Admittedly, the phone'),
  ('rdg-ja-n2-social-media-and-me-l21', 'rdg-ja-n2-social-media-and-me', 21, 6, '良い点もたくさんあります。', 'よい てん も たくさん あります。', '[{"t":"良","r":"よ"},{"t":"い"},{"t":"点","r":"てん"},{"t":"も"},{"t":"たくさん"},{"t":"あります"},{"t":"。"}]'::jsonb, 'also has many good points.'),
  ('rdg-ja-n2-social-media-and-me-l22', 'rdg-ja-n2-social-media-and-me', 22, 6, '遠くに住む家族の様子が', 'とおく に すむ かぞく の ようす が', '[{"t":"遠","r":"とお"},{"t":"く"},{"t":"に"},{"t":"住","r":"す"},{"t":"む"},{"t":"家族","r":"かぞく"},{"t":"の"},{"t":"様子","r":"ようす"},{"t":"が"}]'::jsonb, 'Being able to see how my faraway family is doing'),
  ('rdg-ja-n2-social-media-and-me-l23', 'rdg-ja-n2-social-media-and-me', 23, 6, 'いつでもわかるのは、ありがたいです。', 'いつ でも わかる の わ、ありがたい です。', '[{"t":"いつ"},{"t":"でも"},{"t":"わかる"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"ありがたい"},{"t":"です"},{"t":"。"}]'::jsonb, 'at any time is something I''m grateful for.'),
  ('rdg-ja-n2-social-media-and-me-l24', 'rdg-ja-n2-social-media-and-me', 24, 7, '大切なのは、道具に使われず、', 'たいせつ な の わ、どうぐ に つかわれず、', '[{"t":"大切","r":"たいせつ"},{"t":"な"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"道具","r":"どうぐ"},{"t":"に"},{"t":"使","r":"つか"},{"t":"われず"},{"t":"、"}]'::jsonb, 'What matters is not to be used by the tool,'),
  ('rdg-ja-n2-social-media-and-me-l25', 'rdg-ja-n2-social-media-and-me', 25, 7, '自分が道具を使うことです。', 'じぶん が どうぐ お つかう こと です。', '[{"t":"自分","r":"じぶん"},{"t":"が"},{"t":"道具","r":"どうぐ"},{"t":"を"},{"t":"使","r":"つか"},{"t":"う"},{"t":"こと"},{"t":"です"},{"t":"。"}]'::jsonb, 'but to use the tool yourself.'),
  ('rdg-ja-n2-social-media-and-me-l26', 'rdg-ja-n2-social-media-and-me', 26, 8, '携帯を置いて、目の前の人と', 'けいたい お おいて、め の まえ の ひと と', '[{"t":"携帯","r":"けいたい"},{"t":"を"},{"t":"置","r":"お"},{"t":"いて"},{"t":"、"},{"t":"目","r":"め"},{"t":"の"},{"t":"前","r":"まえ"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"と"}]'::jsonb, 'Put down your phone, and the time spent talking'),
  ('rdg-ja-n2-social-media-and-me-l27', 'rdg-ja-n2-social-media-and-me', 27, 8, '話す時間も大事にしましょう。', 'はなす じかん も だいじ に しましょう。', '[{"t":"話","r":"はな"},{"t":"す"},{"t":"時間","r":"じかん"},{"t":"も"},{"t":"大事","r":"だいじ"},{"t":"に"},{"t":"しましょう"},{"t":"。"}]'::jsonb, 'with the person in front of you — let''s treasure that too.'),
  ('rdg-ja-n2-social-media-and-me-l28', 'rdg-ja-n2-social-media-and-me', 28, 8, '最後まで、ありがとうございました。', 'さいご まで、ありがとうございました。', '[{"t":"最後","r":"さいご"},{"t":"まで"},{"t":"、"},{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you for listening to the end.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n2-social-media-and-me')
ON CONFLICT (reading_id, index) DO NOTHING;

