-- N2 · n2-treasured-object · An object I treasure
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n2-treasured-object', 'lang-ja', ll.id, 'n2-treasured-object', '私の宝物', 'An object I treasure', false, 17
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N2'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n2-treasured-object-l0', 'rdg-ja-n2-treasured-object', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n2-treasured-object-l1', 'rdg-ja-n2-treasured-object', 1, 0, '今日は、私の宝物を', 'きょう わ、わたし の たからもの お', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"宝物","r":"たからもの"},{"t":"を"}]'::jsonb, 'Today I would like to introduce'),
  ('rdg-ja-n2-treasured-object-l2', 'rdg-ja-n2-treasured-object', 2, 0, '紹介したいと思います。', 'しょうかい したい と おもいます。', '[{"t":"紹介","r":"しょうかい"},{"t":"したい"},{"t":"と"},{"t":"思","r":"おも"},{"t":"います"},{"t":"。"}]'::jsonb, 'my treasure.'),
  ('rdg-ja-n2-treasured-object-l3', 'rdg-ja-n2-treasured-object', 3, 1, 'それは、古い腕時計です。', 'それ わ、ふるい うでどけい です。', '[{"t":"それ"},{"t":"は"},{"t":"、"},{"t":"古","r":"ふる"},{"t":"い"},{"t":"腕時計","r":"うでどけい"},{"t":"です"},{"t":"。"}]'::jsonb, 'It is an old wristwatch.'),
  ('rdg-ja-n2-treasured-object-l4', 'rdg-ja-n2-treasured-object', 4, 1, '高いものではありません。', 'たかい もの で わ ありません。', '[{"t":"高","r":"たか"},{"t":"い"},{"t":"もの"},{"t":"では"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'It is not expensive.'),
  ('rdg-ja-n2-treasured-object-l5', 'rdg-ja-n2-treasured-object', 5, 1, '傷だらけで、ベルトも', 'きず だらけ で、ベルト も', '[{"t":"傷","r":"きず"},{"t":"だらけ"},{"t":"で"},{"t":"、"},{"t":"ベルト"},{"t":"も"}]'::jsonb, 'It is covered in scratches,'),
  ('rdg-ja-n2-treasured-object-l6', 'rdg-ja-n2-treasured-object', 6, 1, '少し切れかかっています。', 'すこし きれかかって います。', '[{"t":"少","r":"すこ"},{"t":"し"},{"t":"切","r":"き"},{"t":"れ"},{"t":"かかって"},{"t":"います"},{"t":"。"}]'::jsonb, 'and the strap is starting to tear.'),
  ('rdg-ja-n2-treasured-object-l7', 'rdg-ja-n2-treasured-object', 7, 2, '腕時計は、父が若い頃に', 'うでどけい わ、ちち が わかい ころ に', '[{"t":"腕時計","r":"うでどけい"},{"t":"は"},{"t":"、"},{"t":"父","r":"ちち"},{"t":"が"},{"t":"若","r":"わか"},{"t":"い"},{"t":"頃","r":"ころ"},{"t":"に"}]'::jsonb, 'My father bought this watch'),
  ('rdg-ja-n2-treasured-object-l8', 'rdg-ja-n2-treasured-object', 8, 2, '初めての給料で買ったものです。', 'はじめて の きゅうりょう で かった もの です。', '[{"t":"初","r":"はじ"},{"t":"めて"},{"t":"の"},{"t":"給料","r":"きゅうりょう"},{"t":"で"},{"t":"買","r":"か"},{"t":"った"},{"t":"もの"},{"t":"です"},{"t":"。"}]'::jsonb, 'with his first salary when he was young.'),
  ('rdg-ja-n2-treasured-object-l9', 'rdg-ja-n2-treasured-object', 9, 2, '二十歳の誕生日に、', 'はたち の たんじょうび に、', '[{"t":"二十歳","r":"はたち"},{"t":"の"},{"t":"誕生日","r":"たんじょうび"},{"t":"に"},{"t":"、"}]'::jsonb, 'On my twentieth birthday,'),
  ('rdg-ja-n2-treasured-object-l10', 'rdg-ja-n2-treasured-object', 10, 2, '父はそれを私にくれました。', 'ちち わ それ お わたし に くれました。', '[{"t":"父","r":"ちち"},{"t":"は"},{"t":"それ"},{"t":"を"},{"t":"私","r":"わたし"},{"t":"に"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'he gave it to me.'),
  ('rdg-ja-n2-treasured-object-l11', 'rdg-ja-n2-treasured-object', 11, 3, '「時間を大切にしなさい」と', '「じかん お たいせつ に しなさい」と', '[{"t":"「"},{"t":"時間","r":"じかん"},{"t":"を"},{"t":"大切","r":"たいせつ"},{"t":"に"},{"t":"しなさい"},{"t":"」"},{"t":"と"}]'::jsonb, '"Value your time,"'),
  ('rdg-ja-n2-treasured-object-l12', 'rdg-ja-n2-treasured-object', 12, 3, '父は短く言っただけでした。', 'ちち わ みじかく いった だけ でした。', '[{"t":"父","r":"ちち"},{"t":"は"},{"t":"短","r":"みじか"},{"t":"く"},{"t":"言","r":"い"},{"t":"った"},{"t":"だけ"},{"t":"でした"},{"t":"。"}]'::jsonb, 'was all my father said, briefly.'),
  ('rdg-ja-n2-treasured-object-l13', 'rdg-ja-n2-treasured-object', 13, 3, 'あの時の私は、', 'あの とき の わたし わ、', '[{"t":"あの"},{"t":"時","r":"とき"},{"t":"の"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"}]'::jsonb, 'At that time, I'),
  ('rdg-ja-n2-treasured-object-l14', 'rdg-ja-n2-treasured-object', 14, 3, '意味がよくわかりませんでした。', 'いみ が よく わかりませんでした。', '[{"t":"意味","r":"いみ"},{"t":"が"},{"t":"よく"},{"t":"わかりませんでした"},{"t":"。"}]'::jsonb, 'did not understand the meaning well.'),
  ('rdg-ja-n2-treasured-object-l15', 'rdg-ja-n2-treasured-object', 15, 4, '今は、少しわかる気がします。', 'いま わ、すこし わかる き が します。', '[{"t":"今","r":"いま"},{"t":"は"},{"t":"、"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"わかる"},{"t":"気","r":"き"},{"t":"が"},{"t":"します"},{"t":"。"}]'::jsonb, 'Now, I feel I understand a little.'),
  ('rdg-ja-n2-treasured-object-l16', 'rdg-ja-n2-treasured-object', 16, 4, '毎朝、時計をつけるたびに、', 'まいあさ、とけい お つける たび に、', '[{"t":"毎朝","r":"まいあさ"},{"t":"、"},{"t":"時計","r":"とけい"},{"t":"を"},{"t":"つける"},{"t":"たびに"},{"t":"、"}]'::jsonb, 'Every time I put this watch on in the morning,'),
  ('rdg-ja-n2-treasured-object-l17', 'rdg-ja-n2-treasured-object', 17, 4, '父の働く姿を思い出すのです。', 'ちち の はたらく すがた お おもいだす の です。', '[{"t":"父","r":"ちち"},{"t":"の"},{"t":"働","r":"はたら"},{"t":"く"},{"t":"姿","r":"すがた"},{"t":"を"},{"t":"思","r":"おも"},{"t":"い"},{"t":"出","r":"だ"},{"t":"す"},{"t":"のです"},{"t":"。"}]'::jsonb, 'I remember my father at work.'),
  ('rdg-ja-n2-treasured-object-l18', 'rdg-ja-n2-treasured-object', 18, 5, '去年、時計が止まりました。', 'きょねん、とけい が とまりました。', '[{"t":"去年","r":"きょねん"},{"t":"、"},{"t":"時計","r":"とけい"},{"t":"が"},{"t":"止","r":"と"},{"t":"まりました"},{"t":"。"}]'::jsonb, 'Last year, the watch stopped.'),
  ('rdg-ja-n2-treasured-object-l19', 'rdg-ja-n2-treasured-object', 19, 5, '店の人は、新しいものを', 'みせ の ひと わ、あたらしい もの お', '[{"t":"店","r":"みせ"},{"t":"の"},{"t":"人","r":"ひと"},{"t":"は"},{"t":"、"},{"t":"新","r":"あたら"},{"t":"しい"},{"t":"もの"},{"t":"を"}]'::jsonb, 'The shop clerk recommended'),
  ('rdg-ja-n2-treasured-object-l20', 'rdg-ja-n2-treasured-object', 20, 5, '買うように勧めました。', 'かう よう に すすめました。', '[{"t":"買","r":"か"},{"t":"う"},{"t":"よう"},{"t":"に"},{"t":"勧","r":"すす"},{"t":"めました"},{"t":"。"}]'::jsonb, 'that I buy a new one.'),
  ('rdg-ja-n2-treasured-object-l21', 'rdg-ja-n2-treasured-object', 21, 6, 'けれど、私は', 'けれど、わたし わ', '[{"t":"けれど"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"は"}]'::jsonb, 'But I'),
  ('rdg-ja-n2-treasured-object-l22', 'rdg-ja-n2-treasured-object', 22, 6, '直してもらうことにしました。', 'なおして もらう こと に しました。', '[{"t":"直","r":"なお"},{"t":"して"},{"t":"もらう"},{"t":"こと"},{"t":"に"},{"t":"しました"},{"t":"。"}]'::jsonb, 'decided to have it repaired.'),
  ('rdg-ja-n2-treasured-object-l23', 'rdg-ja-n2-treasured-object', 23, 7, '直った時計が動き出した時、', 'なおった とけい が うごきだした とき、', '[{"t":"直","r":"なお"},{"t":"った"},{"t":"時計","r":"とけい"},{"t":"が"},{"t":"動","r":"うご"},{"t":"き"},{"t":"出","r":"だ"},{"t":"した"},{"t":"時","r":"とき"},{"t":"、"}]'::jsonb, 'When the repaired watch started ticking,'),
  ('rdg-ja-n2-treasured-object-l24', 'rdg-ja-n2-treasured-object', 24, 7, '本当に安心しました。', 'ほんとう に あんしん しました。', '[{"t":"本当","r":"ほんとう"},{"t":"に"},{"t":"安心","r":"あんしん"},{"t":"しました"},{"t":"。"}]'::jsonb, 'I was truly relieved.'),
  ('rdg-ja-n2-treasured-object-l25', 'rdg-ja-n2-treasured-object', 25, 7, '物の値段と、思い出の価値は', 'もの の ねだん と、おもいで の かち わ', '[{"t":"物","r":"もの"},{"t":"の"},{"t":"値段","r":"ねだん"},{"t":"と"},{"t":"、"},{"t":"思","r":"おも"},{"t":"い"},{"t":"出","r":"で"},{"t":"の"},{"t":"価値","r":"かち"},{"t":"は"}]'::jsonb, 'The price of a thing and the value of its memories'),
  ('rdg-ja-n2-treasured-object-l26', 'rdg-ja-n2-treasured-object', 26, 7, '関係がないと思います。', 'かんけい が ない と おもいます。', '[{"t":"関係","r":"かんけい"},{"t":"が"},{"t":"ない"},{"t":"と"},{"t":"思","r":"おも"},{"t":"います"},{"t":"。"}]'::jsonb, 'are unrelated.'),
  ('rdg-ja-n2-treasured-object-l27', 'rdg-ja-n2-treasured-object', 27, 8, 'いつか私にも子供ができたら、', 'いつか わたし に も こども が できたら、', '[{"t":"いつか"},{"t":"私","r":"わたし"},{"t":"にも"},{"t":"子供","r":"こども"},{"t":"が"},{"t":"できたら"},{"t":"、"}]'::jsonb, 'If someday I have children of my own,'),
  ('rdg-ja-n2-treasured-object-l28', 'rdg-ja-n2-treasured-object', 28, 8, '腕時計を渡したいです。', 'うでどけい お わたしたい です。', '[{"t":"腕時計","r":"うでどけい"},{"t":"を"},{"t":"渡","r":"わた"},{"t":"したい"},{"t":"です"},{"t":"。"}]'::jsonb, 'I want to pass this watch on.'),
  ('rdg-ja-n2-treasured-object-l29', 'rdg-ja-n2-treasured-object', 29, 8, 'お聞きいただき、ありがとうございました。', 'おきき いただき、ありがとうございました。', '[{"t":"お"},{"t":"聞","r":"き"},{"t":"きいただき"},{"t":"、"},{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you for listening.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n2-treasured-object')
