-- N2 · n2-hard-choice · A hard choice I made
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n2-hard-choice', 'lang-ja', ll.id, 'n2-hard-choice', '難しい選択', 'A hard choice I made', false, 18
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N2'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n2-hard-choice-l0', 'rdg-ja-n2-hard-choice', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n2-hard-choice-l1', 'rdg-ja-n2-hard-choice', 1, 0, '私の人生を変えた', 'わたし の じんせい お かえた', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"人生","r":"じんせい"},{"t":"を"},{"t":"変","r":"か"},{"t":"えた"}]'::jsonb, 'I would like to talk about'),
  ('rdg-ja-n2-hard-choice-l2', 'rdg-ja-n2-hard-choice', 2, 0, '選択についてお話しします。', 'せんたく に ついて おはなし します。', '[{"t":"選択","r":"せんたく"},{"t":"について"},{"t":"お"},{"t":"話","r":"はな"},{"t":"し"},{"t":"します"},{"t":"。"}]'::jsonb, 'the choice that changed my life.'),
  ('rdg-ja-n2-hard-choice-l3', 'rdg-ja-n2-hard-choice', 3, 1, '大学を出た年、私には', 'だいがく お でた とし、わたし に わ', '[{"t":"大学","r":"だいがく"},{"t":"を"},{"t":"出","r":"で"},{"t":"た"},{"t":"年","r":"とし"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"に"},{"t":"は"}]'::jsonb, 'The year I left university, I had'),
  ('rdg-ja-n2-hard-choice-l4', 'rdg-ja-n2-hard-choice', 4, 1, '二つの道がありました。', 'ふたつ の みち が ありました。', '[{"t":"二","r":"ふた"},{"t":"つ"},{"t":"の"},{"t":"道","r":"みち"},{"t":"が"},{"t":"ありました"},{"t":"。"}]'::jsonb, 'two paths before me.'),
  ('rdg-ja-n2-hard-choice-l5', 'rdg-ja-n2-hard-choice', 5, 1, '一つは、地元の安定した会社。', 'ひとつ わ、じもと の あんてい した かいしゃ。', '[{"t":"一","r":"ひと"},{"t":"つ"},{"t":"は"},{"t":"、"},{"t":"地元","r":"じもと"},{"t":"の"},{"t":"安定","r":"あんてい"},{"t":"した"},{"t":"会社","r":"かいしゃ"},{"t":"。"}]'::jsonb, 'One was a stable company in my hometown.'),
  ('rdg-ja-n2-hard-choice-l6', 'rdg-ja-n2-hard-choice', 6, 1, 'もう一つは、外国での仕事です。', 'もうひとつ わ、がいこく で の しごと です。', '[{"t":"もう"},{"t":"一","r":"ひと"},{"t":"つ"},{"t":"は"},{"t":"、"},{"t":"外国","r":"がいこく"},{"t":"で"},{"t":"の"},{"t":"仕事","r":"しごと"},{"t":"です"},{"t":"。"}]'::jsonb, 'The other was a job abroad.'),
  ('rdg-ja-n2-hard-choice-l7', 'rdg-ja-n2-hard-choice', 7, 2, '両親は、地元に残ってほしいと', 'りょうしん わ、じもと に のこって ほしい と', '[{"t":"両親","r":"りょうしん"},{"t":"は"},{"t":"、"},{"t":"地元","r":"じもと"},{"t":"に"},{"t":"残","r":"のこ"},{"t":"って"},{"t":"ほしい"},{"t":"と"}]'::jsonb, 'My parents said they wanted me to stay'),
  ('rdg-ja-n2-hard-choice-l8', 'rdg-ja-n2-hard-choice', 8, 2, '言いました。', 'いいました。', '[{"t":"言","r":"い"},{"t":"いました"},{"t":"。"}]'::jsonb, 'in my hometown.'),
  ('rdg-ja-n2-hard-choice-l9', 'rdg-ja-n2-hard-choice', 9, 2, 'でも、私の心は', 'でも、わたし の こころ わ', '[{"t":"でも"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"心","r":"こころ"},{"t":"は"}]'::jsonb, 'But my heart'),
  ('rdg-ja-n2-hard-choice-l10', 'rdg-ja-n2-hard-choice', 10, 2, '外国に向いていました。', 'がいこく に むいて いました。', '[{"t":"外国","r":"がいこく"},{"t":"に"},{"t":"向","r":"む"},{"t":"いて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'was turned toward going abroad.'),
  ('rdg-ja-n2-hard-choice-l11', 'rdg-ja-n2-hard-choice', 11, 3, '何週間も、夜よく眠れませんでした。', 'なんしゅうかん も、よる よく ねむれませんでした。', '[{"t":"何週間","r":"なんしゅうかん"},{"t":"も"},{"t":"、"},{"t":"夜","r":"よる"},{"t":"よく"},{"t":"眠","r":"ねむ"},{"t":"れませんでした"},{"t":"。"}]'::jsonb, 'For weeks, I couldn''t sleep well at night.'),
  ('rdg-ja-n2-hard-choice-l12', 'rdg-ja-n2-hard-choice', 12, 3, '紙に、良い点と悪い点を', 'かみ に、よい てん と わるい てん お', '[{"t":"紙","r":"かみ"},{"t":"に"},{"t":"、"},{"t":"良","r":"よ"},{"t":"い"},{"t":"点","r":"てん"},{"t":"と"},{"t":"悪","r":"わる"},{"t":"い"},{"t":"点","r":"てん"},{"t":"を"}]'::jsonb, 'I wrote the good points and bad points'),
  ('rdg-ja-n2-hard-choice-l13', 'rdg-ja-n2-hard-choice', 13, 3, '何度も書き出しました。', 'なんど も かきだしました。', '[{"t":"何度","r":"なんど"},{"t":"も"},{"t":"書","r":"か"},{"t":"き"},{"t":"出","r":"だ"},{"t":"しました"},{"t":"。"}]'::jsonb, 'on paper over and over.'),
  ('rdg-ja-n2-hard-choice-l14', 'rdg-ja-n2-hard-choice', 14, 3, 'けれど、答えは出ませんでした。', 'けれど、こたえ わ でませんでした。', '[{"t":"けれど"},{"t":"、"},{"t":"答","r":"こた"},{"t":"え"},{"t":"は"},{"t":"出","r":"で"},{"t":"ませんでした"},{"t":"。"}]'::jsonb, 'But no answer came.'),
  ('rdg-ja-n2-hard-choice-l15', 'rdg-ja-n2-hard-choice', 15, 4, '最後に私を動かしたのは、', 'さいご に わたし お うごかした の わ、', '[{"t":"最後","r":"さいご"},{"t":"に"},{"t":"私","r":"わたし"},{"t":"を"},{"t":"動","r":"うご"},{"t":"かした"},{"t":"の"},{"t":"は"},{"t":"、"}]'::jsonb, 'What finally moved me'),
  ('rdg-ja-n2-hard-choice-l16', 'rdg-ja-n2-hard-choice', 16, 4, '一つの質問でした。', 'ひとつ の しつもん でした。', '[{"t":"一","r":"ひと"},{"t":"つ"},{"t":"の"},{"t":"質問","r":"しつもん"},{"t":"でした"},{"t":"。"}]'::jsonb, 'was a single question.'),
  ('rdg-ja-n2-hard-choice-l17', 'rdg-ja-n2-hard-choice', 17, 5, '「十年後の私は、', '「じゅうねんご の わたし わ、', '[{"t":"「"},{"t":"十年後","r":"じゅうねんご"},{"t":"の"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"}]'::jsonb, '"Ten years from now,'),
  ('rdg-ja-n2-hard-choice-l18', 'rdg-ja-n2-hard-choice', 18, 5, 'どちらを選ばなかったことを', 'どちら お えらばなかった こと お', '[{"t":"どちら"},{"t":"を"},{"t":"選","r":"えら"},{"t":"ばなかった"},{"t":"こと"},{"t":"を"}]'::jsonb, 'which one will I regret'),
  ('rdg-ja-n2-hard-choice-l19', 'rdg-ja-n2-hard-choice', 19, 5, '後悔するだろうか」', 'こうかい する だろう か」', '[{"t":"後悔","r":"こうかい"},{"t":"する"},{"t":"だろう"},{"t":"か"},{"t":"」"}]'::jsonb, 'not having chosen?"'),
  ('rdg-ja-n2-hard-choice-l20', 'rdg-ja-n2-hard-choice', 20, 6, '答えは、はっきりしていました。', 'こたえ わ、はっきり して いました。', '[{"t":"答","r":"こた"},{"t":"え"},{"t":"は"},{"t":"、"},{"t":"はっきり"},{"t":"して"},{"t":"いました"},{"t":"。"}]'::jsonb, 'The answer was clear.'),
  ('rdg-ja-n2-hard-choice-l21', 'rdg-ja-n2-hard-choice', 21, 6, '私は外国へ行くことに決めました。', 'わたし わ がいこく え いく こと に きめました。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"外国","r":"がいこく"},{"t":"へ"},{"t":"行","r":"い"},{"t":"く"},{"t":"こと"},{"t":"に"},{"t":"決","r":"き"},{"t":"めました"},{"t":"。"}]'::jsonb, 'I decided to go abroad.'),
  ('rdg-ja-n2-hard-choice-l22', 'rdg-ja-n2-hard-choice', 22, 6, '空港で母は泣きませんでしたが、', 'くうこう で はは わ なきませんでした が、', '[{"t":"空港","r":"くうこう"},{"t":"で"},{"t":"母","r":"はは"},{"t":"は"},{"t":"泣","r":"な"},{"t":"きませんでした"},{"t":"が"},{"t":"、"}]'::jsonb, 'My mother did not cry at the airport,'),
  ('rdg-ja-n2-hard-choice-l23', 'rdg-ja-n2-hard-choice', 23, 6, '手が少し震えていました。', 'て が すこし ふるえて いました。', '[{"t":"手","r":"て"},{"t":"が"},{"t":"少","r":"すこ"},{"t":"し"},{"t":"震","r":"ふる"},{"t":"えて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'but her hands were trembling slightly.'),
  ('rdg-ja-n2-hard-choice-l24', 'rdg-ja-n2-hard-choice', 24, 7, '最初の一年は、', 'さいしょ の いちねん わ、', '[{"t":"最初","r":"さいしょ"},{"t":"の"},{"t":"一年","r":"いちねん"},{"t":"は"},{"t":"、"}]'::jsonb, 'The first year'),
  ('rdg-ja-n2-hard-choice-l25', 'rdg-ja-n2-hard-choice', 25, 7, '本当に大変でした。', 'ほんとう に たいへん でした。', '[{"t":"本当","r":"ほんとう"},{"t":"に"},{"t":"大変","r":"たいへん"},{"t":"でした"},{"t":"。"}]'::jsonb, 'was truly hard.'),
  ('rdg-ja-n2-hard-choice-l26', 'rdg-ja-n2-hard-choice', 26, 7, 'それでも、あの選択が', 'それ でも、あの せんたく が', '[{"t":"それ"},{"t":"でも"},{"t":"、"},{"t":"あの"},{"t":"選択","r":"せんたく"},{"t":"が"}]'::jsonb, 'Even so, I do not think'),
  ('rdg-ja-n2-hard-choice-l27', 'rdg-ja-n2-hard-choice', 27, 7, '間違いだったとは思いません。', 'まちがい だった と わ おもいません。', '[{"t":"間違","r":"まちが"},{"t":"い"},{"t":"だった"},{"t":"とは"},{"t":"思","r":"おも"},{"t":"いません"},{"t":"。"}]'::jsonb, 'that choice was a mistake.'),
  ('rdg-ja-n2-hard-choice-l28', 'rdg-ja-n2-hard-choice', 28, 8, '人生は、正しい道を選ぶのではなく、', 'じんせい わ、ただしい みち お えらぶ の で わ なく、', '[{"t":"人生","r":"じんせい"},{"t":"は"},{"t":"、"},{"t":"正","r":"ただ"},{"t":"しい"},{"t":"道","r":"みち"},{"t":"を"},{"t":"選","r":"えら"},{"t":"ぶ"},{"t":"ので"},{"t":"は"},{"t":"なく"},{"t":"、"}]'::jsonb, 'Life is not about choosing the right path,'),
  ('rdg-ja-n2-hard-choice-l29', 'rdg-ja-n2-hard-choice', 29, 8, '選んだ道を正しくしていくものだと', 'えらんだ みち お ただしく して いく もの だ と', '[{"t":"選","r":"えら"},{"t":"んだ"},{"t":"道","r":"みち"},{"t":"を"},{"t":"正","r":"ただ"},{"t":"しく"},{"t":"して"},{"t":"いく"},{"t":"ものだ"},{"t":"と"}]'::jsonb, 'but about making the path you chose right —'),
  ('rdg-ja-n2-hard-choice-l30', 'rdg-ja-n2-hard-choice', 30, 8, '学びました。', 'まなびました。', '[{"t":"学","r":"まな"},{"t":"びました"},{"t":"。"}]'::jsonb, 'that is what I learned.'),
  ('rdg-ja-n2-hard-choice-l31', 'rdg-ja-n2-hard-choice', 31, 9, '私の話は、以上です。', 'わたし の はなし わ、いじょう です。', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"は"},{"t":"、"},{"t":"以上","r":"いじょう"},{"t":"です"},{"t":"。"}]'::jsonb, 'That is the end of my talk.'),
  ('rdg-ja-n2-hard-choice-l32', 'rdg-ja-n2-hard-choice', 32, 9, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n2-hard-choice')
ON CONFLICT (reading_id, index) DO NOTHING;

INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, origin, priority, status)
SELECT 'crq-rdg-ja-n2-hard-choice', 'lang-ja', 'readings', 'rdg-ja-n2-hard-choice', 'create', '{"code":"n2-hard-choice","level":"N2"}'::jsonb, 'ai', 4, 'pending'
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n2-hard-choice' AND NOT published)
  AND NOT EXISTS (SELECT 1 FROM content_review_queue WHERE target_table = 'readings' AND target_id = 'rdg-ja-n2-hard-choice')
ON CONFLICT DO NOTHING;

-- N2 · n2-grandparents-taught-me · What my grandparents taught me
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n2-grandparents-taught-me', 'lang-ja', ll.id, 'n2-grandparents-taught-me', '祖父母から学んだこと', 'What my grandparents taught me', false, 19
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N2'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n2-grandparents-taught-me-l0', 'rdg-ja-n2-grandparents-taught-me', 0, 0, 'みなさん、こんにちは。', 'みなさん、こんにちわ。', '[{"t":"みなさん"},{"t":"、"},{"t":"こんにちは"},{"t":"。"}]'::jsonb, 'Hello, everyone.'),
  ('rdg-ja-n2-grandparents-taught-me-l1', 'rdg-ja-n2-grandparents-taught-me', 1, 0, '今日は、私の祖父母について', 'きょう わ、わたし の そふぼ に ついて', '[{"t":"今日","r":"きょう"},{"t":"は"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"祖父母","r":"そふぼ"},{"t":"について"}]'::jsonb, 'Today I would like to speak'),
  ('rdg-ja-n2-grandparents-taught-me-l2', 'rdg-ja-n2-grandparents-taught-me', 2, 0, 'お話しします。', 'おはなし します。', '[{"t":"お"},{"t":"話","r":"はな"},{"t":"し"},{"t":"します"},{"t":"。"}]'::jsonb, 'about my grandparents.'),
  ('rdg-ja-n2-grandparents-taught-me-l3', 'rdg-ja-n2-grandparents-taught-me', 3, 1, '子供の頃、夏休みになると、', 'こども の ころ、なつやすみ に なる と、', '[{"t":"子供","r":"こども"},{"t":"の"},{"t":"頃","r":"ころ"},{"t":"、"},{"t":"夏休","r":"なつやす"},{"t":"み"},{"t":"に"},{"t":"なる"},{"t":"と"},{"t":"、"}]'::jsonb, 'As a child, when summer vacation came,'),
  ('rdg-ja-n2-grandparents-taught-me-l4', 'rdg-ja-n2-grandparents-taught-me', 4, 1, '私は毎年、田舎にある', 'わたし わ まいとし、いなか に ある', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"毎年","r":"まいとし"},{"t":"、"},{"t":"田舎","r":"いなか"},{"t":"に"},{"t":"ある"}]'::jsonb, 'every year I stayed'),
  ('rdg-ja-n2-grandparents-taught-me-l5', 'rdg-ja-n2-grandparents-taught-me', 5, 1, '祖父母の家に泊まりに行っていました。', 'そふぼ の いえ に とまり に いって いました。', '[{"t":"祖父母","r":"そふぼ"},{"t":"の"},{"t":"家","r":"いえ"},{"t":"に"},{"t":"泊","r":"と"},{"t":"まりに"},{"t":"行","r":"い"},{"t":"って"},{"t":"いました"},{"t":"。"}]'::jsonb, 'at my grandparents'' house in the countryside.'),
  ('rdg-ja-n2-grandparents-taught-me-l6', 'rdg-ja-n2-grandparents-taught-me', 6, 2, '祖父は朝五時に起きて、', 'そふ わ あさ ごじ に おきて、', '[{"t":"祖父","r":"そふ"},{"t":"は"},{"t":"朝","r":"あさごじ"},{"t":"五時"},{"t":"に"},{"t":"起","r":"お"},{"t":"きて"},{"t":"、"}]'::jsonb, 'My grandfather got up at five in the morning'),
  ('rdg-ja-n2-grandparents-taught-me-l7', 'rdg-ja-n2-grandparents-taught-me', 7, 2, '畑で野菜を育てていました。', 'はたけ で やさい お そだてて いました。', '[{"t":"畑","r":"はたけ"},{"t":"で"},{"t":"野菜","r":"やさい"},{"t":"を"},{"t":"育","r":"そだ"},{"t":"てて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'and grew vegetables in the field.'),
  ('rdg-ja-n2-grandparents-taught-me-l8', 'rdg-ja-n2-grandparents-taught-me', 8, 2, '「土は、裏切らない」と', '「つち わ、うらぎらない」と', '[{"t":"「"},{"t":"土","r":"つち"},{"t":"は"},{"t":"、"},{"t":"裏切","r":"うらぎ"},{"t":"らない"},{"t":"」"},{"t":"と"}]'::jsonb, '"Soil does not betray you,"'),
  ('rdg-ja-n2-grandparents-taught-me-l9', 'rdg-ja-n2-grandparents-taught-me', 9, 2, 'よく言っていました。', 'よく いって いました。', '[{"t":"よく"},{"t":"言","r":"い"},{"t":"って"},{"t":"いました"},{"t":"。"}]'::jsonb, 'he often said.'),
  ('rdg-ja-n2-grandparents-taught-me-l10', 'rdg-ja-n2-grandparents-taught-me', 10, 3, '手をかければ、野菜は必ず', 'て お かければ、やさい わ かならず', '[{"t":"手","r":"て"},{"t":"を"},{"t":"かければ"},{"t":"、"},{"t":"野菜","r":"やさい"},{"t":"は"},{"t":"必","r":"かなら"},{"t":"ず"}]'::jsonb, 'If you put in the effort, the vegetables will surely'),
  ('rdg-ja-n2-grandparents-taught-me-l11', 'rdg-ja-n2-grandparents-taught-me', 11, 3, 'それに応えてくれる、という意味です。', 'それ に こたえて くれる、と いう いみ です。', '[{"t":"それ"},{"t":"に"},{"t":"応","r":"こた"},{"t":"え"},{"t":"てくれる"},{"t":"、"},{"t":"という"},{"t":"意味","r":"いみ"},{"t":"です"},{"t":"。"}]'::jsonb, 'respond to it. That was what he meant.'),
  ('rdg-ja-n2-grandparents-taught-me-l12', 'rdg-ja-n2-grandparents-taught-me', 12, 3, '今、仕事で結果が出ない時、', 'いま、しごと で けっか が でない とき、', '[{"t":"今","r":"いま"},{"t":"、"},{"t":"仕事","r":"しごと"},{"t":"で"},{"t":"結果","r":"けっか"},{"t":"が"},{"t":"出","r":"で"},{"t":"ない"},{"t":"時","r":"とき"},{"t":"、"}]'::jsonb, 'Now, when my work shows no results,'),
  ('rdg-ja-n2-grandparents-taught-me-l13', 'rdg-ja-n2-grandparents-taught-me', 13, 3, 'あの言葉を思い出します。', 'あの ことば お おもいだします。', '[{"t":"あの"},{"t":"言葉","r":"ことば"},{"t":"を"},{"t":"思","r":"おも"},{"t":"い"},{"t":"出","r":"だ"},{"t":"します"},{"t":"。"}]'::jsonb, 'I remember those words.'),
  ('rdg-ja-n2-grandparents-taught-me-l14', 'rdg-ja-n2-grandparents-taught-me', 14, 4, '祖母は、いつも台所に立っている人でした。', 'そぼ わ、いつも だいどころ に たって いる ひと でした。', '[{"t":"祖母","r":"そぼ"},{"t":"は"},{"t":"、"},{"t":"いつも"},{"t":"台所","r":"だいどころ"},{"t":"に"},{"t":"立","r":"た"},{"t":"って"},{"t":"いる"},{"t":"人","r":"ひと"},{"t":"でした"},{"t":"。"}]'::jsonb, 'My grandmother was always in the kitchen.'),
  ('rdg-ja-n2-grandparents-taught-me-l15', 'rdg-ja-n2-grandparents-taught-me', 15, 4, '料理を教えてくれる時も、', 'りょうり お おしえて くれる とき も、', '[{"t":"料理","r":"りょうり"},{"t":"を"},{"t":"教","r":"おし"},{"t":"えて"},{"t":"くれる"},{"t":"時","r":"とき"},{"t":"も"},{"t":"、"}]'::jsonb, 'Even when she taught me to cook,'),
  ('rdg-ja-n2-grandparents-taught-me-l16', 'rdg-ja-n2-grandparents-taught-me', 16, 4, '量りは一度も使いませんでした。', 'はかり わ いちど も つかいませんでした。', '[{"t":"量","r":"はか"},{"t":"り"},{"t":"は"},{"t":"一度","r":"いちど"},{"t":"も"},{"t":"使","r":"つか"},{"t":"いませんでした"},{"t":"。"}]'::jsonb, 'she never once used a scale.'),
  ('rdg-ja-n2-grandparents-taught-me-l17', 'rdg-ja-n2-grandparents-taught-me', 17, 5, '「手が覚えているよ」と', '「て が おぼえて いる よ」と', '[{"t":"「"},{"t":"手","r":"て"},{"t":"が"},{"t":"覚","r":"おぼ"},{"t":"えて"},{"t":"いる"},{"t":"よ"},{"t":"」"},{"t":"と"}]'::jsonb, '"My hands remember,"'),
  ('rdg-ja-n2-grandparents-taught-me-l18', 'rdg-ja-n2-grandparents-taught-me', 18, 5, '笑うだけでした。', 'わらう だけ でした。', '[{"t":"笑","r":"わら"},{"t":"う"},{"t":"だけ"},{"t":"でした"},{"t":"。"}]'::jsonb, 'was all she would say, laughing.'),
  ('rdg-ja-n2-grandparents-taught-me-l19', 'rdg-ja-n2-grandparents-taught-me', 19, 6, '二人に共通していたのは、', 'ふたり に きょうつう して いた の わ、', '[{"t":"二人","r":"ふたり"},{"t":"に"},{"t":"共通","r":"きょうつう"},{"t":"して"},{"t":"いた"},{"t":"の"},{"t":"は"},{"t":"、"}]'::jsonb, 'What the two of them had in common'),
  ('rdg-ja-n2-grandparents-taught-me-l20', 'rdg-ja-n2-grandparents-taught-me', 20, 6, '急がないことでした。', 'いそがない こと でした。', '[{"t":"急","r":"いそ"},{"t":"がない"},{"t":"こと"},{"t":"でした"},{"t":"。"}]'::jsonb, 'was that they never hurried.'),
  ('rdg-ja-n2-grandparents-taught-me-l21', 'rdg-ja-n2-grandparents-taught-me', 21, 6, 'お茶を飲みながら、', 'おちゃ お のみながら、', '[{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"を"},{"t":"飲","r":"の"},{"t":"みながら"},{"t":"、"}]'::jsonb, 'While drinking tea,'),
  ('rdg-ja-n2-grandparents-taught-me-l22', 'rdg-ja-n2-grandparents-taught-me', 22, 6, '何時間でも話を聞いてくれました。', 'なんじかん でも はなし お きいて くれました。', '[{"t":"何時間","r":"なんじかん"},{"t":"でも"},{"t":"話","r":"はなし"},{"t":"を"},{"t":"聞","r":"き"},{"t":"いて"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'they would listen to me for hours.'),
  ('rdg-ja-n2-grandparents-taught-me-l23', 'rdg-ja-n2-grandparents-taught-me', 23, 7, '大人になった今、', 'おとな に なった いま、', '[{"t":"大人","r":"おとな"},{"t":"に"},{"t":"なった"},{"t":"今","r":"いま"},{"t":"、"}]'::jsonb, 'Now that I am an adult,'),
  ('rdg-ja-n2-grandparents-taught-me-l24', 'rdg-ja-n2-grandparents-taught-me', 24, 7, 'あの時間がどれほど', 'あの じかん が どれほど', '[{"t":"あの"},{"t":"時間","r":"じかん"},{"t":"が"},{"t":"どれほど"}]'::jsonb, 'I truly understand'),
  ('rdg-ja-n2-grandparents-taught-me-l25', 'rdg-ja-n2-grandparents-taught-me', 25, 7, '贅沢だったか、よくわかります。', 'ぜいたく だった か、よく わかります。', '[{"t":"贅沢","r":"ぜいたく"},{"t":"だった"},{"t":"か"},{"t":"、"},{"t":"よく"},{"t":"わかります"},{"t":"。"}]'::jsonb, 'what a luxury that time was.'),
  ('rdg-ja-n2-grandparents-taught-me-l26', 'rdg-ja-n2-grandparents-taught-me', 26, 8, '祖父母が教えてくれたのは、', 'そふぼ が おしえて くれた の わ、', '[{"t":"祖父母","r":"そふぼ"},{"t":"が"},{"t":"教","r":"おし"},{"t":"えて"},{"t":"くれた"},{"t":"の"},{"t":"は"},{"t":"、"}]'::jsonb, 'What my grandparents taught me'),
  ('rdg-ja-n2-grandparents-taught-me-l27', 'rdg-ja-n2-grandparents-taught-me', 27, 8, '知識ではなく、生き方でした。', 'ちしき で わ なく、いきかた でした。', '[{"t":"知識","r":"ちしき"},{"t":"では"},{"t":"なく"},{"t":"、"},{"t":"生","r":"い"},{"t":"き"},{"t":"方","r":"かた"},{"t":"でした"},{"t":"。"}]'::jsonb, 'was not knowledge, but a way of living.'),
  ('rdg-ja-n2-grandparents-taught-me-l28', 'rdg-ja-n2-grandparents-taught-me', 28, 8, '私も、誰かにとってそんな人に', 'わたし も、だれか に とって そんな ひと に', '[{"t":"私","r":"わたし"},{"t":"も"},{"t":"、"},{"t":"誰","r":"だれ"},{"t":"か"},{"t":"にとって"},{"t":"そんな"},{"t":"人","r":"ひと"},{"t":"に"}]'::jsonb, 'I hope to become that kind of person'),
  ('rdg-ja-n2-grandparents-taught-me-l29', 'rdg-ja-n2-grandparents-taught-me', 29, 8, 'なれたらと思います。', 'なれたら と おもいます。', '[{"t":"なれたら"},{"t":"と"},{"t":"思","r":"おも"},{"t":"います"},{"t":"。"}]'::jsonb, 'for someone, too.'),
  ('rdg-ja-n2-grandparents-taught-me-l30', 'rdg-ja-n2-grandparents-taught-me', 30, 9, '私の話は、これで終わりです。', 'わたし の はなし わ、これ で おわり です。', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"話","r":"はなし"},{"t":"は"},{"t":"、"},{"t":"これ"},{"t":"で"},{"t":"終","r":"お"},{"t":"わり"},{"t":"です"},{"t":"。"}]'::jsonb, 'That is all of my story.'),
  ('rdg-ja-n2-grandparents-taught-me-l31', 'rdg-ja-n2-grandparents-taught-me', 31, 9, 'ありがとうございました。', 'ありがとうございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n2-grandparents-taught-me')
ON CONFLICT (reading_id, index) DO NOTHING;

