-- N1 · n1-wedding-toast · A speech at a friend's wedding
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n1-wedding-toast', 'lang-ja', ll.id, 'n1-wedding-toast', '友人の結婚式でのスピーチ', 'A speech at a friend''s wedding', false, 20
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N1'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n1-wedding-toast-l0', 'rdg-ja-n1-wedding-toast', 0, 0, '皆様、本日はお呼びくださり、誠にありがとうございます。', 'みなさま、ほんじつ わ および くださり、まことに ありがとう ございます。', '[{"t":"皆様","r":"みなさま"},{"t":"、"},{"t":"本日","r":"ほんじつ"},{"t":"は"},{"t":"お"},{"t":"呼","r":"よ"},{"t":"びくださり"},{"t":"、"},{"t":"誠","r":"まこと"},{"t":"に"},{"t":"ありがとうございます"},{"t":"。"}]'::jsonb, 'Everyone, thank you sincerely for inviting me today.'),
  ('rdg-ja-n1-wedding-toast-l1', 'rdg-ja-n1-wedding-toast', 1, 0, '新郎の友人として、一言ご挨拶をさせていただきます。', 'しんろう の ゆうじん として、ひとこと ごあいさつ お させて いただきます。', '[{"t":"新郎","r":"しんろう"},{"t":"の"},{"t":"友人","r":"ゆうじん"},{"t":"として"},{"t":"、"},{"t":"一言","r":"ひとこと"},{"t":"ご"},{"t":"挨拶","r":"あいさつ"},{"t":"を"},{"t":"させていただきます"},{"t":"。"}]'::jsonb, 'As the groom''s friend, allow me to say a few words.'),
  ('rdg-ja-n1-wedding-toast-l2', 'rdg-ja-n1-wedding-toast', 2, 0, 'お二人を前にして、胸が熱くなります。', 'おふたり お まえ に して、むね が あつく なります。', '[{"t":"お"},{"t":"二人","r":"ふたり"},{"t":"を"},{"t":"前","r":"まえ"},{"t":"に"},{"t":"して"},{"t":"、"},{"t":"胸","r":"むね"},{"t":"が"},{"t":"熱","r":"あつ"},{"t":"く"},{"t":"なります"},{"t":"。"}]'::jsonb, 'Standing before you both, my heart is full.'),
  ('rdg-ja-n1-wedding-toast-l3', 'rdg-ja-n1-wedding-toast', 3, 1, '彼と出会ったのは、大学の入学式でした。', 'かれ と であった の わ、だいがく の にゅうがくしき でした。', '[{"t":"彼","r":"かれ"},{"t":"と"},{"t":"出会","r":"であ"},{"t":"った"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"大学","r":"だいがく"},{"t":"の"},{"t":"入学式","r":"にゅうがくしき"},{"t":"でした"},{"t":"。"}]'::jsonb, 'I met him at our university entrance ceremony.'),
  ('rdg-ja-n1-wedding-toast-l4', 'rdg-ja-n1-wedding-toast', 4, 1, '隣の席に座っていた彼は、', 'となり の せき に すわって いた かれ わ、', '[{"t":"隣","r":"となり"},{"t":"の"},{"t":"席","r":"せき"},{"t":"に"},{"t":"座","r":"すわ"},{"t":"って"},{"t":"いた"},{"t":"彼","r":"かれ"},{"t":"は"},{"t":"、"}]'::jsonb, 'He was sitting in the next seat,'),
  ('rdg-ja-n1-wedding-toast-l5', 'rdg-ja-n1-wedding-toast', 5, 1, '緊張のあまり、ネクタイを裏返しに締めていました。', 'きんちょう の あまり、ネクタイ お うらがえし に しめて いました。', '[{"t":"緊張","r":"きんちょう"},{"t":"の"},{"t":"あまり"},{"t":"、"},{"t":"ネクタイ"},{"t":"を"},{"t":"裏返","r":"うらがえ"},{"t":"し"},{"t":"に"},{"t":"締","r":"し"},{"t":"めて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'so nervous that he had tied his tie inside out.'),
  ('rdg-ja-n1-wedding-toast-l6', 'rdg-ja-n1-wedding-toast', 6, 2, 'それから二十年、私と彼の付き合いは今も続いています。', 'それから にじゅうねん、わたし と かれ の つきあい わ いま も つづいて います。', '[{"t":"それから"},{"t":"二十年","r":"にじゅうねん"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"と"},{"t":"彼","r":"かれ"},{"t":"の"},{"t":"付","r":"つ"},{"t":"き"},{"t":"合","r":"あ"},{"t":"い"},{"t":"は"},{"t":"今","r":"いま"},{"t":"も"},{"t":"続","r":"つづ"},{"t":"いて"},{"t":"います"},{"t":"。"}]'::jsonb, 'Twenty years on, our friendship is still going.'),
  ('rdg-ja-n1-wedding-toast-l7', 'rdg-ja-n1-wedding-toast', 7, 2, '彼は決して器用な男ではありません。', 'かれ わ けっして きよう な おとこ で わ ありません。', '[{"t":"彼","r":"かれ"},{"t":"は"},{"t":"決","r":"けっ"},{"t":"して"},{"t":"器用","r":"きよう"},{"t":"な"},{"t":"男","r":"おとこ"},{"t":"では"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'He is by no means the most deft of men.'),
  ('rdg-ja-n1-wedding-toast-l8', 'rdg-ja-n1-wedding-toast', 8, 2, 'しかし、誰よりも誠実です。', 'しかし、だれ より も せいじつ です。', '[{"t":"しかし"},{"t":"、"},{"t":"誰","r":"だれ"},{"t":"より"},{"t":"も"},{"t":"誠実","r":"せいじつ"},{"t":"です"},{"t":"。"}]'::jsonb, 'But he is more sincere than anyone.'),
  ('rdg-ja-n1-wedding-toast-l9', 'rdg-ja-n1-wedding-toast', 9, 3, '私が仕事を失ったとき、', 'わたし が しごと お うしなった とき、', '[{"t":"私","r":"わたし"},{"t":"が"},{"t":"仕事","r":"しごと"},{"t":"を"},{"t":"失","r":"うしな"},{"t":"った"},{"t":"とき"},{"t":"、"}]'::jsonb, 'When I lost my job,'),
  ('rdg-ja-n1-wedding-toast-l10', 'rdg-ja-n1-wedding-toast', 10, 3, '彼は何も聞かずに、一晩中そばにいてくれました。', 'かれ わ なにも きかず に、ひとばんじゅう そば に いて くれました。', '[{"t":"彼","r":"かれ"},{"t":"は"},{"t":"何","r":"なに"},{"t":"も"},{"t":"聞","r":"き"},{"t":"かずに"},{"t":"、"},{"t":"一晩中","r":"ひとばんじゅう"},{"t":"そば"},{"t":"に"},{"t":"いて"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'he asked nothing and stayed by my side all night.'),
  ('rdg-ja-n1-wedding-toast-l11', 'rdg-ja-n1-wedding-toast', 11, 3, 'あの夜のことは、今も覚えています。', 'あの よる の こと わ、いま も おぼえて います。', '[{"t":"あの"},{"t":"夜","r":"よる"},{"t":"の"},{"t":"こと"},{"t":"は"},{"t":"、"},{"t":"今","r":"いま"},{"t":"も"},{"t":"覚","r":"おぼ"},{"t":"えて"},{"t":"います"},{"t":"。"}]'::jsonb, 'I still remember that night.'),
  ('rdg-ja-n1-wedding-toast-l12', 'rdg-ja-n1-wedding-toast', 12, 4, '新婦の方と初めて会ったとき、', 'しんぷ の かた と はじめて あった とき、', '[{"t":"新婦","r":"しんぷ"},{"t":"の"},{"t":"方","r":"かた"},{"t":"と"},{"t":"初","r":"はじ"},{"t":"めて"},{"t":"会","r":"あ"},{"t":"った"},{"t":"とき"},{"t":"、"}]'::jsonb, 'When I first met the bride,'),
  ('rdg-ja-n1-wedding-toast-l13', 'rdg-ja-n1-wedding-toast', 13, 4, '彼がなぜ変わったのか、一目で分かりました。', 'かれ が なぜ かわった の か、ひとめ で わかりました。', '[{"t":"彼","r":"かれ"},{"t":"が"},{"t":"なぜ"},{"t":"変","r":"か"},{"t":"わった"},{"t":"の"},{"t":"か"},{"t":"、"},{"t":"一目","r":"ひとめ"},{"t":"で"},{"t":"分","r":"わ"},{"t":"かりました"},{"t":"。"}]'::jsonb, 'I understood at a glance why he had changed.'),
  ('rdg-ja-n1-wedding-toast-l14', 'rdg-ja-n1-wedding-toast', 14, 4, '彼女の前では、彼は自然に笑うのです。', 'かのじょ の まえ で わ、かれ わ しぜん に わらう の です。', '[{"t":"彼女","r":"かのじょ"},{"t":"の"},{"t":"前","r":"まえ"},{"t":"では"},{"t":"、"},{"t":"彼","r":"かれ"},{"t":"は"},{"t":"自然","r":"しぜん"},{"t":"に"},{"t":"笑","r":"わら"},{"t":"う"},{"t":"のです"},{"t":"。"}]'::jsonb, 'In front of her, he laughs naturally.'),
  ('rdg-ja-n1-wedding-toast-l15', 'rdg-ja-n1-wedding-toast', 15, 5, '二人は、よく似ているわけではありません。', 'ふたり わ、よく にて いる わけ で わ ありません。', '[{"t":"二人","r":"ふたり"},{"t":"は"},{"t":"、"},{"t":"よく"},{"t":"似","r":"に"},{"t":"て"},{"t":"いる"},{"t":"わけ"},{"t":"では"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'These two are not especially alike.'),
  ('rdg-ja-n1-wedding-toast-l16', 'rdg-ja-n1-wedding-toast', 16, 5, 'むしろ、足りないところを補い合っています。', 'むしろ、たりない ところ お おぎない あって います。', '[{"t":"むしろ"},{"t":"、"},{"t":"足","r":"た"},{"t":"りない"},{"t":"ところを"},{"t":"補","r":"おぎな"},{"t":"い"},{"t":"合","r":"あ"},{"t":"って"},{"t":"います"},{"t":"。"}]'::jsonb, 'Rather, each makes up for what the other lacks.'),
  ('rdg-ja-n1-wedding-toast-l17', 'rdg-ja-n1-wedding-toast', 17, 5, 'それこそが、夫婦の強さだと思います。', 'それこそ が、ふうふ の つよさ だ と おもいます。', '[{"t":"それこそ"},{"t":"が"},{"t":"、"},{"t":"夫婦","r":"ふうふ"},{"t":"の"},{"t":"強","r":"つよ"},{"t":"さ"},{"t":"だ"},{"t":"と"},{"t":"思","r":"おも"},{"t":"います"},{"t":"。"}]'::jsonb, 'That, I think, is the strength of a couple.'),
  ('rdg-ja-n1-wedding-toast-l18', 'rdg-ja-n1-wedding-toast', 18, 6, '結婚は、ゴールではなく出発点です。', 'けっこん わ、ゴール で わ なく しゅっぱつてん です。', '[{"t":"結婚","r":"けっこん"},{"t":"は"},{"t":"、"},{"t":"ゴール"},{"t":"では"},{"t":"なく"},{"t":"出発点","r":"しゅっぱつてん"},{"t":"です"},{"t":"。"}]'::jsonb, 'Marriage is not the finish line but the starting point.'),
  ('rdg-ja-n1-wedding-toast-l19', 'rdg-ja-n1-wedding-toast', 19, 6, '楽しい日ばかりではないでしょう。', 'たのしい ひ ばかり で わ ない でしょう。', '[{"t":"楽","r":"たの"},{"t":"しい"},{"t":"日","r":"ひ"},{"t":"ばかり"},{"t":"では"},{"t":"ない"},{"t":"でしょう"},{"t":"。"}]'::jsonb, 'There will not be only happy days.'),
  ('rdg-ja-n1-wedding-toast-l20', 'rdg-ja-n1-wedding-toast', 20, 6, 'そんな日こそ、今日の気持ちを思い出してください。', 'そんな ひ こそ、きょう の きもち お おもいだして ください。', '[{"t":"そんな"},{"t":"日","r":"ひ"},{"t":"こそ"},{"t":"、"},{"t":"今日","r":"きょう"},{"t":"の"},{"t":"気持","r":"きも"},{"t":"ち"},{"t":"を"},{"t":"思","r":"おも"},{"t":"い"},{"t":"出","r":"だ"},{"t":"して"},{"t":"ください"},{"t":"。"}]'::jsonb, 'On those days above all, remember how you feel today.'),
  ('rdg-ja-n1-wedding-toast-l21', 'rdg-ja-n1-wedding-toast', 21, 7, 'どうかお二人とも、お幸せに。', 'どうか おふたり とも、おしあわせ に。', '[{"t":"どうか"},{"t":"お"},{"t":"二人","r":"ふたり"},{"t":"とも"},{"t":"、"},{"t":"お"},{"t":"幸","r":"しあわ"},{"t":"せ"},{"t":"に"},{"t":"。"}]'::jsonb, 'May you both be happy.'),
  ('rdg-ja-n1-wedding-toast-l22', 'rdg-ja-n1-wedding-toast', 22, 7, 'お二人の門出を、心よりお祝い申し上げます。', 'おふたり の かどで お、こころ より おいわい もうしあげます。', '[{"t":"お"},{"t":"二人","r":"ふたり"},{"t":"の"},{"t":"門出","r":"かどで"},{"t":"を"},{"t":"、"},{"t":"心","r":"こころ"},{"t":"より"},{"t":"お"},{"t":"祝","r":"いわ"},{"t":"い"},{"t":"申","r":"もう"},{"t":"し"},{"t":"上","r":"あ"},{"t":"げます"},{"t":"。"}]'::jsonb, 'I offer my heartfelt congratulations on your new beginning.'),
  ('rdg-ja-n1-wedding-toast-l23', 'rdg-ja-n1-wedding-toast', 23, 7, 'ありがとうございました。', 'ありがとう ございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n1-wedding-toast')
ON CONFLICT (reading_id, index) DO NOTHING;

INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, origin, priority, status)
SELECT 'crq-rdg-ja-n1-wedding-toast', 'lang-ja', 'readings', 'rdg-ja-n1-wedding-toast', 'create', '{"code":"n1-wedding-toast","level":"N1"}'::jsonb, 'ai', 5, 'pending'
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n1-wedding-toast' AND NOT published)
  AND NOT EXISTS (SELECT 1 FROM content_review_queue WHERE target_table = 'readings' AND target_id = 'rdg-ja-n1-wedding-toast')
ON CONFLICT DO NOTHING;

-- N1 · n1-technology-loneliness · Technology and loneliness
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n1-technology-loneliness', 'lang-ja', ll.id, 'n1-technology-loneliness', '技術と孤独', 'Technology and loneliness', false, 21
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N1'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n1-technology-loneliness-l0', 'rdg-ja-n1-technology-loneliness', 0, 0, '最後に、誰かと目を見て話したのはいつですか。', 'さいご に、だれか と め お みて はなした の わ いつ です か。', '[{"t":"最後","r":"さいご"},{"t":"に"},{"t":"、"},{"t":"誰","r":"だれ"},{"t":"か"},{"t":"と"},{"t":"目","r":"め"},{"t":"を"},{"t":"見","r":"み"},{"t":"て"},{"t":"話","r":"はな"},{"t":"した"},{"t":"の"},{"t":"は"},{"t":"いつ"},{"t":"です"},{"t":"か"},{"t":"。"}]'::jsonb, 'When was the last time you talked to someone face to face?'),
  ('rdg-ja-n1-technology-loneliness-l1', 'rdg-ja-n1-technology-loneliness', 1, 0, '画面の中ではなく、目の前で。', 'がめん の なか で わ なく、め の まえ で。', '[{"t":"画面","r":"がめん"},{"t":"の"},{"t":"中","r":"なか"},{"t":"では"},{"t":"なく"},{"t":"、"},{"t":"目","r":"め"},{"t":"の"},{"t":"前","r":"まえ"},{"t":"で"},{"t":"。"}]'::jsonb, 'Not inside a screen, but right in front of you.'),
  ('rdg-ja-n1-technology-loneliness-l2', 'rdg-ja-n1-technology-loneliness', 2, 1, '今の時代、人はかつてないほど繋がっています。', 'いま の じだい、ひと わ かつて ない ほど つながって います。', '[{"t":"今","r":"いま"},{"t":"の"},{"t":"時代","r":"じだい"},{"t":"、"},{"t":"人","r":"ひと"},{"t":"は"},{"t":"かつて"},{"t":"ない"},{"t":"ほど"},{"t":"繋","r":"つな"},{"t":"がって"},{"t":"います"},{"t":"。"}]'::jsonb, 'In this age, people are more connected than ever.'),
  ('rdg-ja-n1-technology-loneliness-l3', 'rdg-ja-n1-technology-loneliness', 3, 1, '遠い国に住む人とも、一瞬で話せます。', 'とおい くに に すむ ひと と も、いっしゅん で はなせます。', '[{"t":"遠","r":"とお"},{"t":"い"},{"t":"国","r":"くに"},{"t":"に"},{"t":"住","r":"す"},{"t":"む"},{"t":"人","r":"ひと"},{"t":"とも"},{"t":"、"},{"t":"一瞬","r":"いっしゅん"},{"t":"で"},{"t":"話","r":"はな"},{"t":"せます"},{"t":"。"}]'::jsonb, 'We can talk in an instant even with people who live in faraway countries.'),
  ('rdg-ja-n1-technology-loneliness-l4', 'rdg-ja-n1-technology-loneliness', 4, 1, 'それなのに、なぜ孤独は減らないのですか。', 'それなのに、なぜ こどく わ へらない の です か。', '[{"t":"それなのに"},{"t":"、"},{"t":"なぜ"},{"t":"孤独","r":"こどく"},{"t":"は"},{"t":"減","r":"へ"},{"t":"らない"},{"t":"のです"},{"t":"か"},{"t":"。"}]'::jsonb, 'So why, then, does loneliness not go away?'),
  ('rdg-ja-n1-technology-loneliness-l5', 'rdg-ja-n1-technology-loneliness', 5, 2, '私は、繋がりと絆は別物だと考えています。', 'わたし わ、つながり と きずな わ べつもの だ と かんがえて います。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"繋","r":"つな"},{"t":"がり"},{"t":"と"},{"t":"絆","r":"きずな"},{"t":"は"},{"t":"別物","r":"べつもの"},{"t":"だ"},{"t":"と"},{"t":"考","r":"かんが"},{"t":"えて"},{"t":"います"},{"t":"。"}]'::jsonb, 'I believe that being connected and having bonds are different things.'),
  ('rdg-ja-n1-technology-loneliness-l6', 'rdg-ja-n1-technology-loneliness', 6, 2, '画面に並ぶ名前の数は、', 'がめん に ならぶ なまえ の かず わ、', '[{"t":"画面","r":"がめん"},{"t":"に"},{"t":"並","r":"なら"},{"t":"ぶ"},{"t":"名前","r":"なまえ"},{"t":"の"},{"t":"数","r":"かず"},{"t":"は"},{"t":"、"}]'::jsonb, 'The number of names lined up on a screen'),
  ('rdg-ja-n1-technology-loneliness-l7', 'rdg-ja-n1-technology-loneliness', 7, 2, '心の支えの数とは関係がありません。', 'こころ の ささえ の かず と わ かんけい が ありません。', '[{"t":"心","r":"こころ"},{"t":"の"},{"t":"支","r":"ささ"},{"t":"えの"},{"t":"数","r":"かず"},{"t":"とは"},{"t":"関係","r":"かんけい"},{"t":"が"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'has no relation to the number of people who support your heart.'),
  ('rdg-ja-n1-technology-loneliness-l8', 'rdg-ja-n1-technology-loneliness', 8, 3, '便利さは、我々の手間を省いてくれます。', 'べんりさ わ、われわれ の てま お はぶいて くれます。', '[{"t":"便利","r":"べんり"},{"t":"さ"},{"t":"は"},{"t":"、"},{"t":"我々","r":"われわれ"},{"t":"の"},{"t":"手間","r":"てま"},{"t":"を"},{"t":"省","r":"はぶ"},{"t":"いて"},{"t":"くれます"},{"t":"。"}]'::jsonb, 'Convenience saves us effort.'),
  ('rdg-ja-n1-technology-loneliness-l9', 'rdg-ja-n1-technology-loneliness', 9, 3, '店員と話さなくても、買い物ができます。', 'てんいん と はなさ なくて も、かいもの が できます。', '[{"t":"店員","r":"てんいん"},{"t":"と"},{"t":"話","r":"はな"},{"t":"さ"},{"t":"なくて"},{"t":"も"},{"t":"、"},{"t":"買","r":"か"},{"t":"い"},{"t":"物","r":"もの"},{"t":"が"},{"t":"できます"},{"t":"。"}]'::jsonb, 'We can shop without speaking to a clerk.'),
  ('rdg-ja-n1-technology-loneliness-l10', 'rdg-ja-n1-technology-loneliness', 10, 3, 'しかし、あの手間こそが、', 'しかし、あの てま こそ が、', '[{"t":"しかし"},{"t":"、"},{"t":"あの"},{"t":"手間","r":"てま"},{"t":"こそ"},{"t":"が"},{"t":"、"}]'::jsonb, 'But that very effort'),
  ('rdg-ja-n1-technology-loneliness-l11', 'rdg-ja-n1-technology-loneliness', 11, 3, '人と人との出会いの場でもあったのです。', 'ひと と ひと と の であい の ば で も あった の です。', '[{"t":"人","r":"ひと"},{"t":"と"},{"t":"人","r":"ひと"},{"t":"と"},{"t":"の"},{"t":"出会","r":"であ"},{"t":"い"},{"t":"の"},{"t":"場","r":"ば"},{"t":"でも"},{"t":"あった"},{"t":"のです"},{"t":"。"}]'::jsonb, 'was also a place where people met.'),
  ('rdg-ja-n1-technology-loneliness-l12', 'rdg-ja-n1-technology-loneliness', 12, 4, '言うまでもなく、技術を否定するつもりはありません。', 'いう まで も なく、ぎじゅつ お ひてい する つもり わ ありません。', '[{"t":"言","r":"い"},{"t":"う"},{"t":"まで"},{"t":"も"},{"t":"なく"},{"t":"、"},{"t":"技術","r":"ぎじゅつ"},{"t":"を"},{"t":"否定","r":"ひてい"},{"t":"する"},{"t":"つもり"},{"t":"は"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'Needless to say, I have no intention of rejecting technology.'),
  ('rdg-ja-n1-technology-loneliness-l13', 'rdg-ja-n1-technology-loneliness', 13, 4, '遠くに住む家族の顔を見られるのは、', 'とおく に すむ かぞく の かお お みられる の わ、', '[{"t":"遠","r":"とお"},{"t":"く"},{"t":"に"},{"t":"住","r":"す"},{"t":"む"},{"t":"家族","r":"かぞく"},{"t":"の"},{"t":"顔","r":"かお"},{"t":"を"},{"t":"見","r":"み"},{"t":"られる"},{"t":"の"},{"t":"は"},{"t":"、"}]'::jsonb, 'Being able to see the faces of family living far away'),
  ('rdg-ja-n1-technology-loneliness-l14', 'rdg-ja-n1-technology-loneliness', 14, 4, '本当にありがたいことです。', 'ほんとう に ありがたい こと です。', '[{"t":"本当","r":"ほんとう"},{"t":"に"},{"t":"ありがたい"},{"t":"こと"},{"t":"です"},{"t":"。"}]'::jsonb, 'is truly something to be grateful for.'),
  ('rdg-ja-n1-technology-loneliness-l15', 'rdg-ja-n1-technology-loneliness', 15, 5, '問題は、技術ではなく、', 'もんだい わ、ぎじゅつ で わ なく、', '[{"t":"問題","r":"もんだい"},{"t":"は"},{"t":"、"},{"t":"技術","r":"ぎじゅつ"},{"t":"では"},{"t":"なく"},{"t":"、"}]'::jsonb, 'The problem is not technology,'),
  ('rdg-ja-n1-technology-loneliness-l16', 'rdg-ja-n1-technology-loneliness', 16, 5, 'それに頼りすぎる我々の習慣にあります。', 'それ に たよりすぎる われわれ の しゅうかん に あります。', '[{"t":"それ"},{"t":"に"},{"t":"頼","r":"たよ"},{"t":"りすぎる"},{"t":"我々","r":"われわれ"},{"t":"の"},{"t":"習慣","r":"しゅうかん"},{"t":"に"},{"t":"あります"},{"t":"。"}]'::jsonb, 'but in our habit of leaning on it too much.'),
  ('rdg-ja-n1-technology-loneliness-l17', 'rdg-ja-n1-technology-loneliness', 17, 5, '返事の速さで、愛情を測っていませんか。', 'へんじ の はやさ で、あいじょう お はかって いません か。', '[{"t":"返事","r":"へんじ"},{"t":"の"},{"t":"速","r":"はや"},{"t":"さで"},{"t":"、"},{"t":"愛情","r":"あいじょう"},{"t":"を"},{"t":"測","r":"はか"},{"t":"っていませんか"},{"t":"。"}]'::jsonb, 'Are you not measuring affection by how fast someone replies?'),
  ('rdg-ja-n1-technology-loneliness-l18', 'rdg-ja-n1-technology-loneliness', 18, 6, '孤独を感じたら、電話を置いて、外に出てみましょう。', 'こどく お かんじたら、でんわ お おいて、そと に でて みましょう。', '[{"t":"孤独","r":"こどく"},{"t":"を"},{"t":"感","r":"かん"},{"t":"じたら"},{"t":"、"},{"t":"電話","r":"でんわ"},{"t":"を"},{"t":"置","r":"お"},{"t":"いて"},{"t":"、"},{"t":"外","r":"そと"},{"t":"に"},{"t":"出","r":"で"},{"t":"て"},{"t":"みましょう"},{"t":"。"}]'::jsonb, 'When you feel lonely, put the phone down and step outside.'),
  ('rdg-ja-n1-technology-loneliness-l19', 'rdg-ja-n1-technology-loneliness', 19, 6, 'そして、近所の誰かに声をかけてください。', 'そして、きんじょ の だれか に こえ お かけて ください。', '[{"t":"そして"},{"t":"、"},{"t":"近所","r":"きんじょ"},{"t":"の"},{"t":"誰","r":"だれ"},{"t":"か"},{"t":"に"},{"t":"声","r":"こえ"},{"t":"を"},{"t":"かけて"},{"t":"ください"},{"t":"。"}]'::jsonb, 'Then say hello to someone in your neighbourhood.'),
  ('rdg-ja-n1-technology-loneliness-l20', 'rdg-ja-n1-technology-loneliness', 20, 6, '小さな行動が、孤独を和らげるはずです。', 'ちいさな こうどう が、こどく お やわらげる はず です。', '[{"t":"小","r":"ちい"},{"t":"さな"},{"t":"行動","r":"こうどう"},{"t":"が"},{"t":"、"},{"t":"孤独","r":"こどく"},{"t":"を"},{"t":"和","r":"やわ"},{"t":"らげる"},{"t":"はず"},{"t":"です"},{"t":"。"}]'::jsonb, 'Small actions should ease the loneliness.'),
  ('rdg-ja-n1-technology-loneliness-l21', 'rdg-ja-n1-technology-loneliness', 21, 7, '技術は、人を繋ぐための道具です。', 'ぎじゅつ わ、ひと お つなぐ ため の どうぐ です。', '[{"t":"技術","r":"ぎじゅつ"},{"t":"は"},{"t":"、"},{"t":"人","r":"ひと"},{"t":"を"},{"t":"繋","r":"つな"},{"t":"ぐ"},{"t":"ため"},{"t":"の"},{"t":"道具","r":"どうぐ"},{"t":"です"},{"t":"。"}]'::jsonb, 'Technology is a tool for linking people.'),
  ('rdg-ja-n1-technology-loneliness-l22', 'rdg-ja-n1-technology-loneliness', 22, 7, '手を差し出すのは、いつの時代も人間です。', 'て お さしだす の わ、いつ の じだい も にんげん です。', '[{"t":"手","r":"て"},{"t":"を"},{"t":"差","r":"さ"},{"t":"し"},{"t":"出","r":"だ"},{"t":"す"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"いつ"},{"t":"の"},{"t":"時代","r":"じだい"},{"t":"も"},{"t":"人間","r":"にんげん"},{"t":"です"},{"t":"。"}]'::jsonb, 'In every age, it is people who reach out a hand.'),
  ('rdg-ja-n1-technology-loneliness-l23', 'rdg-ja-n1-technology-loneliness', 23, 7, '聞いてくれて、ありがとうございました。', 'きいて くれて、ありがとう ございました。', '[{"t":"聞","r":"き"},{"t":"いて"},{"t":"くれて"},{"t":"、"},{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you for listening.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n1-technology-loneliness')
ON CONFLICT (reading_id, index) DO NOTHING;

