ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n1-value-of-failure-l0', 'rdg-ja-n1-value-of-failure', 0, 0, '三十歳のとき、私は会社を立ち上げました。', 'さんじっさい の とき、わたし わ かいしゃ お たちあげました。', '[{"t":"三十歳","r":"さんじっさい"},{"t":"の"},{"t":"とき"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"会社","r":"かいしゃ"},{"t":"を"},{"t":"立","r":"た"},{"t":"ち"},{"t":"上","r":"あ"},{"t":"げました"},{"t":"。"}]'::jsonb, 'At thirty, I started a company.'),
  ('rdg-ja-n1-value-of-failure-l1', 'rdg-ja-n1-value-of-failure', 1, 0, 'そして二年後、あの会社を潰してしまいました。', 'そして にねんご、あの かいしゃ お つぶして しまいました。', '[{"t":"そして"},{"t":"二年後","r":"にねんご"},{"t":"、"},{"t":"あの"},{"t":"会社","r":"かいしゃ"},{"t":"を"},{"t":"潰","r":"つぶ"},{"t":"して"},{"t":"しまいました"},{"t":"。"}]'::jsonb, 'Two years later, I ran it into the ground.'),
  ('rdg-ja-n1-value-of-failure-l2', 'rdg-ja-n1-value-of-failure', 2, 0, '貯金も、気力も、すべて失いました。', 'ちょきん も、きりょく も、すべて うしないました。', '[{"t":"貯金","r":"ちょきん"},{"t":"も"},{"t":"、"},{"t":"気力","r":"きりょく"},{"t":"も"},{"t":"、"},{"t":"すべて"},{"t":"失","r":"うしな"},{"t":"いました"},{"t":"。"}]'::jsonb, 'I lost my savings and my energy, everything.'),
  ('rdg-ja-n1-value-of-failure-l3', 'rdg-ja-n1-value-of-failure', 3, 1, '当時の私は、失敗を恥だと思っていました。', 'とうじ の わたし わ、しっぱい お はじ だ と おもって いました。', '[{"t":"当時","r":"とうじ"},{"t":"の"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"失敗","r":"しっぱい"},{"t":"を"},{"t":"恥","r":"はじ"},{"t":"だ"},{"t":"と"},{"t":"思","r":"おも"},{"t":"って"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Back then I thought failure was a disgrace.'),
  ('rdg-ja-n1-value-of-failure-l4', 'rdg-ja-n1-value-of-failure', 4, 1, '友人に会うのも避けていたほどです。', 'ゆうじん に あう の も さけて いた ほど です。', '[{"t":"友人","r":"ゆうじん"},{"t":"に"},{"t":"会","r":"あ"},{"t":"う"},{"t":"の"},{"t":"も"},{"t":"避","r":"さ"},{"t":"けて"},{"t":"いた"},{"t":"ほど"},{"t":"です"},{"t":"。"}]'::jsonb, 'I even avoided meeting friends.'),
  ('rdg-ja-n1-value-of-failure-l5', 'rdg-ja-n1-value-of-failure', 5, 1, '部屋に閉じこもって、何週間も過ごしました。', 'へや に とじこもって、なんしゅうかん も すごしました。', '[{"t":"部屋","r":"へや"},{"t":"に"},{"t":"閉","r":"と"},{"t":"じこもって"},{"t":"、"},{"t":"何週間","r":"なんしゅうかん"},{"t":"も"},{"t":"過","r":"す"},{"t":"ごしました"},{"t":"。"}]'::jsonb, 'I shut myself in my room and spent weeks that way.'),
  ('rdg-ja-n1-value-of-failure-l6', 'rdg-ja-n1-value-of-failure', 6, 2, 'ところが、ある日ふと気づいたのです。', 'ところが、ある ひ ふと きづいた の です。', '[{"t":"ところが"},{"t":"、"},{"t":"ある"},{"t":"日","r":"ひ"},{"t":"ふと"},{"t":"気","r":"き"},{"t":"づいた"},{"t":"のです"},{"t":"。"}]'::jsonb, 'Then one day I suddenly realised something.'),
  ('rdg-ja-n1-value-of-failure-l7', 'rdg-ja-n1-value-of-failure', 7, 2, '私は、あの二年間で、', 'わたし わ、あの にねんかん で、', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"あの"},{"t":"二年間","r":"にねんかん"},{"t":"で"},{"t":"、"}]'::jsonb, 'that in those two years,'),
  ('rdg-ja-n1-value-of-failure-l8', 'rdg-ja-n1-value-of-failure', 8, 2, '十年分のことを学んでいたことに。', 'じゅうねんぶん の こと お まなんで いた こと に。', '[{"t":"十年分","r":"じゅうねんぶん"},{"t":"の"},{"t":"こと"},{"t":"を"},{"t":"学","r":"まな"},{"t":"んで"},{"t":"いた"},{"t":"こと"},{"t":"に"},{"t":"。"}]'::jsonb, 'I had learned ten years'' worth of lessons.'),
  ('rdg-ja-n1-value-of-failure-l9', 'rdg-ja-n1-value-of-failure', 9, 3, '成功は、人を喜ばせてくれます。', 'せいこう わ、ひと お よろこばせて くれます。', '[{"t":"成功","r":"せいこう"},{"t":"は"},{"t":"、"},{"t":"人","r":"ひと"},{"t":"を"},{"t":"喜","r":"よろこ"},{"t":"ばせてくれます"},{"t":"。"}]'::jsonb, 'Success makes people happy.'),
  ('rdg-ja-n1-value-of-failure-l10', 'rdg-ja-n1-value-of-failure', 10, 3, 'しかし、教えてくれることは少ないのです。', 'しかし、おしえて くれる こと わ すくない の です。', '[{"t":"しかし"},{"t":"、"},{"t":"教","r":"おし"},{"t":"えて"},{"t":"くれる"},{"t":"こと"},{"t":"は"},{"t":"少","r":"すく"},{"t":"ない"},{"t":"のです"},{"t":"。"}]'::jsonb, 'But it teaches us little.'),
  ('rdg-ja-n1-value-of-failure-l11', 'rdg-ja-n1-value-of-failure', 11, 3, '失敗は痛みを伴いますが、', 'しっぱい わ いたみ お ともないます が、', '[{"t":"失敗","r":"しっぱい"},{"t":"は"},{"t":"痛","r":"いた"},{"t":"み"},{"t":"を"},{"t":"伴","r":"ともな"},{"t":"います"},{"t":"が"},{"t":"、"}]'::jsonb, 'Failure comes with pain,'),
  ('rdg-ja-n1-value-of-failure-l12', 'rdg-ja-n1-value-of-failure', 12, 3, '理由まで丁寧に教えてくれます。', 'りゆう まで ていねい に おしえて くれます。', '[{"t":"理由","r":"りゆう"},{"t":"まで"},{"t":"丁寧","r":"ていねい"},{"t":"に"},{"t":"教","r":"おし"},{"t":"えて"},{"t":"くれます"},{"t":"。"}]'::jsonb, 'but it also explains the reasons carefully.'),
  ('rdg-ja-n1-value-of-failure-l13', 'rdg-ja-n1-value-of-failure', 13, 4, '大切なのは、同じ失敗を繰り返さないことです。', 'たいせつ な の わ、おなじ しっぱい お くりかえさ ない こと です。', '[{"t":"大切","r":"たいせつ"},{"t":"な"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"同","r":"おな"},{"t":"じ"},{"t":"失敗","r":"しっぱい"},{"t":"を"},{"t":"繰","r":"く"},{"t":"り"},{"t":"返","r":"かえ"},{"t":"さない"},{"t":"こと"},{"t":"です"},{"t":"。"}]'::jsonb, 'What matters is not repeating the same failure.'),
  ('rdg-ja-n1-value-of-failure-l14', 'rdg-ja-n1-value-of-failure', 14, 4, '転んだ場所を覚えていれば、', 'ころんだ ばしょ お おぼえて いれば、', '[{"t":"転","r":"ころ"},{"t":"んだ"},{"t":"場所","r":"ばしょ"},{"t":"を"},{"t":"覚","r":"おぼ"},{"t":"えて"},{"t":"いれば"},{"t":"、"}]'::jsonb, 'If you remember the place where you fell,'),
  ('rdg-ja-n1-value-of-failure-l15', 'rdg-ja-n1-value-of-failure', 15, 4, '次は避けて通ることができます。', 'つぎ わ さけて とおる こと が できます。', '[{"t":"次","r":"つぎ"},{"t":"は"},{"t":"避","r":"さ"},{"t":"けて"},{"t":"通","r":"とお"},{"t":"る"},{"t":"ことができます"},{"t":"。"}]'::jsonb, 'next time you can step around it.'),
  ('rdg-ja-n1-value-of-failure-l16', 'rdg-ja-n1-value-of-failure', 16, 5, '今、私は二つ目の会社を経営しています。', 'いま、わたし わ ふたつめ の かいしゃ お けいえい して います。', '[{"t":"今","r":"いま"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"二","r":"ふた"},{"t":"つ"},{"t":"目","r":"め"},{"t":"の"},{"t":"会社","r":"かいしゃ"},{"t":"を"},{"t":"経営","r":"けいえい"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'Now I run my second company.'),
  ('rdg-ja-n1-value-of-failure-l17', 'rdg-ja-n1-value-of-failure', 17, 5, '最初の会社があったからこそ、今の私がいます。', 'さいしょ の かいしゃ が あった から こそ、いま の わたし が います。', '[{"t":"最初","r":"さいしょ"},{"t":"の"},{"t":"会社","r":"かいしゃ"},{"t":"が"},{"t":"あった"},{"t":"から"},{"t":"こそ"},{"t":"、"},{"t":"今","r":"いま"},{"t":"の"},{"t":"私","r":"わたし"},{"t":"が"},{"t":"います"},{"t":"。"}]'::jsonb, 'It is because of that first company that I am who I am.'),
  ('rdg-ja-n1-value-of-failure-l18', 'rdg-ja-n1-value-of-failure', 18, 5, 'ですから、あの失敗に感謝しています。', 'ですから、あの しっぱい に かんしゃ して います。', '[{"t":"ですから"},{"t":"、"},{"t":"あの"},{"t":"失敗","r":"しっぱい"},{"t":"に"},{"t":"感謝","r":"かんしゃ"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'So I am grateful for that failure.'),
  ('rdg-ja-n1-value-of-failure-l19', 'rdg-ja-n1-value-of-failure', 19, 6, 'どうか、失敗を恐れないでください。', 'どうか、しっぱい お おそれない で ください。', '[{"t":"どうか"},{"t":"、"},{"t":"失敗","r":"しっぱい"},{"t":"を"},{"t":"恐","r":"おそ"},{"t":"れない"},{"t":"で"},{"t":"ください"},{"t":"。"}]'::jsonb, 'Please do not be afraid of failure.'),
  ('rdg-ja-n1-value-of-failure-l20', 'rdg-ja-n1-value-of-failure', 20, 6, '挑戦しないことのほうが、よほど高くつきます。', 'ちょうせん しない こと の ほう が、よほど たかく つきます。', '[{"t":"挑戦","r":"ちょうせん"},{"t":"しない"},{"t":"こと"},{"t":"の"},{"t":"ほうが"},{"t":"、"},{"t":"よほど"},{"t":"高","r":"たか"},{"t":"くつきます"},{"t":"。"}]'::jsonb, 'Not trying costs far more in the end.'),
  ('rdg-ja-n1-value-of-failure-l21', 'rdg-ja-n1-value-of-failure', 21, 6, 'ありがとうございました。', 'ありがとう ございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n1-value-of-failure')
ON CONFLICT (reading_id, index) DO NOTHING;

