SELECT 'crq-rdg-ja-n1-value-of-failure', 'lang-ja', 'readings', 'rdg-ja-n1-value-of-failure', 'create', '{"code":"n1-value-of-failure","level":"N1"}'::jsonb, 'ai', 5, 'pending'
