-- N1 · n1-language-identity · Language and identity
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n1-language-identity', 'lang-ja', ll.id, 'n1-language-identity', '言葉とアイデンティティ', 'Language and identity', false, 23
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N1'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n1-language-identity-l0', 'rdg-ja-n1-language-identity', 0, 0, '私は、二つの言葉で生きています。', 'わたし わ、ふたつ の ことば で いきて います。', '[{"t":"私","r":"わたし"},{"t":"は"},{"t":"、"},{"t":"二","r":"ふた"},{"t":"つ"},{"t":"の"},{"t":"言葉","r":"ことば"},{"t":"で"},{"t":"生","r":"い"},{"t":"きて"},{"t":"います"},{"t":"。"}]'::jsonb, 'I live in two languages.'),
  ('rdg-ja-n1-language-identity-l1', 'rdg-ja-n1-language-identity', 1, 0, 'どちらも、私にとって大切な言葉です。', 'どちら も、わたし に とって たいせつな ことば です。', '[{"t":"どちら"},{"t":"も"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"にとって"},{"t":"大切","r":"たいせつ"},{"t":"な"},{"t":"言葉","r":"ことば"},{"t":"です"},{"t":"。"}]'::jsonb, 'Both are precious languages to me.'),
  ('rdg-ja-n1-language-identity-l2', 'rdg-ja-n1-language-identity', 2, 1, '家では母の言葉を、', 'いえ で わ はは の ことば お、', '[{"t":"家","r":"いえ"},{"t":"では"},{"t":"母","r":"はは"},{"t":"の"},{"t":"言葉","r":"ことば"},{"t":"を"},{"t":"、"}]'::jsonb, 'At home I spoke my mother''s language,'),
  ('rdg-ja-n1-language-identity-l3', 'rdg-ja-n1-language-identity', 3, 1, '学校では周りの言葉を話しました。', 'がっこう で わ まわり の ことば お はなしました。', '[{"t":"学校","r":"がっこう"},{"t":"では"},{"t":"周","r":"まわ"},{"t":"り"},{"t":"の"},{"t":"言葉","r":"ことば"},{"t":"を"},{"t":"話","r":"はな"},{"t":"しました"},{"t":"。"}]'::jsonb, 'and at school, the language around me.'),
  ('rdg-ja-n1-language-identity-l4', 'rdg-ja-n1-language-identity', 4, 1, '二つの言葉は、いつも私の中で話し合っていました。', 'ふたつ の ことば わ、いつも わたし の なか で はなしあって いました。', '[{"t":"二","r":"ふた"},{"t":"つ"},{"t":"の"},{"t":"言葉","r":"ことば"},{"t":"は"},{"t":"、"},{"t":"いつも"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"中","r":"なか"},{"t":"で"},{"t":"話","r":"はな"},{"t":"し"},{"t":"合","r":"あ"},{"t":"って"},{"t":"いました"},{"t":"。"}]'::jsonb, 'The two languages were always talking inside me.'),
  ('rdg-ja-n1-language-identity-l5', 'rdg-ja-n1-language-identity', 5, 1, 'どちらが本当の自分なのか、よく悩みました。', 'どちら が ほんとう の じぶん な の か、よく なやみました。', '[{"t":"どちら"},{"t":"が"},{"t":"本当","r":"ほんとう"},{"t":"の"},{"t":"自分","r":"じぶん"},{"t":"な"},{"t":"の"},{"t":"か"},{"t":"、"},{"t":"よく"},{"t":"悩","r":"なや"},{"t":"みました"},{"t":"。"}]'::jsonb, 'I often wondered which one was the real me.'),
  ('rdg-ja-n1-language-identity-l6', 'rdg-ja-n1-language-identity', 6, 2, '不思議なことに、言語を変えると、', 'ふしぎ な こと に、げんご お かえる と、', '[{"t":"不思議","r":"ふしぎ"},{"t":"な"},{"t":"こと"},{"t":"に"},{"t":"、"},{"t":"言語","r":"げんご"},{"t":"を"},{"t":"変","r":"か"},{"t":"える"},{"t":"と"},{"t":"、"}]'::jsonb, 'Curiously, when I change language,'),
  ('rdg-ja-n1-language-identity-l7', 'rdg-ja-n1-language-identity', 7, 2, '声の高さまで変わるのです。', 'こえ の たかさ まで かわる の です。', '[{"t":"声","r":"こえ"},{"t":"の"},{"t":"高","r":"たか"},{"t":"さまで"},{"t":"変","r":"か"},{"t":"わる"},{"t":"のです"},{"t":"。"}]'::jsonb, 'even the pitch of my voice changes.'),
  ('rdg-ja-n1-language-identity-l8', 'rdg-ja-n1-language-identity', 8, 2, '冗談を言う間も、怒り方も違います。', 'じょうだん お いう ま も、おこりかた も ちがいます。', '[{"t":"冗談","r":"じょうだん"},{"t":"を"},{"t":"言","r":"い"},{"t":"う"},{"t":"間","r":"ま"},{"t":"も"},{"t":"、"},{"t":"怒","r":"おこ"},{"t":"り"},{"t":"方","r":"かた"},{"t":"も"},{"t":"違","r":"ちが"},{"t":"います"},{"t":"。"}]'::jsonb, 'My sense of timing in jokes and my way of getting angry differ too.'),
  ('rdg-ja-n1-language-identity-l9', 'rdg-ja-n1-language-identity', 9, 3, '言葉は、ただの伝達の手段ではありません。', 'ことば わ、ただ の でんたつ の しゅだん で わ ありません。', '[{"t":"言葉","r":"ことば"},{"t":"は"},{"t":"、"},{"t":"ただ"},{"t":"の"},{"t":"伝達","r":"でんたつ"},{"t":"の"},{"t":"手段","r":"しゅだん"},{"t":"では"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'Language is not merely a means of communication.'),
  ('rdg-ja-n1-language-identity-l10', 'rdg-ja-n1-language-identity', 10, 3, '物の見方を、作っているのです。', 'もの の みかた お、つくって いる の です。', '[{"t":"物","r":"もの"},{"t":"の"},{"t":"見方","r":"みかた"},{"t":"を"},{"t":"、"},{"t":"作","r":"つく"},{"t":"って"},{"t":"いる"},{"t":"のです"},{"t":"。"}]'::jsonb, 'It shapes the way we see things.'),
  ('rdg-ja-n1-language-identity-l11', 'rdg-ja-n1-language-identity', 11, 3, 'ある言語にしかない言葉が、', 'ある げんご に しか ない ことば が、', '[{"t":"ある"},{"t":"言語","r":"げんご"},{"t":"に"},{"t":"しか"},{"t":"ない"},{"t":"言葉","r":"ことば"},{"t":"が"},{"t":"、"}]'::jsonb, 'A word that exists in only one language'),
  ('rdg-ja-n1-language-identity-l12', 'rdg-ja-n1-language-identity', 12, 3, 'ある感情に名前を与えてくれることもあります。', 'ある かんじょう に なまえ お あたえて くれる こと も あります。', '[{"t":"ある"},{"t":"感情","r":"かんじょう"},{"t":"に"},{"t":"名前","r":"なまえ"},{"t":"を"},{"t":"与","r":"あた"},{"t":"えて"},{"t":"くれる"},{"t":"こと"},{"t":"も"},{"t":"あります"},{"t":"。"}]'::jsonb, 'can sometimes give a name to a certain feeling.'),
  ('rdg-ja-n1-language-identity-l13', 'rdg-ja-n1-language-identity', 13, 4, '昔、私は自分の発音を隠そうと必死でした。', 'むかし、わたし わ じぶん の はつおん お かくそう と ひっし でした。', '[{"t":"昔","r":"むかし"},{"t":"、"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"自分","r":"じぶん"},{"t":"の"},{"t":"発音","r":"はつおん"},{"t":"を"},{"t":"隠","r":"かく"},{"t":"そう"},{"t":"と"},{"t":"必死","r":"ひっし"},{"t":"でした"},{"t":"。"}]'::jsonb, 'In the past I was desperate to hide my own pronunciation.'),
  ('rdg-ja-n1-language-identity-l14', 'rdg-ja-n1-language-identity', 14, 4, '笑われることが怖かったからです。', 'わらわれる こと が こわかった から です。', '[{"t":"笑","r":"わら"},{"t":"われる"},{"t":"こと"},{"t":"が"},{"t":"怖","r":"こわ"},{"t":"かったからです"},{"t":"。"}]'::jsonb, 'I was afraid of being laughed at.'),
  ('rdg-ja-n1-language-identity-l15', 'rdg-ja-n1-language-identity', 15, 4, 'でも今は、それも私の歴史だと思えます。', 'でも いま わ、それ も わたし の れきし だ と おもえます。', '[{"t":"でも"},{"t":"今","r":"いま"},{"t":"は"},{"t":"、"},{"t":"それ"},{"t":"も"},{"t":"私","r":"わたし"},{"t":"の"},{"t":"歴史","r":"れきし"},{"t":"だ"},{"t":"と"},{"t":"思","r":"おも"},{"t":"えます"},{"t":"。"}]'::jsonb, 'But now I can see it as part of my own history.'),
  ('rdg-ja-n1-language-identity-l16', 'rdg-ja-n1-language-identity', 16, 5, '自分という存在は、一つに絞るものではなく、', 'じぶん と いう そんざい わ、ひとつ に しぼる もの で わ なく、', '[{"t":"自分","r":"じぶん"},{"t":"という"},{"t":"存在","r":"そんざい"},{"t":"は"},{"t":"、"},{"t":"一","r":"ひと"},{"t":"つ"},{"t":"に"},{"t":"絞","r":"しぼ"},{"t":"る"},{"t":"もの"},{"t":"では"},{"t":"なく"},{"t":"、"}]'::jsonb, 'Who you are is not something to narrow down to one,'),
  ('rdg-ja-n1-language-identity-l17', 'rdg-ja-n1-language-identity', 17, 5, '重ねていくものなのかもしれません。', 'かさねて いく もの な の か も しれません。', '[{"t":"重","r":"かさ"},{"t":"ねて"},{"t":"いく"},{"t":"もの"},{"t":"な"},{"t":"の"},{"t":"か"},{"t":"も"},{"t":"しれません"},{"t":"。"}]'::jsonb, 'it may be something you layer up.'),
  ('rdg-ja-n1-language-identity-l18', 'rdg-ja-n1-language-identity', 18, 5, '新しい言語を身につけるたびに、', 'あたらしい げんご お み に つける たび に、', '[{"t":"新","r":"あたら"},{"t":"しい"},{"t":"言語","r":"げんご"},{"t":"を"},{"t":"身","r":"み"},{"t":"に"},{"t":"つける"},{"t":"たびに"},{"t":"、"}]'::jsonb, 'Each time you take on a new language,'),
  ('rdg-ja-n1-language-identity-l19', 'rdg-ja-n1-language-identity', 19, 5, 'もう一人の自分が、生まれるのです。', 'もう ひとり の じぶん が、うまれる の です。', '[{"t":"もう"},{"t":"一人","r":"ひとり"},{"t":"の"},{"t":"自分","r":"じぶん"},{"t":"が"},{"t":"、"},{"t":"生","r":"う"},{"t":"まれる"},{"t":"のです"},{"t":"。"}]'::jsonb, 'one more version of you is born.'),
  ('rdg-ja-n1-language-identity-l20', 'rdg-ja-n1-language-identity', 20, 6, '今、外国の言葉を学んでいる人へ。', 'いま、がいこく の ことば お まなんで いる ひと え。', '[{"t":"今","r":"いま"},{"t":"、"},{"t":"外国","r":"がいこく"},{"t":"の"},{"t":"言葉","r":"ことば"},{"t":"を"},{"t":"学","r":"まな"},{"t":"んで"},{"t":"いる"},{"t":"人","r":"ひと"},{"t":"へ"},{"t":"。"}]'::jsonb, 'To anyone learning a foreign language now,'),
  ('rdg-ja-n1-language-identity-l21', 'rdg-ja-n1-language-identity', 21, 6, '発音が完璧でなくても、構いません。', 'はつおん が かんぺき で なくて も、かまいません。', '[{"t":"発音","r":"はつおん"},{"t":"が"},{"t":"完璧","r":"かんぺき"},{"t":"で"},{"t":"なくて"},{"t":"も"},{"t":"、"},{"t":"構","r":"かま"},{"t":"いません"},{"t":"。"}]'::jsonb, 'It does not matter if your pronunciation is not perfect.'),
  ('rdg-ja-n1-language-identity-l22', 'rdg-ja-n1-language-identity', 22, 6, '不完全な言葉の中にも、あなたらしさは宿ります。', 'ふかんぜん な ことば の なか に も、あなたらしさ わ やどります。', '[{"t":"不完全","r":"ふかんぜん"},{"t":"な"},{"t":"言葉","r":"ことば"},{"t":"の"},{"t":"中","r":"なか"},{"t":"にも"},{"t":"、"},{"t":"あなたらしさ"},{"t":"は"},{"t":"宿","r":"やど"},{"t":"ります"},{"t":"。"}]'::jsonb, 'Even in imperfect speech, who you are shines through.'),
  ('rdg-ja-n1-language-identity-l23', 'rdg-ja-n1-language-identity', 23, 6, 'ありがとうございました。', 'ありがとう ございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you.')
) AS v(id, reading_id, index, stanza, text, reading_kana, furigana, translation)
WHERE EXISTS (SELECT 1 FROM readings WHERE id = 'rdg-ja-n1-language-identity')
ON CONFLICT (reading_id, index) DO NOTHING;

