SELECT 'crq-rdg-ja-n1-language-identity', 'lang-ja', 'readings', 'rdg-ja-n1-language-identity', 'create', '{"code":"n1-language-identity","level":"N1"}'::jsonb, 'ai', 5, 'pending'
