-- N1 · n1-colleague-farewell · A farewell speech for a colleague
INSERT INTO readings (id, language_id, level_id, code, title, title_en, published, sort_index)
SELECT 'rdg-ja-n1-colleague-farewell', 'lang-ja', ll.id, 'n1-colleague-farewell', '同僚への送別の言葉', 'A farewell speech for a colleague', false, 24
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N1'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO reading_lines (id, reading_id, index, stanza, text, reading_kana, furigana, translation)
SELECT v.* FROM (VALUES
  ('rdg-ja-n1-colleague-farewell-l0', 'rdg-ja-n1-colleague-farewell', 0, 0, '皆さん、お忙しい中、お越しくださり、', 'みなさん、おいそがしい なか、おこし くださり、', '[{"t":"皆","r":"みな"},{"t":"さん"},{"t":"、"},{"t":"お"},{"t":"忙","r":"いそが"},{"t":"しい"},{"t":"中","r":"なか"},{"t":"、"},{"t":"お"},{"t":"越","r":"こ"},{"t":"しくださり"},{"t":"、"}]'::jsonb, 'Everyone, for taking time out of your busy day to be here,'),
  ('rdg-ja-n1-colleague-farewell-l1', 'rdg-ja-n1-colleague-farewell', 1, 0, 'ありがとうございます。', 'ありがとう ございます。', '[{"t":"ありがとうございます"},{"t":"。"}]'::jsonb, 'thank you.'),
  ('rdg-ja-n1-colleague-farewell-l2', 'rdg-ja-n1-colleague-farewell', 2, 0, '田中さんに一言、感謝の気持ちを伝えさせてください。', 'たなかさん に ひとこと、かんしゃ の きもち お つたえさせて ください。', '[{"t":"田中","r":"たなか"},{"t":"さん"},{"t":"に"},{"t":"一言","r":"ひとこと"},{"t":"、"},{"t":"感謝","r":"かんしゃ"},{"t":"の"},{"t":"気持","r":"きも"},{"t":"ち"},{"t":"を"},{"t":"伝","r":"つた"},{"t":"えさせてください"},{"t":"。"}]'::jsonb, 'Let me say a few words of thanks to Tanaka-san.'),
  ('rdg-ja-n1-colleague-farewell-l3', 'rdg-ja-n1-colleague-farewell', 3, 1, '田中さんと同じ部署で働いて、八年になります。', 'たなかさん と おなじ ぶしょ で はたらいて、はちねん に なります。', '[{"t":"田中","r":"たなか"},{"t":"さん"},{"t":"と"},{"t":"同","r":"おな"},{"t":"じ"},{"t":"部署","r":"ぶしょ"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"いて"},{"t":"、"},{"t":"八年","r":"はちねん"},{"t":"に"},{"t":"なります"},{"t":"。"}]'::jsonb, 'I have worked in the same department as Tanaka-san for eight years.'),
  ('rdg-ja-n1-colleague-farewell-l4', 'rdg-ja-n1-colleague-farewell', 4, 1, '私が入社した日、最初に声をかけてくれたのが', 'わたし が にゅうしゃ した ひ、さいしょ に こえ お かけて くれた の が', '[{"t":"私","r":"わたし"},{"t":"が"},{"t":"入社","r":"にゅうしゃ"},{"t":"した"},{"t":"日","r":"ひ"},{"t":"、"},{"t":"最初","r":"さいしょ"},{"t":"に"},{"t":"声","r":"こえ"},{"t":"を"},{"t":"かけて"},{"t":"くれた"},{"t":"の"},{"t":"が"}]'::jsonb, 'On the day I joined, the first person to speak to me'),
  ('rdg-ja-n1-colleague-farewell-l5', 'rdg-ja-n1-colleague-farewell', 5, 1, '田中さんでした。', 'たなかさん でした。', '[{"t":"田中","r":"たなか"},{"t":"さん"},{"t":"でした"},{"t":"。"}]'::jsonb, 'was Tanaka-san.'),
  ('rdg-ja-n1-colleague-farewell-l6', 'rdg-ja-n1-colleague-farewell', 6, 2, '仕事に対しては、とても厳しい方でした。', 'しごと に たいして わ、とても きびしい かた でした。', '[{"t":"仕事","r":"しごと"},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"},{"t":"は"},{"t":"、"},{"t":"とても"},{"t":"厳","r":"きび"},{"t":"しい"},{"t":"方","r":"かた"},{"t":"でした"},{"t":"。"}]'::jsonb, 'When it came to work, Tanaka-san was very strict.'),
  ('rdg-ja-n1-colleague-farewell-l7', 'rdg-ja-n1-colleague-farewell', 7, 2, '私の資料は、何度も突き返されました。', 'わたし の しりょう わ、なんど も つきかえされました。', '[{"t":"私","r":"わたし"},{"t":"の"},{"t":"資料","r":"しりょう"},{"t":"は"},{"t":"、"},{"t":"何度","r":"なんど"},{"t":"も"},{"t":"突","r":"つ"},{"t":"き"},{"t":"返","r":"かえ"},{"t":"されました"},{"t":"。"}]'::jsonb, 'My documents were sent back to me many times.'),
  ('rdg-ja-n1-colleague-farewell-l8', 'rdg-ja-n1-colleague-farewell', 8, 2, '当時は辛かったけれど、今では感謝しかありません。', 'とうじ わ つらかった けれど、いま で わ かんしゃ しか ありません。', '[{"t":"当時","r":"とうじ"},{"t":"は"},{"t":"辛","r":"つら"},{"t":"かったけれど"},{"t":"、"},{"t":"今","r":"いま"},{"t":"では"},{"t":"感謝","r":"かんしゃ"},{"t":"しか"},{"t":"ありません"},{"t":"。"}]'::jsonb, 'It was hard then, but now I feel nothing but gratitude.'),
  ('rdg-ja-n1-colleague-farewell-l9', 'rdg-ja-n1-colleague-farewell', 9, 3, '一方で、田中さんは誰よりも優しい人でもありました。', 'いっぽう で、たなかさん わ だれ より も やさしい ひと で も ありました。', '[{"t":"一方","r":"いっぽう"},{"t":"で"},{"t":"、"},{"t":"田中","r":"たなか"},{"t":"さん"},{"t":"は"},{"t":"誰","r":"だれ"},{"t":"より"},{"t":"も"},{"t":"優","r":"やさ"},{"t":"しい"},{"t":"人","r":"ひと"},{"t":"でも"},{"t":"ありました"},{"t":"。"}]'::jsonb, 'At the same time, Tanaka-san was also kinder than anyone.'),
  ('rdg-ja-n1-colleague-farewell-l10', 'rdg-ja-n1-colleague-farewell', 10, 3, '失敗した後輩を、決して責めませんでした。', 'しっぱい した こうはい お、けっして せめません でした。', '[{"t":"失敗","r":"しっぱい"},{"t":"した"},{"t":"後輩","r":"こうはい"},{"t":"を"},{"t":"、"},{"t":"決","r":"けっ"},{"t":"して"},{"t":"責","r":"せ"},{"t":"めませんでした"},{"t":"。"}]'::jsonb, 'Tanaka-san never blamed a junior who had made a mistake.'),
  ('rdg-ja-n1-colleague-farewell-l11', 'rdg-ja-n1-colleague-farewell', 11, 3, '代わりに、黙ってお茶を入れてくれました。', 'かわり に、だまって おちゃ お いれて くれました。', '[{"t":"代","r":"か"},{"t":"わり"},{"t":"に"},{"t":"、"},{"t":"黙","r":"だま"},{"t":"って"},{"t":"お"},{"t":"茶","r":"ちゃ"},{"t":"を"},{"t":"入","r":"い"},{"t":"れて"},{"t":"くれました"},{"t":"。"}]'::jsonb, 'Instead, Tanaka-san quietly made them tea.'),
  ('rdg-ja-n1-colleague-farewell-l12', 'rdg-ja-n1-colleague-farewell', 12, 4, '今も思い出すのは、三年前の大きな仕事です。', 'いま も おもいだす の わ、さんねんまえ の おおきな しごと です。', '[{"t":"今","r":"いま"},{"t":"も"},{"t":"思","r":"おも"},{"t":"い"},{"t":"出","r":"だ"},{"t":"す"},{"t":"の"},{"t":"は"},{"t":"、"},{"t":"三年前","r":"さんねんまえ"},{"t":"の"},{"t":"大","r":"おお"},{"t":"きな"},{"t":"仕事","r":"しごと"},{"t":"です"},{"t":"。"}]'::jsonb, 'What I still recall is a big job three years ago.'),
  ('rdg-ja-n1-colleague-farewell-l13', 'rdg-ja-n1-colleague-farewell', 13, 4, '締め切りの前夜、全員が諦めかけていました。', 'しめきり の ぜんや、ぜんいん が あきらめかけて いました。', '[{"t":"締","r":"し"},{"t":"め"},{"t":"切","r":"き"},{"t":"り"},{"t":"の"},{"t":"前夜","r":"ぜんや"},{"t":"、"},{"t":"全員","r":"ぜんいん"},{"t":"が"},{"t":"諦","r":"あきら"},{"t":"めかけて"},{"t":"いました"},{"t":"。"}]'::jsonb, 'The night before the deadline, everyone was close to giving up.'),
  ('rdg-ja-n1-colleague-farewell-l14', 'rdg-ja-n1-colleague-farewell', 14, 4, 'あのとき、田中さんが笑って言いました。', 'あの とき、たなかさん が わらって いいました。', '[{"t":"あの"},{"t":"とき"},{"t":"、"},{"t":"田中","r":"たなか"},{"t":"さん"},{"t":"が"},{"t":"笑","r":"わら"},{"t":"って"},{"t":"言","r":"い"},{"t":"いました"},{"t":"。"}]'::jsonb, 'Then Tanaka-san smiled and said,'),
  ('rdg-ja-n1-colleague-farewell-l15', 'rdg-ja-n1-colleague-farewell', 15, 4, '「大丈夫、まだ朝まで時間はある」と。', '「だいじょうぶ、まだ あさ まで じかん わ ある」と。', '[{"t":"「"},{"t":"大丈夫","r":"だいじょうぶ"},{"t":"、"},{"t":"まだ"},{"t":"朝","r":"あさ"},{"t":"まで"},{"t":"時間","r":"じかん"},{"t":"は"},{"t":"ある"},{"t":"」"},{"t":"と"},{"t":"。"}]'::jsonb, '"It is fine, we still have until morning."'),
  ('rdg-ja-n1-colleague-farewell-l16', 'rdg-ja-n1-colleague-farewell', 16, 5, 'あの一言で、チームの空気が変わりました。', 'あの ひとこと で、チーム の くうき が かわりました。', '[{"t":"あの"},{"t":"一言","r":"ひとこと"},{"t":"で"},{"t":"、"},{"t":"チーム"},{"t":"の"},{"t":"空気","r":"くうき"},{"t":"が"},{"t":"変","r":"か"},{"t":"わりました"},{"t":"。"}]'::jsonb, 'With that one remark, the whole mood of the team changed.'),
  ('rdg-ja-n1-colleague-farewell-l17', 'rdg-ja-n1-colleague-farewell', 17, 5, '田中さんは、チームの大黒柱でした。', 'たなかさん わ、チーム の だいこくばしら でした。', '[{"t":"田中","r":"たなか"},{"t":"さん"},{"t":"は"},{"t":"、"},{"t":"チーム"},{"t":"の"},{"t":"大黒柱","r":"だいこくばしら"},{"t":"でした"},{"t":"。"}]'::jsonb, 'Tanaka-san was the backbone of this team.'),
  ('rdg-ja-n1-colleague-farewell-l18', 'rdg-ja-n1-colleague-farewell', 18, 6, '新しい土地での生活は、不安も多いでしょう。', 'あたらしい とち で の せいかつ わ、ふあん も おおい でしょう。', '[{"t":"新","r":"あたら"},{"t":"しい"},{"t":"土地","r":"とち"},{"t":"で"},{"t":"の"},{"t":"生活","r":"せいかつ"},{"t":"は"},{"t":"、"},{"t":"不安","r":"ふあん"},{"t":"も"},{"t":"多","r":"おお"},{"t":"い"},{"t":"でしょう"},{"t":"。"}]'::jsonb, 'Life in a new place will surely bring many worries.'),
  ('rdg-ja-n1-colleague-farewell-l19', 'rdg-ja-n1-colleague-farewell', 19, 6, 'けれど、田中さんなら、必ず大丈夫です。', 'けれど、たなかさん なら、かならず だいじょうぶ です。', '[{"t":"けれど"},{"t":"、"},{"t":"田中","r":"たなか"},{"t":"さん"},{"t":"なら"},{"t":"、"},{"t":"必","r":"かなら"},{"t":"ず"},{"t":"大丈夫","r":"だいじょうぶ"},{"t":"です"},{"t":"。"}]'::jsonb, 'But with Tanaka-san, I am sure it will be fine.'),
  ('rdg-ja-n1-colleague-farewell-l20', 'rdg-ja-n1-colleague-farewell', 20, 6, 'どうかお体を大切に。', 'どうか おからだ お たいせつ に。', '[{"t":"どうか"},{"t":"お"},{"t":"体","r":"からだ"},{"t":"を"},{"t":"大切","r":"たいせつ"},{"t":"に"},{"t":"。"}]'::jsonb, 'Please take good care of yourself.'),
  ('rdg-ja-n1-colleague-farewell-l21', 'rdg-ja-n1-colleague-farewell', 21, 7, 'またいつか、一緒に仕事ができる日を、', 'また いつか、いっしょ に しごと が できる ひ お、', '[{"t":"ま"},{"t":"たい"},{"t":"つ"},{"t":"か"},{"t":"、"},{"t":"一緒","r":"いっしょ"},{"t":"に"},{"t":"仕事","r":"しごと"},{"t":"が"},{"t":"できる"},{"t":"日","r":"ひ"},{"t":"を"},{"t":"、"}]'::jsonb, 'The day we can work together again,'),
  ('rdg-ja-n1-colleague-farewell-l22', 'rdg-ja-n1-colleague-farewell', 22, 7, '楽しみにしています。', 'たのしみ に して います。', '[{"t":"楽","r":"たの"},{"t":"しみ"},{"t":"に"},{"t":"して"},{"t":"います"},{"t":"。"}]'::jsonb, 'I look forward to it.'),
  ('rdg-ja-n1-colleague-farewell-l23', 'rdg-ja-n1-colleague-farewell', 23, 7, '長い間、本当にお世話になりました。', 'ながい あいだ、ほんとう に おせわ に なりました。', '[{"t":"長","r":"なが"},{"t":"い"},{"t":"間","r":"あいだ"},{"t":"、"},{"t":"本当","r":"ほんとう"},{"t":"に"},{"t":"お"},{"t":"世話","r":"せわ"},{"t":"に"},{"t":"なりました"},{"t":"。"}]'::jsonb, 'Thank you so much for all your help over the years.'),
  ('rdg-ja-n1-colleague-farewell-l24', 'rdg-ja-n1-colleague-farewell', 24, 7, 'ありがとうございました。', 'ありがとう ございました。', '[{"t":"ありがとうございました"},{"t":"。"}]'::jsonb, 'Thank you very much.')
